[1463] = "Opacità della finestra di anteprima",
-- a625f9d4 English: Choose a whole number of upcoming recommendations, from zero (hidden) to five.
--     The preview shows the current priority results, not a full simulation of future cooldowns or
--     combat. Icons start at 64 pixels; resizing scales all icons while preserving their square
--     shape and the window ratio.
[1464] = "Scegli un numero intero di suggerimenti successivi, da zero (nascosta) a cinque. L'anteprima mostra i risultati di priorità attuali, non una simulazione completa dei tempi di recupero o del combattimento futuri. Le icone partono da 64 pixel; ridimensionare scala tutte le icone mantenendone la forma quadrata e le proporzioni della finestra.",
-- 54b44fb7 English: Arrange preview icons horizontally (default) or vertically. Below the opacity
--     slider, Lock, Direction and Reset share one row.
[1465] = "Disponi le icone dell'anteprima in orizzontale (predefinito) o in verticale. Sotto il cursore dell'opacità, Blocca, Direzione e Reimposta condividono una riga.",
-- 026621d4 English: Immediately return the preview window to the screen center and restore 64-pixel
--     icons without Apply. Other pending settings are preserved.
[1466] = "Riporta subito la finestra di anteprima al centro dello schermo e ripristina le icone a 64 pixel senza Applica. Le altre impostazioni in sospeso vengono conservate.",
-- 10d580ca English: Lock position and size
[1467] = "Blocca posizione e dimensioni",
