[1547] = "Sposta",
-- 9e3bd238 English: Edit fields opens a graphical schema draft. Add, name, reorder or remove
--     fields, choose primitive or nested types, and edit nested fields. Apply stages the schema and
--     its field order. Advanced exposes the equivalent raw schema, parsed as data without executing
--     Lua.
[1548] = "Modifica campi apre una bozza grafica dello schema. Aggiungi, rinomina, riordina o rimuovi campi, scegli tipi primitivi o annidati e modifica i campi annidati. Applica prepara lo schema e l'ordine dei suoi campi. Avanzate mostra lo schema grezzo equivalente, interpretato come dati senza eseguire Lua.",
-- 5ed7c1f2 English: Decide whether this condition currently matches.
[1549] = "Stabilisce se questa condizione è attualmente soddisfatta.",
-- cbb89125 English: The stored values for this condition.
[1550] = "I valori memorizzati per questa condizione.",
-- d02f326b English: Shared data for this evaluation cycle.
[1551] = "Dati condivisi per questo ciclo di valutazione.",
-- 5e32b652 English: Evaluation start time, in seconds from GetTime().
[1552] = "Istante di inizio della valutazione, in secondi da GetTime().",
-- dbb95241 English: True matches; false or nil does not match.
[1553] = "true corrisponde; false o nil non corrisponde.",
