[1566] = "L'identificativo della condizione.",
-- 46569f1f English: No return value is used.
[1567] = "Il valore restituito non viene usato.",
-- 95a1b634 English: Release resources when the condition is removed or replaced.
[1568] = "Rilascia le risorse quando la condizione viene rimossa o sostituita.",
