--     the function source pane.
[1570] = "Valori restituiti",
-- b92993e1 English: Field names are Lua identifiers. Choose a field type from its dropdown. Records
--     contain named fields; allowed types contain alternatives, including nested records.
[1571] = "I nomi dei campi sono identificatori Lua. Scegli il tipo di un campo dal suo menu a tendina. I record contengono campi con nome; i tipi consentiti contengono alternative, inclusi record annidati.",
-- 5f81b556 English: A container carries its nested fields. Drop into a highlighted gap. Up / Down
--     moves within the current container; Duplicate copies the complete field; the red trash can
--     deletes it.
[1572] = "Un contenitore porta con sé i suoi campi annidati. Rilascia in uno spazio evidenziato. Su / Giù sposta all'interno del contenitore attuale; Duplica copia il campo completo; il cestino rosso lo elimina.",
-- d24ed6ad English: The chevron hides or shows nested fields. Add field appends to that container.
--     Undo / Redo affect the draft. Apply validates and stages the schema; Cancel leaves the
--     condition unchanged. Red borders mark invalid names or incomplete types.
[1573] = "La freccia nasconde o mostra i campi annidati. Aggiungi campo aggiunge in fondo a quel contenitore. Annulla / Ripeti agiscono sulla bozza. Applica convalida e prepara lo schema; Annulla lascia invariata la condizione. I bordi rossi indicano nomi non validi o tipi incompleti.",
-- 521fc51f English: Packaged helper from %s.
-- %s #1: %s #1: the file path of the packaged helper, e.g. "Functions/text.lua"
[1574] = "Funzione di supporto inclusa da %s.",
