--     explicit local aliases. Editing an alias does not rewrite your Lua body.
[1591] = "Gli argomenti diventano parametri Lua. Le associazioni espongono le funzioni di supporto selezionate tramite alias locali espliciti. Modificare un alias non riscrive il corpo Lua.",
-- 47b843fc English: New function
[1592] = "Nuova funzione",
