[1593] = "Descrivi cosa fa questa funzione.",
-- 0d646ec9 English: Add a function or duplicate a packaged helper to edit its source.
[1594] = "Aggiungi una funzione o duplica una funzione di supporto inclusa per modificarne il codice sorgente.",
