--     runs this buffer explicitly using the test arguments. It does not replace the saved rotation
--     or live callback.
[1595] = "LuaWorkbench fornisce modifica, completamento, conoscenza delle API e debug. Debug esegue esplicitamente questo buffer usando gli argomenti di test. Non sostituisce la rotazione salvata né la callback attiva.",
-- ac6ddfe4 English: Connected: embedded editing, completion, API knowledge and debugging.
[1596] = "Collegato: modifica integrata, completamento, conoscenza delle API e debug.",
-- e3b56b53 English: Review the dependency bundle before applying it.
[1597] = "Esamina il pacchetto di dipendenze prima di applicarlo.",
