[1963] = "/rm debug timeline [secondi] - Riferisce che cosa la sequenza temporale degli scontri di Retail e Forever offre agli addon.",
-- aca68a8a English: %d rotations from before version 2 are waiting in an archive and do not run
--     until you adopt them. Open Rotation Master, choose Rotations, then Recover unassigned
--     rotations.
-- %d #1: %d #1: how many rotations from before version 2 are waiting in the archive, e.g. 5
[1964] = "%d rotazioni precedenti alla versione 2 sono in attesa in un archivio e non vengono eseguite finché non le adotti. Apri Rotation Master, scegli Rotazioni, poi Recupera rotazioni non assegnate.",
-- a64b8edb English: %d rotations from before version 2 are waiting in an archive and do not run
--     until you adopt them.
-- %d #1: %d #1: how many rotations from before version 2 are waiting in the archive, e.g. 5
[1965] = "%d rotazioni precedenti alla versione 2 sono in attesa in un archivio e non vengono eseguite finché non le adotti.",
-- 48845bff English: Dismiss
-- Context: Button in the banner about unassigned rotations: closes the banner without opening the
--     archive (verb).
[1966] = "Ignora",
-- e11a6591 English: Adopt all %d for %s
-- Context: Button in the recovery window that adopts every listed rotation at once: %d is how many
--     rotations, %s is the destination (a class name or 'This character').
-- %d #1: %d #1: how many unassigned rotations will be adopted, e.g. 5
-- %s #2: %s #2: who will own them, e.g. "your Mage class"
[1967] = "Adotta tutte le %d per %s",
-- c727dc7d English: Adopt all %d from specialization %d for %s
-- %d #1: %d #1: how many rotations of this specialization will be adopted, e.g. 3
-- %d #2: %d #2: the specialization number, e.g. 64
-- %s #3: %s #3: who will own them, e.g. "your Mage class"
[1968] = "Adotta tutte le %d della specializzazione %d per %s",
-- dcf0a82d English: Adopt %d unassigned rotations for %s? Each keeps its identifier. A rotation
--     that cannot be adopted stays in the archive.
-- %d #1: %d #1: how many unassigned rotations will be adopted, e.g. 5
-- %s #2: %s #2: who will own them, e.g. "your Mage class"
[1969] = "Adottare %d rotazioni non assegnate per %s? Ognuna mantiene il proprio identificatore. Una rotazione che non può essere adottata resta nell'archivio.",
-- bf328c9e English: Adopted %d of %d. These stay in the archive: %s
-- %d #1: %d #1: how many rotations were adopted, e.g. 4
-- %d #2: %d #2: how many were attempted, e.g. 5
-- %s #3: %s #3: the names of those that were not adopted, separated by commas, e.g. "Old Fire"
[1970] = "Adottate %d su %d. Queste restano nell'archivio: %s",
-- 23bfc44f English: Player State
-- Context: Condition type title: groups simple player states (mounted, swimming, flying ...). Also
--     an icon name in the icon picker.
[1971] = "Stato del giocatore",
-- 68a2f69b English: Group Count
-- Context: Condition type title: the number of players in the group. Also its help page title.
[1972] = "Conteggio del gruppo",
-- de24e677 English: Eclipse
-- Context: Condition type title: the Druid Eclipse bar. Also its help page title.
[1973] = "Eclissi",
-- 5baf9a05 English: your group's main tank
[1974] = "il tank principale del tuo gruppo",
-- 94585dba English: your group's main tank's
[1975] = "del tank principale del tuo gruppo",
-- 90092817 English: your group's main assist
[1976] = "l'assistente principale del tuo gruppo",
-- 67d03081 English: your group's main assist's
[1977] = "dell'assistente principale del tuo gruppo",
-- 800a1841 English: your group's assigned tank
[1978] = "il difensore assegnato del tuo gruppo",
-- c27b7dbd English: your group's assigned tank's
[1979] = "del difensore assegnato del tuo gruppo",
-- 0a817df6 English: your group's assigned healer
[1980] = "il guaritore assegnato del tuo gruppo",
-- 1f321239 English: your group's assigned healer's
[1981] = "del guaritore assegnato del tuo gruppo",
-- 343dc906 English: your group's leader
-- Context: Phrase for the unit choice 'group leader' in condition summaries, e.g. '<this> {{!is|is
--     not}} your group's leader'; the next string is its possessive form.
[1982] = "il capo del tuo gruppo",
-- 1d3180fa English: your group's leader's
-- Context: Possessive form of 'your group's leader' used in condition summaries before a noun, e.g.
--     'your group's leader's health'.
[1983] = "del capo del tuo gruppo",
-- fad43537 English: Absolute health target (negative means deficit) or percentage fraction.
[1984] = "Salute bersaglio assoluta (un valore negativo indica un deficit) o frazione percentuale.",
-- 29a55788 English: All original results, preserving nil positions and return count.
[1985] = "Tutti i risultati originali, preservando le posizioni nil e il numero di valori restituiti.",
-- c7e69e75 English: Apply the legacy integer or canonical numeric-string spelling test. Numbers use
--     floor equality; strings must equal the spelling obtained after numeric conversion and floor.
--     Other types return false. This is not a finite-number validator.
[1986] = "Applica il test precedente sulla rappresentazione come intero o come stringa numerica canonica. I numeri usano l'uguaglianza dopo floor; le stringhe devono coincidere con la rappresentazione ottenuta dopo la conversione numerica e floor. Gli altri tipi restituiscono false. Non è un validatore di numeri finiti.",
-- 69eb2e21 English: Arguments forwarded unchanged to the observed function.
[1987] = "Argomenti inoltrati invariati alla funzione osservata.",
-- 1d513028 English: Arguments forwarded unchanged; types, identity, arity and nil positions
--     distinguish cache entries.
[1988] = "Argomenti inoltrati invariati; tipi, identità, arità e posizioni nil distinguono le voci della cache.",
-- 3e8d2702 English: Availability or query-validation reason for a nil level observation.
[1989] = "Motivo di indisponibilità o di convalida della query quando l'osservazione del livello è nil.",
-- e2ffe9af English: Availability or query-validation reason for a nil level.
[1990] = "Motivo di indisponibilità o di convalida della query quando il livello è nil.",
-- 66134514 English: Availability or query-validation reason when no current state can be read.
[1991] = "Motivo di indisponibilità o di convalida della query quando non è possibile leggere alcuno stato attuale.",
-- 77b92c6d English: Availability or query-validation reason when the whole observation is
--     unavailable.
[1992] = "Motivo di indisponibilità o di convalida della query quando l'intera osservazione non è disponibile.",
-- 11483c22 English: Availability or validation reason for a nil result.
[1993] = "Motivo di indisponibilità o di convalida quando il risultato è nil.",
-- bd62d347 English: Availability or validation reason when the record is nil.
[1994] = "Motivo di indisponibilità o di convalida quando il record è nil.",
-- cab01ca9 English: Availability or validation reason when the result is nil.
[1995] = "Motivo di indisponibilità o di convalida quando il risultato è nil.",
-- 37cddc45 English: Availability reason for a nil result.
[1996] = "Motivo di indisponibilità quando il risultato è nil.",
-- eced4849 English: Availability reason when resolution fails; nil on success.
[1997] = "Motivo di indisponibilità quando la risoluzione fallisce; nil in caso di successo.",
-- 09403547 English: Cache an observation after it returns a non-nil value; retry observations whose
--     entire return tuple is nil. Uses the same exact argument keys as getCached.
[1998] = "Memorizza in cache un'osservazione dopo che ha restituito un valore non nil; ritenta le osservazioni la cui intera tupla restituita è nil. Usa le stesse chiavi esatte di argomenti di getCached.",
-- ec80f70e English: Calculate a checked health-history rate using an explicit finite window and
--     clock. Preserve ordered weighting, per-row live canonical rounding, skipped streams, array
--     holes, fractional keys and final visited ages. A fixed 4096-unit budget covers visited rows
--     and accumulation bins across both streams; excess or invalid consumed arithmetic returns
--     unavailable, never a partial estimate or clamp. This new API has its own source identity;
--     historical trend functions remain unchanged.
[1999] = "Calcola un tasso verificato dalla cronologia della salute usando una finestra e un orologio finiti ed espliciti. Preserva la ponderazione ordinata, l'arrotondamento canonico attuale per riga, i flussi saltati, i buchi negli array, le chiavi frazionarie e le età finali visitate. Un budget fisso di 4096 unità copre le righe visitate e i contenitori di accumulo in entrambi i flussi; un'aritmetica consumata eccessiva o non valida restituisce non disponibile, mai una stima parziale o un valore limitato. Questa nuova API ha una propria identità di origine; le funzioni storiche di tendenza restano invariate.",
-- e3a904cc English: Call an observation once per cache and exact argument tuple, including nil
--     results. Pass the evaluation cache to share observations within a recommendation cycle; nil
--     cache calls directly.
[2000] = "Chiama un'osservazione una sola volta per cache e per tupla esatta di argomenti, inclusi i risultati nil. Passa la cache di valutazione per condividere le osservazioni all'interno di un ciclo di raccomandazione; con cache nil la chiamata avviene direttamente.",
-- cb8a709c English: Callback invoked after changing the selected unit.
[2001] = "Callback richiamata dopo la modifica dell'unità selezionata.",
-- f4755bc2 English: Callback receiving the committed spell value.
[2002] = "Callback che riceve il valore dell'incantesimo confermato.",
-- 8473e032 English: Caller-owned evaluation observation cache; nil queries afresh.
[2003] = "Cache delle osservazioni della valutazione posseduta dal chiamante; con nil esegue nuove query.",
-- d07ec966 English: Capability or clock observation availability reason.
[2004] = "Motivo di indisponibilità della funzionalità o dell'osservazione dell'orologio.",
-- aca2f51b English: Capability or observation availability reason for a nil class.
[2005] = "Motivo di indisponibilità della funzionalità o dell'osservazione quando la classe è nil.",
-- fb8dd5ac English: Check whether a spell can be recommended now, allowing a spell whose remaining
--     cooldown ends with the current global cooldown. On Retail and Forever, where cooldown times
--     are secret in combat, readiness comes from the never-secret isEnabled, isActive and isOnGCD
--     flags instead. This checks cooldown readiness only; it does not check learned status, range
--     or resource usability. Pass evaluation time from evalStart or GetTime().
[2006] = "Verifica se un incantesimo può essere consigliato ora, ammettendo un incantesimo il cui tempo di recupero residuo termina con il tempo di recupero globale in corso. Su Retail e Forever, dove i tempi di recupero sono segreti in combattimento, la disponibilità deriva invece dai flag isEnabled, isActive e isOnGCD, che non sono mai segreti. Verifica solo la disponibilità rispetto al tempo di recupero; non verifica se l'incantesimo è appreso, la portata o la disponibilità di risorse. Passa il tempo di valutazione da evalStart o GetTime().",
-- 1081f5fc English: Check whether a table has a non-nil value at a key. A stored false value still
--     counts as present; this does not scan table values.
[2007] = "Controlla se una tabella ha un valore non nil in corrispondenza di una chiave. Un valore false memorizzato conta comunque come presente; non esamina i valori della tabella.",
-- 3f1a5911 English: Checkbox widget with boolean value and callback methods.
[2008] = "Widget casella di controllo con valore booleano e metodi di callback.",
-- 8373609b English: Choose the supplied player value only for the literal player unit token; every
--     other unit selects the nonplayer value. Selected false and nil values are preserved.
[2009] = "Sceglie il valore fornito per il giocatore solo per l'identificativo unità letterale player; ogni altra unità seleziona il valore per i non giocatori. I valori false e nil selezionati vengono preservati.",
-- 68e9defe English: Classification, validation or availability reason for a nil result.
[2010] = "Motivo di classificazione, di convalida o di indisponibilità quando il risultato è nil.",
-- 7fc7159a English: Classify a numeric item as a glyph for the requested class, using guarded
--     native item metadata. Class is optional and defaults to the readable player class. This
--     establishes item classification only, not equipped status or an item-to-glyph-spell ID
--     mapping.
[2011] = "Classifica un oggetto numerico come glifo per la classe richiesta, usando in modo protetto i metadati nativi dell'oggetto. La classe è facoltativa e per impostazione predefinita è la classe leggibile del giocatore. Stabilisce solo la classificazione dell'oggetto, non lo stato di equipaggiamento né una corrispondenza tra ID dell'oggetto e ID dell'incantesimo del glifo.",
-- 355b4c25 English: Client-family, query-validation or required-observation availability reason for
--     a nil result.
[2012] = "Motivo di famiglia del client, di convalida della query o di indisponibilità di un'osservazione richiesta quando il risultato è nil.",
-- 56d0a810 English: Client-policy, capability, call or observation availability reason for a nil
--     form.
[2013] = "Motivo di policy del client, di funzionalità, di chiamata o di indisponibilità dell'osservazione quando la forma è nil.",
-- fffddfca English: Client-policy, capability, call or observation availability reason for a nil
--     record.
[2014] = "Motivo di policy del client, di funzionalità, di chiamata o di indisponibilità dell'osservazione quando il record è nil.",
-- 7a0f627b English: Client-policy, native-call or required membership availability reason for a nil
--     record.
[2015] = "Motivo di policy del client, di chiamata nativa o di indisponibilità dell'appartenenza richiesta quando il record è nil.",
-- 0a8d99a6 English: Closed kind: runner, resist or immune.
[2016] = "Tipo chiuso: runner, resist o immune.",
-- 6999f76c English: Closed scalar kind: current or maximum.
[2017] = "Tipo scalare chiuso: current o maximum.",
-- a7224c57 English: Collect table keys and sort them by their associated values using Lua less-than
--     comparison. This sorts values rather than key names; equal values have no guaranteed key
--     order.
[2018] = "Raccoglie le chiavi della tabella e le ordina in base ai valori associati usando il confronto minore-di di Lua. Ordina i valori anziché i nomi delle chiavi; a parità di valore l'ordine delle chiavi non è garantito.",
-- 508c105b English: Combat-policy, capability, observation or scan-budget reason for a nil count.
[2019] = "Motivo di policy di combattimento, di funzionalità, di osservazione o di budget di scansione quando il conteggio è nil.",
-- 14b9d8a2 English: Combined signed weighted rate from the original formula; malformed or nonfinite
--     inputs retain the legacy error/numeric behavior.
[2020] = "Tasso ponderato combinato con segno, dalla formula originale; gli input malformati o non finiti mantengono il comportamento precedente di errore/numerico.",
-- ee842735 English: Compare the selected unit creature ID with one existing saved creature-type
--     key. Resolve the fixed key-to-ID identity in one private executable mapper; gameplay matching
--     does not depend on the mutable localized UI caption map. Share complete native observations
--     within the supplied evaluation-pass cache by actual observer, receiver and unit, including
--     absence and unavailable reasons. Known absence or a known different ID returns false; an
--     unavailable required observation returns nil with a reason. No longterm state or caption
--     mutation is added.
[2021] = "Confronta l'ID creatura dell'unità selezionata con una chiave di tipo di creatura salvata esistente. Risolve l'identità fissa chiave-ID in un unico mappatore eseguibile privato; la corrispondenza in gioco non dipende dalla mappa modificabile delle didascalie localizzate dell'interfaccia. Condivide le osservazioni native complete nella cache del passaggio di valutazione fornita, per osservatore, ricevente e unità effettivi, inclusi l'assenza e i motivi di indisponibilità. Un'assenza accertata o un ID diverso accertato restituisce false; un'osservazione richiesta non disponibile restituisce nil con un motivo. Non vengono aggiunti stati a lungo termine né modifiche alle didascalie.",
-- 098e89f6 English: Compare two exact unit tokens using UnitIsUnit after checking only the first
--     token with UnitExists. A readable absent first unit returns false without comparing. Required
--     missing, failed, restricted or malformed observations return nil with a reason. No second
--     existence query, GUID lookup or inferred identity is added.
[2022] = "Confronta due identificativi unità esatti usando UnitIsUnit, dopo aver verificato con UnitExists solo il primo. Se la prima unità è leggibile ma assente restituisce false senza confrontare. Osservazioni richieste mancanti, fallite, soggette a restrizioni o malformate restituiscono nil con un motivo. Non vengono aggiunte una seconda query di esistenza, una ricerca del GUID o un'identità dedotta.",
-- f92fafbd English: Compare two values using an RM operator identifier: LESSTHAN, LESSTHANOREQUALS,
--     GREATERTHAN, GREATERTHANOREQUALS, EQUALS, NOTEQUALS or DIVISIBLE. Invalid operators warn and
--     return nil; operands must support the selected Lua operation.
[2023] = "Confronta due valori usando un identificativo di operatore RM: LESSTHAN, LESSTHANOREQUALS, GREATERTHAN, GREATERTHANOREQUALS, EQUALS, NOTEQUALS o DIVISIBLE. Gli operatori non validi generano un avviso e restituiscono nil; gli operandi devono supportare l'operazione Lua selezionata.",
-- 4d1da429 English: Comparison operator key, such as EQUALS or LESSTHAN.
[2024] = "Chiave dell'operatore di confronto, ad esempio EQUALS o LESSTHAN.",
-- 8d6dc0da English: Comparison result, or nil for an unknown operator.
[2025] = "Risultato del confronto, oppure nil per un operatore sconosciuto.",
-- 45e7a5a6 English: Comparison text retaining named Boolean alternative markup.
[2026] = "Testo del confronto che mantiene il markup delle alternative booleane con nome.",
-- beb1fd9a English: Complete matching class count, including zero, or nil when unavailable.
[2027] = "Conteggio completo delle classi corrispondenti, zero incluso, oppure nil se non disponibile.",
-- 3abb0dce English: Complete nonnegative observed count including zero, or nil when unavailable.
[2028] = "Conteggio osservato completo e non negativo, zero incluso, oppure nil se non disponibile.",
-- a3cbc46a English: Condition container supporting SetLayout, AddChild, SetUserData, SetWidth and
--     DoLayout.
[2029] = "Contenitore di condizioni che supporta SetLayout, AddChild, SetUserData, SetWidth e DoLayout.",
-- 1edda05a English: Condition value record containing spell, ranked and disabled fields; updated in
--     place.
[2030] = "Record del valore della condizione contenente i campi spell, ranked e disabled; aggiornato sul posto.",
-- bd948209 English: Condition value record updated when a unit is chosen.
[2031] = "Record del valore della condizione aggiornato quando viene scelta un'unità.",
-- 49082497 English: Configured unit selector; add it with parent:AddChild(widget).
[2032] = "Selettore di unità configurato; aggiungilo con parent:AddChild(widget).",
-- 93e87554 English: Copy a table using tostring of each original key as the destination key. Values
--     retain their original identities. Colliding stringified keys overwrite each other in
--     unspecified pairs traversal order.
[2033] = "Copia una tabella usando tostring di ogni chiave originale come chiave di destinazione. I valori mantengono le loro identità originali. Le chiavi convertite in stringa che collidono si sovrascrivono a vicenda, nell'ordine non specificato di attraversamento di pairs.",
-- dcd01801 English: Count all entries visited by pairs, including false values and sparse numeric
--     or nonnumeric keys. A nil table has length zero.
[2034] = "Conta tutte le voci visitate da pairs, inclusi i valori false e le chiavi numeriche sparse o non numeriche. Una tabella nil ha lunghezza zero.",
-- 7ee6eac7 English: Count matching class tokens in the current fixed roster. Read group membership
--     first; when requested, raid membership selects raid1 through raid40 without a separate player
--     fact. Solo and party paths read player first, then party1 through party4 when grouped. A
--     complete known roster returns a count, including zero; any required unavailable fact returns
--     nil with a reason. Complete observations share the evaluation-pass cache; no player class
--     persists across passes. Archived raw callbacks retain their original load-time class
--     separately.
[2035] = "Conta gli identificativi di classe corrispondenti nell'elenco fisso attuale dei membri. Legge prima l'appartenenza al gruppo; se richiesto, l'appartenenza a un'incursione seleziona da raid1 a raid40 senza un dato separato sul giocatore. I percorsi in solitario e in gruppo leggono prima player, poi da party1 a party4 se sei in gruppo. Un elenco dei membri completo e noto restituisce un conteggio, zero incluso; qualsiasi dato richiesto non disponibile restituisce nil con un motivo. Le osservazioni complete condividono la cache del passaggio di valutazione; nessuna classe del giocatore persiste tra un passaggio e l'altro. Le callback grezze archiviate mantengono separatamente la classe originale del momento del caricamento.",
-- ddfd3a7c English: Count only GUID-keyed units already in the observed membership snapshot. Verify
--     current token identity before using the published threat observer; known absent or reused
--     tokens are excluded without adding replacements. Complete identity and threat observations
--     share only the supplied evaluation cache, while membership is traversed fresh. Known nonenemy
--     or optional nil threat is not counted; required unreadable, malformed or failed facts make
--     the entire result unavailable. This does not enumerate a complete roster, apply a range
--     filter or modify tracked records.
[2036] = "Conta solo le unità indicizzate per GUID già presenti nell'istantanea dei membri osservata. Verifica l'identità attuale dell'identificativo prima di usare l'osservatore della minaccia pubblicato; gli identificativi accertati come assenti o riutilizzati vengono esclusi senza aggiungere sostituti. Le osservazioni complete di identità e minaccia condividono solo la cache di valutazione fornita, mentre l'appartenenza viene percorsa da capo. Una unità accertata come non nemica o una minaccia nil facoltativa non viene contata; dati richiesti illeggibili, malformati o falliti rendono non disponibile l'intero risultato. Non enumera un elenco completo dei membri, non applica un filtro di distanza e non modifica i record tracciati.",
-- 02e149c6 English: Create a condition field container with RM-owned List, Table and responsive
--     spell-field layouts. It accepts registered native condition widgets; add children with
--     AddChild and attach the group to the callback parent.
[2037] = "Crea un contenitore di campi di condizione con layout List, Table e campi incantesimo adattivi gestiti da RM. Accetta i widget di condizione nativi registrati; aggiungi i figli con AddChild e collega il gruppo al genitore della callback.",
-- 24b26357 English: Create a configured unit selector bound to a condition value record. Returns
--     the widget for the caller to add to the condition callback parent.
[2038] = "Crea un selettore di unità configurato, associato a un record del valore della condizione. Restituisce il widget, che il chiamante aggiunge al genitore della callback della condizione.",
-- 704feebd English: Create a native boolean condition control. Configure SetLabel, SetValue,
--     SetDisabled and OnValueChanged; add it with parent:AddChild(widget).
[2039] = "Crea un controllo booleano nativo per le condizioni. Configura SetLabel, SetValue, SetDisabled e OnValueChanged; aggiungilo con parent:AddChild(widget).",
-- d67fc3b8 English: Create a native button using the shared condition widget lifecycle and
--     workbench theme. SetText, SetDisabled and SetCallback configure its label and interaction;
--     OnClick receives the mouse button. Add it to the callback parent with
--     parent:AddChild(widget).
[2040] = "Crea un pulsante nativo usando il ciclo di vita condiviso dei widget di condizione e il tema del workbench. SetText, SetDisabled e SetCallback ne configurano l'etichetta e l'interazione; OnClick riceve il pulsante del mouse. Aggiungilo al genitore della callback con parent:AddChild(widget).",
-- d4341110 English: Create a native condition selector. SetList accepts key-to-label or
--     key-to-entry maps; SetValue selects a key and OnValueChanged reports changes. Add it with
--     parent:AddChild(widget).
[2041] = "Crea un selettore nativo per le condizioni. SetList accetta mappe da chiave a etichetta o da chiave a voce; SetValue seleziona una chiave e OnValueChanged segnala le modifiche. Aggiungilo con parent:AddChild(widget).",
-- e149229e English: Create a native image control using the condition widget lifecycle. SetImage
--     and SetImageSize choose the texture; SetText optionally adds a caption. OnClick, OnEnter and
--     OnLeave use the shared callback contract. Add the control to the callback parent with
--     parent:AddChild(widget).
[2042] = "Crea un controllo immagine nativo usando il ciclo di vita dei widget di condizione. SetImage e SetImageSize scelgono la texture; SetText aggiunge facoltativamente una didascalia. OnClick, OnEnter e OnLeave usano il contratto condiviso delle callback. Aggiungi il controllo al genitore della callback con parent:AddChild(widget).",
-- b943d164 English: Create a native numeric condition input with a slider and typed numeric field.
--     Configure SetSliderValues, SetValue, SetIsPercent and SetCallback; OnValueChanged reports
--     committed values. Add it with parent:AddChild(widget).
[2043] = "Crea un campo numerico nativo per le condizioni, con un cursore e un campo numerico digitabile. Configura SetSliderValues, SetValue, SetIsPercent e SetCallback; OnValueChanged segnala i valori confermati. Aggiungilo con parent:AddChild(widget).",
-- a67c621c English: Create a native position pad using the shared directional controls.
--     OnOffsetChanged reports horizontal and vertical direction, whether Center was pressed, and
--     the increment (one, or ten with Shift). SetDisabled controls interaction; add the pad to the
--     callback parent with parent:AddChild(widget).
[2044] = "Crea un pad di posizionamento nativo usando i controlli direzionali condivisi. OnOffsetChanged segnala la direzione orizzontale e verticale, se è stato premuto Centro e l'incremento (uno, oppure dieci con Maiusc). SetDisabled controlla l'interazione; aggiungi il pad al genitore della callback con parent:AddChild(widget).",
-- 25defe9e English: Create a native text input using the condition widget contract. SetLabel,
--     SetText, SetDisabled and SetCallback configure it; OnEnterPressed commits text. Add it to the
--     callback parent with parent:AddChild(widget).
[2045] = "Crea un campo di testo nativo usando il contratto dei widget di condizione. SetLabel, SetText, SetDisabled e SetCallback lo configurano; OnEnterPressed conferma il testo. Aggiungilo al genitore della callback con parent:AddChild(widget).",
-- edff3bd0 English: Create a shallow filtered copy despite the historical deepcopy name. Nested
--     values retain their original identities and the source metatable is not copied. By default
--     exclude keys listed among except values; invert true includes only listed keys. Nil input
--     returns nil.
[2046] = "Crea una copia superficiale filtrata, nonostante il nome storico deepcopy. I valori annidati mantengono le loro identità originali e la metatabella di origine non viene copiata. Per impostazione predefinita esclude le chiavi elencate tra i valori di except; con invert true include solo le chiavi elencate. Un input nil restituisce nil.",
-- ccc11c66 English: Create a spell input with suggestions, validation and spell-link support for
--     custom condition widgets. The update callback owns saving a chosen value; add the returned
--     widget to the callback parent.
[2047] = "Crea un campo per incantesimi con suggerimenti, convalida e supporto ai link degli incantesimi per i widget delle condizioni personalizzate. La callback di aggiornamento si occupa di salvare il valore scelto; aggiungi il widget restituito al genitore della callback.",
-- 4736bce4 English: Create a transient named condition summary. Use {name} for scalar values and
--     {{positive|negative}} for predicate alternatives; prefix a primary alternative with !. Escape
--     literal double braces as {{{{ and }}}}. Values are inserted literally without parsing their
--     percent signs, links, colors or braces. Typed predicate values participate in primary
--     selection. Templates, values and rendered text are bounded; malformed input renders a
--     localized unavailable summary. This changes presentation only and runs no condition
--     observations.
[2048] = "Crea un riepilogo temporaneo della condizione con nome. Usa {name} per i valori scalari e {{positivo|negativo}} per le alternative dei predicati; anteponi ! a un'alternativa primaria. Per le doppie graffe letterali usa l'escape {{{{ e }}}}. I valori vengono inseriti letteralmente, senza interpretarne segni di percentuale, link, colori o graffe. I valori dei predicati tipizzati partecipano alla selezione primaria. Modelli, valori e testo generato hanno limiti di dimensione; un input malformato genera un riepilogo localizzato di non disponibilità. Modifica solo la presentazione e non esegue alcuna osservazione delle condizioni.",
-- 7735b638 English: Create a typed comparison predicate for a named condition phrase. Positive
--     wording uses the original captured operator map and negative wording uses the current negated
--     operator map. A primary predicate takes precedence over qualifiers; only the first eligible
--     predicate negates. Unknown operators use the existing operator placeholder. This formats
--     wording without comparing values or evaluating a condition.
[2049] = "Crea un predicato di confronto tipizzato per una frase di condizione con nome. La formulazione positiva usa la mappa degli operatori originale acquisita e quella negativa usa la mappa attuale degli operatori negati. Un predicato primario ha la precedenza sui qualificatori; solo il primo predicato idoneo viene negato. Gli operatori sconosciuti usano il segnaposto di operatore esistente. Formatta la formulazione senza confrontare valori né valutare una condizione.",
-- ddea308b English: Create an iterator over a sorted snapshot of table keys. Default ordering
--     compares keys; a custom order callback receives the original table and two keys. Values are
--     read from the original table when each key is yielded. The legacy iterator ends when the next
--     captured key is nil or false.
[2050] = "Crea un iteratore su un'istantanea ordinata delle chiavi della tabella. L'ordinamento predefinito confronta le chiavi; una callback di ordinamento personalizzata riceve la tabella originale e due chiavi. I valori vengono letti dalla tabella originale quando ciascuna chiave viene restituita. L'iteratore precedente termina quando la successiva chiave acquisita è nil o false.",
-- 629b2567 English: Create native wrapping text that measures its height from its width and font.
--     SetText, SetFont or SetFontObject configure its contents. Add it to the callback parent with
--     parent:AddChild(widget) so layout can track its measured height.
[2051] = "Crea un testo nativo a capo automatico che misura la propria altezza in base a larghezza e carattere. SetText, SetFont o SetFontObject ne configurano il contenuto. Aggiungilo al genitore della callback con parent:AddChild(widget) affinché il layout possa tenere conto dell'altezza misurata.",
-- c58c9a9a English: Create native wrapping text with optional leading image and pointer callbacks.
--     SetImage and SetImageSize configure the image; OnEnter, OnLeave and OnClick use the condition
--     callback contract. Add it to the callback parent with parent:AddChild(widget); callbacks
--     expire when its lease is released.
[2052] = "Crea un testo nativo a capo automatico con immagine iniziale facoltativa e callback del puntatore. SetImage e SetImageSize configurano l'immagine; OnEnter, OnLeave e OnClick usano il contratto delle callback delle condizioni. Aggiungilo al genitore della callback con parent:AddChild(widget); le callback scadono quando la sua concessione viene rilasciata.",
-- fa988d31 English: Current evaluation time in seconds from GetTime(), normally evalStart.
[2053] = "Tempo di valutazione attuale in secondi da GetTime(), di norma evalStart.",
-- c7fd7453 English: Current positive visibility distance in yards; nil when unavailable.
[2054] = "Distanza di visibilità positiva attuale in metri; nil se non disponibile.",
-- 574eed72 English: Current unit token whose distance from the player should be observed.
[2055] = "Identificativo unità attuale di cui osservare la distanza dal giocatore.",
-- 83a1023e English: Damage/heals arrays of time/value rows; only selected streams are consumed.
[2056] = "Array damage/heals di righe tempo/valore; vengono consumati solo i flussi selezionati.",
-- 38e0b44b English: Decimal places, default zero; negative values round to tens or larger powers of
--     ten.
[2057] = "Numero di decimali, predefinito zero; i valori negativi arrotondano alle decine o a potenze di dieci superiori.",
-- c1094708 English: Dense array of keys sorted by associated value.
[2058] = "Array denso di chiavi ordinate in base al valore associato.",
-- 7de55bf4 English: Dense array of nonempty text fields.
[2059] = "Array denso di campi di testo non vuoti.",
-- ba17b32f English: Destination array modified in place.
[2060] = "Array di destinazione modificato sul posto.",
-- 9d65688a English: Display lookup table.
[2061] = "Tabella di ricerca da visualizzare.",
-- 763bf095 English: Estimate signed health change from weighted damage and healing history. Damage
--     contributes a negative rate and healing a positive rate. Read the live profile window when no
--     window is supplied, use the live clock and legacy rounding service, and preserve the existing
--     weighting and rounded-age calculation. This helper does not validate or sanitize history,
--     clamp timestamps, or guarantee finite results.
[2062] = "Stima la variazione di salute con segno dalla cronologia ponderata di danni e cure. I danni contribuiscono con un tasso negativo e le cure con un tasso positivo. Legge la finestra attuale del profilo quando non viene fornita una finestra, usa l'orologio attuale e il servizio di arrotondamento precedente, e preserva la ponderazione esistente e il calcolo dell'età arrotondata. Questa funzione di supporto non convalida né pulisce la cronologia, non limita i timestamp e non garantisce risultati finiti.",
-- c95e98a7 English: Estimate time until selected health. Cache complete native identity and lazy
--     scalar observations per evaluation pass, while provider, history, window, clock and forecast
--     stay live. Exact target equality returns zero before history work. Preserve deliberate
--     no-estimate false and initialized-zero results for zero or opposite rates; required invalid
--     facts, overflow or 4096-unit work exhaustion are unavailable. Never mutate history or invent
--     a partial estimate.
[2063] = "Stima il tempo necessario per raggiungere la salute selezionata. Memorizza in cache per passaggio di valutazione le osservazioni native complete dell'identità e quelle scalari pigre, mentre fornitore, cronologia, finestra, orologio e previsione restano in tempo reale. Se il bersaglio coincide esattamente restituisce zero prima di elaborare la cronologia. Preserva il risultato false intenzionale di nessuna stima e quello zero inizializzato per tassi nulli o opposti; dati richiesti non validi, overflow o esaurimento del lavoro di 4096 unità risultano non disponibili. Non modifica mai la cronologia e non inventa stime parziali.",
-- 52a17c6c English: Evaluation cache, or nil to bypass caching.
[2064] = "Cache di valutazione, oppure nil per non usare la cache.",
-- 79697e3a English: Evaluation-pass cache for complete unit observations; nil observes directly.
--     Different selected keys reuse the same unit snapshot.
[2065] = "Cache del passaggio di valutazione per le osservazioni complete dell'unità; con nil osserva direttamente. Chiavi selezionate diverse riutilizzano la stessa istantanea dell'unità.",
-- bd88f3f9 English: Evaluation-pass cache, or nil for fresh observations.
[2066] = "Cache del passaggio di valutazione, oppure nil per osservazioni nuove.",
-- d022fab6 English: Evaluation-pass cache, or nil to observe identity directly. Resource mapping is
--     resolved live on each invocation.
[2067] = "Cache del passaggio di valutazione, oppure nil per osservare direttamente l'identità. La corrispondenza delle risorse viene risolta in tempo reale a ogni chiamata.",
-- 0900784b English: Evaluation-pass cache, or nil to observe identity directly. Successful player
--     class observations may use the existing longterm identity cache; resource mapping remains
--     live.
[2068] = "Cache del passaggio di valutazione, oppure nil per osservare direttamente l'identità. Le osservazioni riuscite della classe del giocatore possono usare la cache esistente dell'identità a lungo termine; la corrispondenza delle risorse resta in tempo reale.",
-- 383aa43c English: Evaluation-pass native observation cache; nil queries afresh.
[2069] = "Cache delle osservazioni native del passaggio di valutazione; con nil esegue nuove query.",
-- bf9ecd5c English: Evaluation-pass presence cache only; name, level and provider history remain
--     fresh.
[2070] = "Cache solo della presenza per il passaggio di valutazione; nome, livello e cronologia del fornitore vengono sempre riletti.",
-- 2dbf0453 English: Exact helper-owned player, party1..party4 or raid1..raid40 token.
[2071] = "Identificativo esatto gestito dalla funzione di supporto: player, da party1 a party4 o da raid1 a raid40.",
-- 27bda267 English: Exact integral native rune slot from 1 through 6.
[2072] = "Slot di runa nativo esatto e intero, da 1 a 6.",
-- 4fc2d3d1 English: Exact nonempty unit token to observe.
[2073] = "Identificativo unità esatto e non vuoto da osservare.",
-- c590f11f English: Exact nonempty unit token, passed unchanged.
[2074] = "Identificativo unità esatto e non vuoto, passato invariato.",
-- fd8065c0 English: Exact readable recipient name recorded for this cast.
[2075] = "Nome esatto e leggibile del destinatario registrato per questo lancio.",
-- b05cf3b2 English: Exact selected unit token; only the literal player token may select the TBC
--     combo transport.
[2076] = "Identificativo esatto dell'unità selezionata; solo l'identificativo letterale player può selezionare il trasporto dei punti combo di TBC.",
-- 19306e82 English: Exact selected unit token; player class alone may use the successful longterm
--     cache.
[2077] = "Identificativo esatto dell'unità selezionata; solo la classe del giocatore può usare la cache a lungo termine dei risultati riusciti.",
-- af7eabaa English: Exact selected unit token; the attacker remains player.
[2078] = "Identificativo esatto dell'unità selezionata; l'attaccante resta player.",
-- c08ce58e English: Exact unit token checked for existence and passed to the selected metadata API.
[2079] = "Identificativo unità esatto, di cui si verifica l'esistenza, passato all'API di metadati selezionata.",
-- eb750dcd English: Exact unit token passed unchanged to UnitExists and, when required, UnitClass.
[2080] = "Identificativo unità esatto passato invariato a UnitExists e, se necessario, a UnitClass.",
-- 3641c328 English: Exact unit token used for existence and as the recipient of player hostility
--     and threat queries.
[2081] = "Identificativo unità esatto usato per l'esistenza e come destinatario delle query di ostilità e minaccia del giocatore.",
-- 616ee642 English: Exact unit token whose resource should be observed; this does not redirect
--     player or vehicle units.
[2082] = "Identificativo esatto dell'unità di cui osservare la risorsa; non reindirizza le unità del giocatore o dei veicoli.",
-- f89b30c5 English: Exact unit token whose selected flag should be observed.
[2083] = "Identificativo esatto dell'unità di cui osservare l'indicatore selezionato.",
-- bb716e79 English: Exact unit token whose selected resource quantity is requested.
[2084] = "Identificativo esatto dell'unità di cui si richiede la quantità della risorsa selezionata.",
-- d07d5f8c English: Exactly current for UnitPower or maximum for UnitPowerMax.
[2085] = "Esattamente current per UnitPower o maximum per UnitPowerMax.",
-- 3234a7b8 English: Exactly current for UnitPower or maximum for UnitPowerMax; no other native
--     query is added.
[2086] = "Esattamente current per UnitPower o maximum per UnitPowerMax; non viene aggiunta alcuna altra query nativa.",
-- ce5b4817 English: Exactly current for the player/target combo query or maximum for the player
--     capacity query.
[2087] = "Esattamente current per la query dei punti combo player/target o maximum per la query della capacità del giocatore.",
-- 01112dbd English: Exactly dead for UnitIsDeadOrGhost, or friendly for UnitIsFriend(player, unit).
[2088] = "Esattamente dead per UnitIsDeadOrGhost, oppure friendly per UnitIsFriend(player, unit).",
-- 572b3dd2 English: Exactly type or school; selects the required subject field without requiring
--     the other.
[2089] = "Esattamente type o school; seleziona il campo del soggetto richiesto senza richiedere l'altro.",
-- 618e2637 English: Existing stored CREATURE key: BEAST, DRAGONKIN, DEMON, ELEMENTAL, GIANT,
--     UNDEAD, HUMANOID, CRITTER, MECHANICAL, OTHER, TOTEM, NONCOMBAT_PET or GAS_CLUUD.
[2090] = "Chiave CREATURE memorizzata esistente: BEAST, DRAGONKIN, DEMON, ELEMENTAL, GIANT, UNDEAD, HUMANOID, CRITTER, MECHANICAL, OTHER, TOTEM, NONCOMBAT_PET o GAS_CLUUD.",
-- 93af5992 English: Explicit finite clock snapshot; signed and fractional values remain valid.
[2091] = "Istantanea esplicita e finita dell'orologio; i valori con segno e frazionari restano validi.",
-- b6d72a06 English: Explicit finite weighting window; no profile fallback or clamp.
[2092] = "Finestra di ponderazione esplicita e finita; nessun ripiego sul profilo né limitazione.",
-- 8775b9a4 English: Explicit nonnegative integer power selector, false for a known absent unit, or
--     nil when required data is unavailable.
[2093] = "Selettore di risorsa esplicito intero non negativo, false per un'unità accertata come assente, oppure nil quando i dati richiesti non sono disponibili.",
-- 593273d6 English: Explicit nonnegative integer selector, false for known unit absence, or nil
--     when required data is unavailable.
[2094] = "Selettore esplicito intero non negativo, false per un'unità accertata come assente, oppure nil quando i dati richiesti non sono disponibili.",
-- 18dcc116 English: Explicit readable finite nonnegative integer power selector, including zero.
[2095] = "Selettore di risorsa esplicito, leggibile, finito, intero e non negativo, zero incluso.",
-- 4cb2bf6f English: Explicit readable finite nonnegative integer power selector.
[2096] = "Selettore di risorsa esplicito, leggibile, finito, intero e non negativo.",
-- cdbf6c56 English: Finite ETA including zero, false for known absence/no estimate, or nil when
--     unavailable.
[2097] = "Tempo stimato finito, zero incluso, false per assenza accertata/nessuna stima, oppure nil se non disponibile.",
-- a4382b09 English: Finite final stream age, or nil when unavailable.
[2098] = "Età finale finita del flusso, oppure nil se non disponibile.",
-- 84e16e8d English: Finite minimum native threat status, preserving signed and fractional
--     thresholds.
[2099] = "Stato di minaccia nativo minimo finito, che preserva soglie con segno e frazionarie.",
-- 7e3a2158 English: Finite native creature ID, false for known unit absence, or nil when required
--     observations are unavailable.
[2100] = "ID creatura nativo finito, false per un'unità accertata come assente, oppure nil quando le osservazioni richieste non sono disponibili.",
-- 3dd70e07 English: Finite native resource quantity, retaining its sign and fractional part; nil
--     when unavailable.
[2101] = "Quantità nativa finita della risorsa, con segno e parte frazionaria mantenuti; nil se non disponibile.",
-- 3931aa80 English: Finite native threat status, false for known absence/nonenemy/no-threat, or nil
--     for unavailable observations.
[2102] = "Stato di minaccia nativo finito, false per assenza/non nemico/nessuna minaccia accertati, oppure nil per osservazioni non disponibili.",
-- 9cb9f6d2 English: Finite nonnegative native health scalar, or nil when unavailable.
[2103] = "Valore scalare nativo della salute, finito e non negativo, oppure nil se non disponibile.",
-- aa23a412 English: Finite quantity in whole units with its fractional part; nil when unavailable.
[2104] = "Quantità finita in unità intere con la sua parte frazionaria; nil se non disponibile.",
-- 29e4a6a2 English: Finite signed combined rate, or nil for unavailable calculation.
[2105] = "Tasso combinato finito con segno, oppure nil se il calcolo non è disponibile.",
-- 94c010ef English: First exact unit token, checked for existence before comparison.
[2106] = "Primo identificativo unità esatto, di cui si verifica l'esistenza prima del confronto.",
-- 46ec876e English: First table to compare.
[2107] = "Prima tabella da confrontare.",
-- 13e6df72 English: Format comparison wording with named Boolean alternatives when the operator has
--     a negative form. The primary flag marks the positive form as the primary alternative.
--     Positive operator labels use the captured operator map; negative labels and nullable dispatch
--     retain their live addon APIs.
[2108] = "Formatta la formulazione del confronto con alternative booleane con nome quando l'operatore ha una forma negativa. L'opzione primary indica la forma positiva come alternativa primaria. Le etichette degli operatori positivi usano la mappa degli operatori acquisita; le etichette negative e la gestione dei valori nulli mantengono le rispettive API attuali dell'addon.",
-- b0edcb9b English: Fresh finite native clock value, or nil when unavailable.
[2109] = "Valore nativo dell'orologio, appena letto e finito, oppure nil se non disponibile.",
-- b3a296d8 English: Fresh readable class filename, or nil when unavailable.
[2110] = "Nome file della classe appena letto e leggibile, oppure nil se non disponibile.",
-- 16428e88 English: Fresh readable finite clock, or nil when unavailable.
[2111] = "Orologio appena letto, leggibile e finito, oppure nil se non disponibile.",
-- 2078f2c6 English: Fresh readable record with active, then name or nameReason, remainingSeconds,
--     durationSeconds, interruptible and spellID. Remaining time and duration are in seconds;
--     remaining time is clamped to zero. An unavailable optional field has its own reason; it does
--     not invalidate an active record.
[2112] = "Record aggiornato e leggibile con active, poi name o nameReason, remainingSeconds, durationSeconds, interruptible e spellID. Il tempo rimanente e la durata sono in secondi; il tempo rimanente viene limitato a zero. Un campo facoltativo non disponibile ha il proprio motivo; non invalida un record attivo.",
-- 47a58974 English: Fresh readable record with exists and, when present, a positive integer level.
[2113] = "Record appena letto e leggibile con exists e, se presente, un livello intero positivo.",
-- a25abeed English: Fresh readable record with exists and, when present, current health. Maximum
--     health is included only when requested.
[2114] = "Record appena letto e leggibile con exists e, se presente, la salute attuale. La salute massima è inclusa solo se richiesta.",
-- 21290700 English: Fresh readable record with exists and, when present, powerType and finite
--     current quantity. Requested maximum is finite and nonnegative. Quantities may be fractional;
--     current-mode current may be signed.
[2115] = "Record appena letto e leggibile con exists e, se presente, powerType e una quantità attuale finita. Il massimo richiesto è finito e non negativo. Le quantità possono essere frazionarie; in modalità current la quantità attuale può avere segno.",
-- 681f8ad6 English: Fresh readable record with finite nonnegative speed, or nil when unavailable.
[2116] = "Record appena letto e leggibile con velocità finita e non negativa, oppure nil se non disponibile.",
-- abf7477d English: Function or global function name to call.
[2117] = "Funzione, o nome di funzione globale, da chiamare.",
-- 9d253f49 English: History record with newest-first damage and heals arrays of time/value entries.
--     Falsy history returns only zero without reading the clock.
[2118] = "Record della cronologia con array damage e heals di voci tempo/valore, dalla più recente. Una cronologia falsy restituisce solo zero senza leggere l'orologio.",
-- 8deb9947 English: Identifier-keyed scalar values or typed predicates. Strings, finite numbers and
--     booleans are supported; referenced slots must be present. Values are captured when the phrase
--     is created.
[2119] = "Valori scalari o predicati tipizzati indicizzati per identificatore. Sono supportati stringhe, numeri finiti e booleani; gli slot referenziati devono essere presenti. I valori vengono acquisiti alla creazione della frase.",
-- b1c195d7 English: Insert each value visited by ipairs at its corresponding leading index in the
--     destination array. Existing entries shift after the inserted prefix; traversal stops at the
--     first missing source index.
[2120] = "Inserisce ogni valore visitato da ipairs nel corrispondente indice iniziale dell'array di destinazione. Le voci esistenti vengono spostate dopo il prefisso inserito; l'attraversamento si interrompe al primo indice di origine mancante.",
-- db2baa62 English: Integral RM statistic selector 1..5, or 6 for effective armor.
[2121] = "Selettore intero di statistica RM da 1 a 5, oppure 6 per l'armatura effettiva.",
-- c406e603 English: Iterator yielding a captured key and its current table value, or no values when
--     exhausted.
[2122] = "Iteratore che restituisce una chiave acquisita e il valore attuale nella tabella, oppure nessun valore quando è esaurito.",
-- ce63ac6d English: Key to look up.
[2123] = "Chiave da cercare.",
-- 3638b5da English: Known active count from zero through the RM scan budget, or nil when
--     unavailable.
[2124] = "Conteggio attivo noto, da zero fino al budget di scansione di RM, oppure nil se non disponibile.",
-- 101d17c0 English: Known nonempty role string, false for known absent unit, or nil when
--     unavailable.
[2125] = "Stringa di ruolo nota e non vuota, false per un'unità accertata come assente, oppure nil se non disponibile.",
-- 5194c38b English: Known nonempty role string, or nil when unavailable.
[2126] = "Stringa di ruolo nota e non vuota, oppure nil se non disponibile.",
-- 74c5fd96 English: Known unit presence or absence; nil when the required observation is
--     unavailable.
[2127] = "Presenza o assenza nota dell'unità; nil quando l'osservazione richiesta non è disponibile.",
-- 337a2aa3 English: Larger rounded stream age in seconds, not a sample count or proof of continuous
--     observation. Omitted when history is falsy.
[2128] = "La maggiore età arrotondata dei flussi, in secondi; non è un numero di campioni né una prova di osservazione continua. Omessa quando la cronologia è falsy.",
-- 289c0861 English: Left operand; use numbers for ordering and divisibility.
[2129] = "Operando sinistro; usa numeri per ordinamento e divisibilità.",
-- c6b39836 English: Literal prefix, including an empty prefix.
[2130] = "Prefisso letterale, anche vuoto.",
-- 8bc05b19 English: Literal suffix, including an empty suffix.
[2131] = "Suffisso letterale, anche vuoto.",
-- 696821ba English: Live selected talent-group argument, forwarded unchanged as one argument after
--     readability checking.
[2132] = "Argomento attuale del gruppo di talenti selezionato, inoltrato invariato come unico argomento dopo il controllo di leggibilità.",
-- 55c2262c English: Localized complete sentence with named slots and optional explicit predicate
--     alternatives.
[2133] = "Frase completa localizzata con slot con nome e alternative esplicite facoltative per i predicati.",
-- ebab9399 English: Look up a table key for display, preserving non-nil results; invalid tables,
--     missing keys and nil keys use nullable placeholder text.
[2134] = "Cerca una chiave della tabella per la visualizzazione, preservando i risultati non nil; tabelle non valide, chiavi mancanti e chiavi nil usano un testo segnaposto per valori nulli.",
-- d27c5ef2 English: Lookup key.
[2135] = "Chiave di ricerca.",
-- d746509f English: Lua pattern character-class separator, default %s for whitespace.
-- %s #1: %s #1: not a placeholder; it is the literal Lua pattern class for whitespace, shown to the user as text, e.g. "default %s for whitespace". Keep %s exactly as written.
[2136] = "Separatore come classe di caratteri di un pattern Lua, predefinito %s per gli spazi.",
-- 3aeb0664 English: Mark the positive wording as the primary named alternative.
[2137] = "Indica la formulazione positiva come alternativa primaria con nome.",
-- 44dec6d3 English: Matching key, including a false key, or nil when no match exists.
[2138] = "Chiave corrispondente, anche una chiave false, oppure nil quando non esiste alcuna corrispondenza.",
-- 75ef3e00 English: Missing-value display text; omitted uses the localized value placeholder.
[2139] = "Testo da mostrare per un valore mancante; se omesso, usa il segnaposto di valore localizzato.",
-- 15f81670 English: Native button with label, disabled state and lease-protected callbacks.
[2140] = "Pulsante nativo con etichetta, stato disattivato e callback protette da concessione.",
-- 8eb10f5d English: Native directional pad with center reset and lease-protected callbacks.
[2141] = "Pad direzionale nativo con ripristino al centro e callback protette da concessione.",
-- bb0ac63a English: Native image control with label, texture, disabled state and callbacks.
[2142] = "Controllo immagine nativo con etichetta, texture, stato disattivato e callback.",
-- 43cf01e1 English: Native interactive text and image control with measured height and disabled
--     state.
[2143] = "Controllo nativo interattivo di testo e immagine con altezza misurata e stato disattivato.",
-- 990a6544 English: Native one-based integral active-row index within the 256-row RM scan budget.
[2144] = "Indice nativo intero, a partire da uno, della riga attiva entro il budget di scansione di RM di 256 righe.",
-- 7e3aed01 English: Native wrapping text control with font, color and alignment methods.
[2145] = "Controllo nativo di testo a capo automatico con metodi per carattere, colore e allineamento.",
-- d76c2067 English: New shallow filtered table, or nil for nil input.
[2146] = "Nuova tabella superficiale filtrata, oppure nil per un input nil.",
-- 50f7bd28 English: New table with stringified keys and unchanged values.
[2147] = "Nuova tabella con chiavi convertite in stringa e valori invariati.",
-- f1052f11 English: Newest-first health snapshots containing time, value and max. Falsy input
--     returns only zero without reading the clock.
[2148] = "Istantanee della salute dalla più recente, contenenti time, value e max. Un input falsy restituisce solo zero senza leggere l'orologio.",
-- 7276d3c4 English: No return values. The destination array is modified in place.
[2149] = "Nessun valore restituito. L'array di destinazione viene modificato sul posto.",
-- 69c24773 English: No return values. The supplied table is modified in place.
[2150] = "Nessun valore restituito. La tabella fornita viene modificata sul posto.",
-- da87cc23 English: Nonempty class filename token to count; no class-token whitelist is applied.
[2151] = "Identificativo non vuoto del nome file della classe da contare; non viene applicata alcuna lista consentita di identificativi di classe.",
-- 3694f9ed English: Nonempty historical school key for resist/immune; unused for runner.
[2152] = "Chiave storica non vuota della scuola per resist/immune; non usata per runner.",
-- 7ee44b6f English: Normalized bounded socket snapshot with slots and complete, or nil when the
--     query is unavailable.
[2153] = "Istantanea normalizzata e limitata degli alloggiamenti con slots e complete, oppure nil quando la query non è disponibile.",
-- 93ec5fb4 English: Normalized requested subject with finite timeRemaining or timeRemainingReason;
--     nil when the required row or subject is unavailable.
[2154] = "Soggetto richiesto normalizzato con timeRemaining finito o timeRemainingReason; nil quando la riga o il soggetto richiesti non sono disponibili.",
-- 7663ebe1 English: Number of entries visited.
[2155] = "Numero di voci visitate.",
-- 7f36a397 English: Number or string to inspect; other types do not match.
[2156] = "Numero o stringa da esaminare; gli altri tipi non corrispondono.",
-- 4e6ddf17 English: Numeric widget supporting slider bounds, percent display and pending-edit
--     validation.
[2157] = "Widget numerico che supporta limiti del cursore, visualizzazione in percentuale e convalida delle modifiche in sospeso.",
-- c8144d6f English: Observation kind: cast or channel. These use different native interruptibility
--     tuple positions.
[2158] = "Tipo di osservazione: cast o channel. Usano posizioni diverse nella tupla nativa di interrompibilità.",
-- 02905e55 English: Observation, history, work-limit or arithmetic availability reason.
[2159] = "Motivo di indisponibilità di osservazione, cronologia, limite di lavoro o aritmetica.",
-- 966b23c3 English: Observe a fresh protected zero-argument GetTime for a needed health forecast.
--     Require readability and a finite number; preserve signed and fractional values without adding
--     a monotonic, integral or nonnegative restriction. No clock cache or extra native query is
--     used.
[2160] = "Osserva un GetTime protetto senza argomenti, appena letto, per una previsione della salute necessaria. Richiede leggibilità e un numero finito; preserva i valori con segno e frazionari senza aggiungere vincoli di monotonia, interezza o non negatività. Non usa cache dell'orologio né query native aggiuntive.",
-- 9d79dc0d English: Observe a point resource that the client reports in fragments (Mists of
--     Pandaria Burning Embers). Current uses exactly UnitPower(unit,powerType,true) and maximum
--     UnitPowerMax(unit,powerType,true); the result is divided by Blizzard MAX_POWER_PER_EMBER
--     (10), so 35 fragments are 3.5. Probe policy only. Missing, failed, restricted or malformed
--     data remains unavailable; it never falls back to the whole-unit query. No cache is added.
[2161] = "Osserva una risorsa a punti che il client riporta in frammenti (Braci Ardenti di Mists of Pandaria). Current usa esattamente UnitPower(unit,powerType,true) e maximum usa UnitPowerMax(unit,powerType,true); il risultato viene diviso per MAX_POWER_PER_EMBER (10) di Blizzard, quindi 35 frammenti valgono 3,5. Solo criterio di verifica. Dati mancanti, falliti, soggetti a restrizioni o malformati restano non disponibili; non ripiega mai sulla query in unità intere. Non viene aggiunta alcuna cache.",
-- eb0c20b2 English: Observe a readable raw unit level on known clients. A readable absent unit
--     returns exists=false; present units require a positive finite integer UnitLevel. Unknown boss
--     levels, missing, failed, restricted or malformed observations return nil with a reason. This
--     does not use effective or scaled levels.
[2162] = "Osserva il livello grezzo leggibile di un'unità sui client noti. Un'unità leggibile ma assente restituisce exists=false; le unità presenti richiedono un UnitLevel intero, finito e positivo. Livelli dei boss sconosciuti e osservazioni mancanti, fallite, soggette a restrizioni o malformate restituiscono nil con un motivo. Non usa livelli effettivi o scalati.",
-- bc5313d0 English: Observe a selected unit role on probe- and restricted-policy clients without
--     issuing inspection requests. Known unit absence returns false. Prefer the callable modern
--     inspection API, with legacy fallback only when that callable is absent; a selected failure
--     never falls through. Require a positive finite integral specialization ID and consume only
--     role return five from the exact one-argument GetSpecializationInfoByID call. Missing, failed,
--     restricted or malformed required facts are unavailable; readable nonempty future role strings
--     remain exact.
[2163] = "Osserva il ruolo di un'unità selezionata sui client con policy di sondaggio o ristretta, senza inviare richieste di ispezione. Un'unità accertata come assente restituisce false. Preferisce l'API di ispezione moderna richiamabile, ripiegando su quella precedente solo quando la prima non è richiamabile; un errore della selezionata non ripiega mai. Richiede un ID di specializzazione intero, finito e positivo e consuma solo il quinto valore restituito, il ruolo, dalla chiamata esatta a un argomento GetSpecializationInfoByID. Dati richiesti mancanti, falliti, soggetti a restrizioni o malformati sono non disponibili; le stringhe di ruolo future leggibili e non vuote restano esatte.",
-- 3668cf1e English: Observe a unit casting or channeling on probe- and restricted-policy clients. A
--     known absent unit or a readable inactive result returns active=false. Active records contain
--     name, or nameReason when the name is secret (the unit is still casting), and independently
--     available remainingSeconds, durationSeconds, interruptible and spellID fields, with
--     remainingReason, durationReason, interruptibleReason or spellReason when an optional field is
--     unavailable. Missing, failed or restricted presence observations return nil with a reason.
[2164] = "Osserva il lancio o la canalizzazione di un'unità sui client con policy di sondaggio o ristretta. Un'unità accertata come assente o un risultato inattivo leggibile restituisce active=false. I record attivi contengono name, oppure nameReason quando il nome è segreto (l'unità sta comunque lanciando), e i campi remainingSeconds, durationSeconds, interruptible e spellID, disponibili in modo indipendente, con remainingReason, durationReason, interruptibleReason o spellReason quando un campo facoltativo non è disponibile. Le osservazioni di presenza mancanti, non riuscite o limitate restituiscono nil con un motivo.",
-- 740dd187 English: Observe creature identity from native UnitCreatureType return two on probe- and
--     restricted-policy clients. Check exact UnitExists(unit) first; readable false returns false
--     without requiring or calling creature metadata. A present unit requires a readable finite
--     numeric ID; the unused localized name does not affect availability. Preserve signed,
--     fractional, zero and future finite IDs as known values. Missing, failed, nil, restricted or
--     malformed required facts return nil with a reason. No creature enumeration, translated
--     caption comparison or longterm cache is added.
[2165] = "Osserva l'identità della creatura dal secondo valore restituito da UnitCreatureType nativo sui client con policy di sondaggio o ristretta. Verifica prima esattamente UnitExists(unit); un false leggibile restituisce false senza richiedere né chiamare i metadati della creatura. Un'unità presente richiede un ID numerico finito e leggibile; il nome localizzato inutilizzato non influisce sulla disponibilità. Preserva come valori noti gli ID con segno, frazionari, zero e futuri finiti. Dati richiesti mancanti, falliti, nil, soggetti a restrizioni o malformati restituiscono nil con un motivo. Non vengono aggiunti enumerazione delle creature, confronto delle didascalie tradotte o cache a lungo termine.",
-- 075b71e7 English: Observe death or ghost state, or friendliness to the player, for the exact
--     selected unit on probe- and restricted-policy clients. A missing, failed, restricted or
--     malformed required observation is unavailable. Unit absence is unavailable rather than a
--     negative match, including under NOT. No cross-poll state is retained.
[2166] = "Osserva lo stato di morte o di spirito, oppure l'amicizia verso il giocatore, per l'unità selezionata esatta sui client con policy di sondaggio o ristretta. Un'osservazione richiesta mancante, fallita, soggetta a restrizioni o malformata è non disponibile. L'assenza dell'unità è non disponibile anziché una corrispondenza negativa, anche sotto NOT. Non viene mantenuto alcuno stato tra un sondaggio e l'altro.",
-- 87176204 English: Observe exact pet existence and optionally its formatted GetUnitName display
--     name. Presence-only queries never require name data. Known absence skips the name query.
--     Present pets require a readable nonempty name only when requested; required missing, failed,
--     nil, restricted or malformed observations return nil with a reason. The display helper is
--     called with its single original pet argument, without UnitName fallback or inferred bar,
--     health or ability state.
[2167] = "Osserva l'esistenza esatta del famiglio e, facoltativamente, il suo nome visualizzato formattato da GetUnitName. Le query di sola presenza non richiedono mai il nome. Un'assenza accertata salta la query del nome. I famigli presenti richiedono un nome leggibile e non vuoto solo se richiesto; osservazioni richieste mancanti, fallite, nil, soggette a restrizioni o malformate restituiscono nil con un motivo. La funzione di visualizzazione viene chiamata con il suo unico argomento originale pet, senza ripiegare su UnitName e senza dedurre barra, salute o stato delle abilità.",
-- 2280ad22 English: Observe exact selected-unit existence and optionally its class filename for
--     point-resource conditions. Known absence returns exists=false without reading class. Present
--     units require only UnitClass return two when requested; unused localized names and IDs do not
--     affect availability. Required missing, failed, restricted or malformed observations remain
--     unavailable. This does not select a resource or cache identity.
[2168] = "Osserva l'esistenza esatta dell'unità selezionata e, facoltativamente, il nome file della sua classe per le condizioni sulle risorse a punti. Un'assenza accertata restituisce exists=false senza leggere la classe. Le unità presenti richiedono, se richiesto, solo il secondo valore restituito da UnitClass; nomi localizzati e ID inutilizzati non influiscono sulla disponibilità. Osservazioni richieste mancanti, fallite, soggette a restrizioni o malformate restano non disponibili. Non seleziona una risorsa né memorizza l'identità in cache.",
-- 9b79981c English: Observe explicit mana or the current raw power resource on supported readable
--     clients. Select resource identities from the live PowerType enum; explicit mana never falls
--     back to the current bar. Known absence returns exists=false; missing, failed, restricted or
--     malformed observations return nil with a reason. Current-mode quantities preserve signed
--     native resources; explicit mana is nonnegative. Request maximum only when needed; percentage
--     consumers must require a positive maximum.
[2169] = "Osserva il mana esplicito o la risorsa grezza attuale sui client leggibili supportati. Seleziona le identità delle risorse dall'enum PowerType attuale; il mana esplicito non ripiega mai sulla barra attuale. Un'assenza accertata restituisce exists=false; osservazioni mancanti, fallite, soggette a restrizioni o malformate restituiscono nil con un motivo. Le quantità in modalità current preservano le risorse native con segno; il mana esplicito è non negativo. Richiedi il massimo solo se necessario; chi usa le percentuali deve richiedere un massimo positivo.",
-- 278a17a4 English: Observe glyph sockets on verified Wrath, Cata and Mists client layouts. Returns
--     slots and a complete flag. Each slot has active=false when known locked or empty, active=true
--     plus spellID when occupied, or nil active plus reason when unavailable. Unknown layouts and
--     failed count queries return nil with a reason. This does not compare item names or prove
--     exact item-to-spell identity.
[2170] = "Osserva gli alloggiamenti dei glifi sui layout verificati dei client Wrath, Cata e Mists. Restituisce slots e un indicatore complete. Ogni alloggiamento ha active=false se accertato come bloccato o vuoto, active=true più spellID se occupato, oppure active nil più un motivo se non disponibile. Layout sconosciuti e query di conteggio fallite restituiscono nil con un motivo. Non confronta i nomi degli oggetti né dimostra l'esatta corrispondenza tra oggetto e incantesimo.",
-- 24ad932a English: Observe one consumed native unit metadata field after checking UnitExists:
--     class uses UnitClass return two, creature uses the localized UnitCreatureType name, and
--     classification uses UnitClassification. A readable absent unit returns false without querying
--     metadata. Unused tuple fields do not affect availability; a required missing, failed, nil,
--     restricted or malformed value returns nil with a reason. No player class, GUID, enum or
--     translation inference is added.
[2171] = "Osserva un singolo campo di metadati nativi dell'unità consumato, dopo aver verificato UnitExists: class usa il secondo valore restituito da UnitClass, creature usa il nome localizzato di UnitCreatureType e classification usa UnitClassification. Un'unità leggibile ma assente restituisce false senza interrogare i metadati. I campi inutilizzati della tupla non influiscono sulla disponibilità; un valore richiesto mancante, fallito, nil, soggetto a restrizioni o malformato restituisce nil con un motivo. Non vengono aggiunte deduzioni di classe del giocatore, GUID, enum o traduzione.",
-- 641cce1a English: Observe one current unit flag: combat uses UnitAffectingCombat, enemy uses
--     UnitIsEnemy with player as the first unit, and pvp uses UnitIsPVP. A readable absent unit
--     returns false without querying the flag. Required missing, failed, restricted or malformed
--     observations return nil with a reason. This preserves the exact selected unit and does not
--     infer friendliness, attackability or other unit states.
[2172] = "Osserva un singolo indicatore attuale dell'unità: combat usa UnitAffectingCombat, enemy usa UnitIsEnemy con player come prima unità e pvp usa UnitIsPVP. Un'unità leggibile ma assente restituisce false senza interrogare l'indicatore. Osservazioni richieste mancanti, fallite, soggette a restrizioni o malformate restituiscono nil con un motivo. Preserva l'unità selezionata esatta e non deduce amicizia, attaccabilità o altri stati dell'unità.",
-- abc3ec81 English: Observe one exact native rune slot using GetRuneType with its single index
--     argument. Require a readable finite positive integral type; known future numeric types remain
--     distinct from the selected type, and Death is an exact type rather than a wildcard. Missing,
--     failed, restricted or malformed observations remain unavailable. No class, unit, count or
--     inferred base-rune query is added.
[2173] = "Osserva un singolo slot di runa nativo esatto usando GetRuneType con il suo unico argomento indice. Richiede un tipo intero, positivo, finito e leggibile; i tipi numerici futuri noti restano distinti dal tipo selezionato, e Morte è un tipo esatto, non un jolly. Osservazioni mancanti, fallite, soggette a restrizioni o malformate restano non disponibili. Non vengono aggiunte query di classe, unità, conteggio o runa base dedotta.",
-- 87dc4eea English: Observe one independent zero-argument player flag: stealthed uses IsStealthed,
--     control uses HasFullControl, and outdoors uses IsOutdoors. Readable true and false retain
--     their meanings. Required missing, failed, nil, restricted or malformed data returns nil with
--     a reason. No existence, instance or ability-usability inference is added.
[2174] = "Osserva un singolo indicatore indipendente del giocatore senza argomenti: stealthed usa IsStealthed, control usa HasFullControl e outdoors usa IsOutdoors. I valori true e false leggibili mantengono il loro significato. Dati richiesti mancanti, falliti, nil, soggetti a restrizioni o malformati restituiscono nil con un motivo. Non vengono aggiunte deduzioni su esistenza, istanza o utilizzabilità delle abilità.",
-- 46d51f29 English: Observe one protected zero-argument IsInInstance tuple. Required readable
--     Boolean membership is independent of the type field: known outside returns without
--     interpreting the unused type; inside returns a readable string type or an instanceTypeReason
--     when that secondary field is unavailable. Callers testing outside need only membership;
--     inside type comparisons must check the secondary reason. No outdoors, zone or unit inference
--     is added.
[2175] = "Osserva una singola tupla protetta di IsInInstance senza argomenti. L'appartenenza booleana leggibile richiesta è indipendente dal campo del tipo: se accertato fuori, restituisce senza interpretare il tipo inutilizzato; se dentro, restituisce un tipo stringa leggibile oppure instanceTypeReason quando quel campo secondario non è disponibile. Chi verifica l'essere fuori ha bisogno solo dell'appartenenza; i confronti sul tipo all'interno devono controllare il motivo secondario. Non vengono aggiunte deduzioni su all'aperto, zona o unità.",
-- 5671d2c8 English: Observe ordered selected-unit existence, hostility from player, then the player
--     threat status on that unit. Known absence, nonenemy and a successfully read nil threat status
--     return false, preserving the no-threat predicate. Finite status numbers including zero retain
--     their original comparison meaning. Required missing, failed, nil, restricted or malformed
--     facts return nil with a reason. No attackability, death, combat or vehicle inference is
--     added.
[2176] = "Osserva in ordine l'esistenza dell'unità selezionata, l'ostilità rispetto al giocatore e poi lo stato di minaccia del giocatore su quell'unità. Un'assenza accertata, un'unità non nemica e uno stato di minaccia nil letto correttamente restituiscono false, preservando il predicato di assenza di minaccia. I numeri di stato finiti, zero incluso, mantengono il loro significato originale nei confronti. Dati richiesti mancanti, falliti, nil, soggetti a restrizioni o malformati restituiscono nil con un motivo. Non vengono aggiunte deduzioni su attaccabilità, morte, combattimento o veicoli.",
-- 545656e0 English: Observe readable current health and optionally maximum health on supported
--     clients. A readable absent unit returns exists=false. Missing, failed, restricted or
--     malformed observations return nil with a reason; they do not establish an absent unit or a
--     health value.
[2177] = "Osserva la salute attuale leggibile e, facoltativamente, la salute massima sui client supportati. Un'unità leggibile ma assente restituisce exists=false. Osservazioni mancanti, fallite, soggette a restrizioni o malformate restituiscono nil con un motivo; non stabiliscono un'unità assente né un valore di salute.",
-- 254b0aeb English: Observe the current player form with one protected zero-argument
--     GetShapeshiftForm call. Preserve every readable finite numeric result, including zero, signed
--     and fractional values; no stronger native index domain is inferred. Missing, failed, nil,
--     restricted or nonfinite data remains unavailable. No form count, class, spell ID, unit or
--     optional argument is added.
[2178] = "Osserva la forma attuale del giocatore con un'unica chiamata protetta a GetShapeshiftForm senza argomenti. Preserva ogni risultato numerico finito leggibile, inclusi zero, valori con segno e frazionari; non viene dedotto un dominio di indici nativo più restrittivo. Dati mancanti, falliti, nil, soggetti a restrizioni o non finiti restano non disponibili. Non vengono aggiunti numero di forme, classe, ID incantesimo, unità o argomenti facoltativi.",
-- 1de1b681 English: Observe the effective statistic from native return two only. On probe- and
--     restricted-policy clients, query exact UnitExists(unit), then UnitStat(unit,stat) for
--     selector 1..5 or UnitArmor(unit) for selector 6. Known absence returns exists=false; missing,
--     failed, restricted or nonfinite required facts return nil. Preserve finite signed, fractional
--     and zero values; ignore all unused tuple fields. The 1..6 route is an RM selector policy, not
--     a native value-domain limit.
[2179] = "Osserva la statistica effettiva solo dal secondo valore nativo restituito. Sui client con policy di sondaggio o ristretta interroga esattamente UnitExists(unit), poi UnitStat(unit,stat) per i selettori 1..5 o UnitArmor(unit) per il selettore 6. Un'assenza accertata restituisce exists=false; dati richiesti mancanti, falliti, soggetti a restrizioni o non finiti restituiscono nil. Preserva i valori finiti con segno, frazionari e zero; ignora tutti i campi inutilizzati della tupla. L'instradamento 1..6 è una policy dei selettori di RM, non un limite del dominio dei valori nativi.",
-- 2cf23a04 English: Observe the explicitly selected TBC player combo transport. Current uses
--     exactly GetComboPoints(player,target); maximum uses UnitPowerMax(player,powerType) with the
--     original selector. Other families are unavailable here and must use their existing
--     point-power observer. Preserve readable finite signed, fractional and zero values. Missing,
--     failed, restricted or malformed data remains unavailable; a failed chosen combo query never
--     falls back to UnitPower. This observes no other actor and adds no cache.
[2180] = "Osserva il trasporto dei punti combo del giocatore di TBC selezionato esplicitamente. Current usa esattamente GetComboPoints(player,target); maximum usa UnitPowerMax(player,powerType) con il selettore originale. Le altre famiglie non sono disponibili qui e devono usare il loro osservatore esistente delle risorse a punti. Preserva i valori leggibili finiti con segno, frazionari e zero. Dati mancanti, falliti, soggetti a restrizioni o malformati restano non disponibili; una query dei punti combo scelta che fallisce non ripiega mai su UnitPower. Non osserva nessun altro attore e non aggiunge cache.",
-- 95b7963d English: Observe the first role result of the exact legacy GetTalentGroupRole(group) dot
--     call on probe- and restricted-policy clients. Forward the readable selected group unchanged,
--     including nil as one argument; do not infer group bounds, substitute another API or query a
--     player unit. The complete legacy primary declaration is not established. Missing, failed,
--     restricted, empty or malformed role data is unavailable; readable nonempty future strings
--     remain exact.
[2181] = "Osserva il primo risultato di ruolo della chiamata con punto esatta GetTalentGroupRole(group), del sistema precedente, sui client con policy di sondaggio o ristretta. Inoltra invariato il gruppo selezionato leggibile, anche nil come unico argomento; non dedurre i limiti del gruppo, non sostituire un'altra API e non interrogare un'unità giocatore. La dichiarazione primaria completa del sistema precedente non è accertata. Dati di ruolo mancanti, falliti, soggetti a restrizioni, vuoti o malformati sono non disponibili; le stringhe future leggibili e non vuote restano esatte.",
-- 79e9c144 English: Observe the first zone PvP classification result with one protected
--     zero-argument dot call. Prefer callable C_PvP.GetZonePVPInfo and use the global helper only
--     when the modern callable is absent. A successful nil or no returned values produces a known
--     empty record; missing, failed, restricted or malformed observations remain unavailable.
--     Readable empty and future strings retain their exact meaning, and unused return fields do not
--     determine availability. Never switch backends after a modern result or failure.
[2182] = "Osserva il primo risultato della classificazione PvP della zona con un'unica chiamata con punto protetta senza argomenti. Preferisci C_PvP.GetZonePVPInfo se richiamabile e usa la funzione globale solo quando quella moderna non è richiamabile. Un nil restituito con successo o l'assenza di valori restituiti produce un record vuoto noto; osservazioni mancanti, fallite, soggette a restrizioni o malformate restano non disponibili. Le stringhe vuote e future leggibili mantengono il loro significato esatto e i campi restituiti inutilizzati non determinano la disponibilità. Non cambiare mai backend dopo un risultato o un errore di quella moderna.",
-- 9570ca02 English: Observe the player current movement speed on supported readable clients. This
--     queries GetUnitSpeed for player only, without testing another unit or redirecting vehicle
--     ownership. Zero means stationary; positive finite fractional speeds remain valid. Missing,
--     failed, restricted or malformed observations return nil with a reason.
[2183] = "Osserva la velocità di movimento attuale del giocatore sui client leggibili supportati. Interroga GetUnitSpeed solo per player, senza verificare un'altra unità né reindirizzare la proprietà dei veicoli. Zero significa fermo; le velocità positive, finite e frazionarie restano valide. Osservazioni mancanti, fallite, soggette a restrizioni o malformate restituiscono nil con un motivo.",
-- 6b0f7980 English: Observe unit presence on identified client families. Pass the selected unit
--     unchanged to one protected UnitExists call. Preserve readable true and false; missing,
--     failed, restricted, nil or malformed required observations return nil with a reason. No
--     identity, visibility, range or combat-state query is added.
[2184] = "Osserva la presenza dell'unità sulle famiglie di client identificate. Passa l'unità selezionata invariata a un'unica chiamata protetta a UnitExists. Preserva true e false leggibili; osservazioni richieste mancanti, fallite, soggette a restrizioni, nil o malformate restituiscono nil con un motivo. Non vengono aggiunte query su identità, visibilità, distanza o stato di combattimento.",
-- a754c7d3 English: Observe whether the player can attack a selected unit that is not dead, using
--     the exact UnitExists, UnitCanAttack and UnitIsDead predicates. Known absence or a readable
--     false attack result returns false without querying death. Required missing, failed,
--     restricted or malformed observations return nil with a reason. This does not test ghosts,
--     range, hostility or ability usability, and does not redirect unit ownership.
[2185] = "Osserva se il giocatore può attaccare un'unità selezionata non morta, usando esattamente i predicati UnitExists, UnitCanAttack e UnitIsDead. Un'assenza accertata o un risultato di attacco false leggibile restituisce false senza interrogare la morte. Osservazioni richieste mancanti, fallite, soggette a restrizioni o malformate restituiscono nil con un motivo. Non verifica spiriti, distanza, ostilità o utilizzabilità delle abilità e non reindirizza la proprietà dell'unità.",
-- d4d5ab66 English: Observed class filename string, false for a known absent unit, or nil when
--     unavailable.
[2186] = "Stringa del nome file della classe osservata, false per un'unità accertata come assente, oppure nil se non disponibile.",
-- 6b236c0f English: Observed membership, or nil when unavailable.
[2187] = "Appartenenza osservata, oppure nil se non disponibile.",
-- 7c413887 English: On a selected resource only, target-combo for the explicit TBC player fallback
--     or power for the existing selected-unit transport.
[2188] = "Solo su una risorsa selezionata: target-combo per il ripiego esplicito del giocatore di TBC oppure power per il trasporto esistente dell'unità selezionata.",
-- 4b90146b English: On probe- and restricted-policy clients, observe exact UnitExists(unit), then
--     UnitGUID(unit) only for a present unit. Known absence is false. Present identity requires a
--     readable nonempty GUID; missing, failed, malformed or restricted required facts are
--     unavailable. No health, provider or extra-unit observation is added.
[2189] = "Sui client con policy di sondaggio o ristretta osserva esattamente UnitExists(unit), poi UnitGUID(unit) solo per un'unità presente. Un'assenza accertata è false. L'identità presente richiede un GUID leggibile e non vuoto; dati richiesti mancanti, falliti, malformati o soggetti a restrizioni sono non disponibili. Non vengono aggiunte osservazioni su salute, fornitore o unità aggiuntive.",
-- 7980af82 English: One of class, creature or classification; other metadata kinds are unsupported.
[2190] = "Uno tra class, creature o classification; gli altri tipi di metadati non sono supportati.",
-- f4dbfa56 English: One of combat, enemy or pvp; other flag kinds are not supported.
[2191] = "Uno tra combat, enemy o pvp; gli altri tipi di indicatore non sono supportati.",
-- 6a9d3fdc English: One of stealthed, control or outdoors; no other predicate is invoked.
[2192] = "Uno tra stealthed, control o outdoors; non viene richiamato nessun altro predicato.",
-- e7332ebe English: One rounded numeric result from the original formula.
[2193] = "Un unico risultato numerico arrotondato dalla formula originale.",
-- ffb1aba4 English: Optional collection of key values selecting entries; its own keys are ignored.
[2194] = "Raccolta facoltativa di valori chiave che selezionano le voci; le sue chiavi vengono ignorate.",
-- a4bd9302 English: Optional ordering callback called as order(t, leftKey, rightKey).
[2195] = "Callback di ordinamento facoltativa, chiamata come order(t, leftKey, rightKey).",
-- 3a0cafbd English: Optional positive class ID; nil queries the current player class under
--     protection.
[2196] = "ID di classe positivo facoltativo; con nil interroga in modo protetto la classe attuale del giocatore.",
-- d8e2dd81 English: Original explicit readable finite nonnegative integer combo-resource selector,
--     including zero; retained for the maximum query.
[2197] = "Selettore originale esplicito della risorsa dei punti combo, leggibile, finito, intero e non negativo, zero incluso; mantenuto per la query del massimo.",
-- 8311cae8 English: Original non-nil lookup result, or a colored placeholder string.
[2198] = "Risultato originale non nil della ricerca, oppure una stringa segnaposto colorata.",
-- 32680ed5 English: Original non-nil value, or a colored placeholder string.
[2199] = "Valore originale non nil, oppure una stringa segnaposto colorata.",
-- 80842131 English: Original rounded-age bucket count, omitted when the result is the lone zero.
[2200] = "Conteggio originale degli intervalli di età arrotondata, omesso quando il risultato è lo zero da solo.",
-- 169b03f3 English: Packaged helper from Conditions/spatial.lua.
[2201] = "Funzione di supporto inclusa da Conditions/spatial.lua.",
-- 18a2dc4d English: Packaged helper from utils.lua.
[2202] = "Funzione di supporto inclusa da utils.lua.",
-- dd1476f6 English: Partial current/maximum record, empty when provider absent, or nil when
