[2205] = "Osservazione del famiglio con exists booleano e, per un famiglio presente richiesto, name; nil quando i dati richiesti non sono disponibili.",
-- f4bb093a English: Policy or availability reason for a nil movement observation.
[2206] = "Motivo di policy o di indisponibilità quando l'osservazione del movimento è nil.",
-- 7f7f12b8 English: Policy, capability or clock observation availability reason for a nil time.
[2207] = "Motivo di policy, di funzionalità o di indisponibilità dell'osservazione dell'orologio quando il tempo è nil.",
