[2208] = "Motivo di policy, di funzionalità o di indisponibilità di un'osservazione richiesta.",
-- d35012ad English: Policy, query, capability or required row/subject availability reason for a nil
--     record.
[2209] = "Motivo di policy, di query, di funzionalità o di indisponibilità della riga/del soggetto richiesti quando il record è nil.",
-- 59cf373b English: Policy, query-validation or availability reason for a nil metadata observation.
[2210] = "Motivo di policy, di convalida della query o di indisponibilità quando l'osservazione dei metadati è nil.",
-- 5f9416e7 English: Policy, query-validation or availability reason for a nil pet observation.
[2211] = "Motivo di policy, di convalida della query o di indisponibilità quando l'osservazione del famiglio è nil.",
