[2212] = "Motivo di policy, di convalida della query o di indisponibilità quando l'indicatore del giocatore è nil.",
-- a9338066 English: Policy, query-validation or availability reason for a nil quantity.
[2213] = "Motivo di policy, di convalida della query o di indisponibilità quando la quantità è nil.",
-- bde90d0c English: Policy, query-validation or availability reason for a nil resource observation.
[2214] = "Motivo di policy, di convalida della query o di indisponibilità quando l'osservazione della risorsa è nil.",
-- cd1d6bc4 English: Policy, query-validation or availability reason for a nil threat observation.
[2215] = "Motivo di policy, di convalida della query o di indisponibilità quando l'osservazione della minaccia è nil.",
