[2216] = "Motivo di policy, di convalida della query o di indisponibilità quando l'indicatore dell'unità è nil.",
-- de3eca9c English: Policy, query-validation or availability reason for nil attackability.
[2217] = "Motivo di policy, di convalida della query o di indisponibilità quando l'attaccabilità è nil.",
-- e1be06fc English: Policy, query-validation or identity/selector availability reason for a nil
--     selector.
[2218] = "Motivo di policy, di convalida della query o di indisponibilità dell'identità/del selettore quando il selettore è nil.",
-- a82bb017 English: Policy, query-validation or required observation availability reason for a nil
--     quantity.
[2219] = "Motivo di policy, di convalida della query o di indisponibilità di un'osservazione richiesta quando la quantità è nil.",
-- 3422d50e English: Policy, query-validation or required observation availability reason for a nil
--     record.
[2220] = "Motivo di policy, di convalida della query o di indisponibilità di un'osservazione richiesta quando il record è nil.",
-- 6d8971dd English: Policy, query-validation or required-observation availability reason for a nil
--     ID.
[2221] = "Motivo di policy, di convalida della query o di indisponibilità di un'osservazione richiesta quando l'ID è nil.",
-- abb38505 English: Policy, query-validation or required-observation availability reason for a nil
--     match.
[2222] = "Motivo di policy, di convalida della query o di indisponibilità di un'osservazione richiesta quando la corrispondenza è nil.",
-- 4be03f57 English: Policy, slot-validation or required observation availability reason for a nil
--     type.
[2223] = "Motivo di policy, di convalida dello slot o di indisponibilità di un'osservazione richiesta quando il tipo è nil.",
-- 07a2f2a4 English: Policy, slot-validation, capability or native-call availability reason for a
--     nil record.
[2224] = "Motivo di policy, di convalida dello slot, di funzionalità o di indisponibilità della chiamata nativa quando il record è nil.",
-- 57d4e2a6 English: Policy, snapshot, identity or threat observation availability reason.
[2225] = "Motivo di policy o di indisponibilità dell'osservazione di istantanea, identità o minaccia.",
-- 88172c69 English: Policy, token-validation or availability reason for a nil identity result.
[2226] = "Motivo di policy, di convalida dell'identificativo o di indisponibilità quando il risultato dell'identità è nil.",
-- 41f7dc66 English: Policy, validation or availability reason for a nil health observation.
[2227] = "Motivo di policy, di convalida o di indisponibilità quando l'osservazione della salute è nil.",
-- cc67968e English: Policy, validation or availability reason for a nil snapshot.
[2228] = "Motivo di policy, di convalida o di indisponibilità quando l'istantanea è nil.",
-- 84bacc88 English: Policy, validation or observation availability reason.
[2229] = "Motivo di policy, di convalida o di indisponibilità dell'osservazione.",
-- 702b5d1d English: Policy, validation or required observation availability reason.
[2230] = "Motivo di policy, di convalida o di indisponibilità di un'osservazione richiesta.",
-- e3a0a3ce English: Positive integer glyph item ID stored by the condition; arrays, item-set keys
--     and spell IDs are not item references.
[2231] = "ID intero positivo dell'oggetto glifo memorizzato dalla condizione; array, chiavi dei set di oggetti e ID degli incantesimi non sono riferimenti a oggetti.",
-- c7e5f035 English: Positive integer level, false for a known absent unit, or nil when unavailable.
[2232] = "Livello intero positivo, false per un'unità accertata come assente, oppure nil se non disponibile.",
-- 2ce665d6 English: Positive integer spell ID, not a spell-book slot.
[2233] = "ID intero positivo dell'incantesimo, non uno slot del libro degli incantesimi.",
-- 37be242f English: Positive item ID or native-recognized item name/link to classify.
[2234] = "ID oggetto positivo o nome/link dell'oggetto riconosciuto dal client da classificare.",
-- eac23024 English: Predicate that validates the proposed spell value.
[2235] = "Predicato che convalida il valore proposto per l'incantesimo.",
-- b7acadb2 English: Present GUID, false for known absence, or nil when unavailable.
[2236] = "GUID presente, false per un'assenza accertata, oppure nil se non disponibile.",
-- 5825055c English: Provider, validation or observation availability reason.
[2237] = "Motivo di fornitore, di convalida o di indisponibilità dell'osservazione.",
-- e78c7309 English: Query, policy or observation availability reason.
[2238] = "Motivo di query, di policy o di indisponibilità dell'osservazione.",
-- b79b336b English: RM comparison operator identifier; missing labels use the operator placeholder.
[2239] = "Identificativo di operatore di confronto RM; le etichette mancanti usano il segnaposto dell'operatore.",
-- 505c9dde English: RM operator identifier.
[2240] = "Identificativo di operatore RM.",
-- a3bcccb3 English: Range record with applicable and, when applicable, inRange; nil when
--     unavailable.
[2241] = "Record di portata con applicable e, se applicabile, inRange; nil se non disponibile.",
-- a18d0c99 English: Read a fresh protected UnitClass player observation for rotation ownership.
--     Consume only the readable nonempty class filename from return two. No existence, level,
--     vehicle, family or combat-policy read is added, and no result persists across calls. Core
--     ownership still validates the class token and character key separately; overridden context
--     providers retain their complete original path.
[2242] = "Legge un'osservazione protetta e appena letta di UnitClass del giocatore per la proprietà della rotazione. Consuma solo il nome file della classe leggibile e non vuoto dal secondo valore restituito. Non vengono aggiunte letture di esistenza, livello, veicolo, famiglia o policy di combattimento, e nessun risultato persiste tra le chiamate. La proprietà nel nucleo convalida comunque separatamente l'identificativo della classe e la chiave del personaggio; i fornitori di contesto sostituiti mantengono il loro percorso originale completo.",
-- 97b3a051 English: Read a fresh protected zero-argument GetTime for rune cooldown arithmetic.
--     Require a readable finite number. This observation is deliberately uncached; callers preserve
--     the original clock-before-scan order and require its value only when a matching rune needs
--     timing. No evaluation-start substitution or inferred time is supplied.
[2243] = "Legge un GetTime protetto, appena letto e senza argomenti, per l'aritmetica dei tempi di recupero delle rune. Richiede un numero leggibile e finito. Questa osservazione non usa deliberatamente la cache; i chiamanti preservano l'ordine originale orologio-prima-della-scansione e richiedono il suo valore solo quando una runa corrispondente ha bisogno dei tempi. Non vengono forniti sostituzioni con l'inizio della valutazione né tempi dedotti.",
-- 3b2652a8 English: Read a lazy health scalar after a separate identity gate. Kind current uses
--     exact UnitHealth(unit); maximum uses exact UnitHealthMax(unit). Probe- and restricted-policy
--     clients accept readable finite nonnegative numbers including zero. No repeated existence/GUID
--     call or alternate tuple fallback is added.
[2244] = "Legge un valore scalare pigro della salute dopo un controllo separato dell'identità. Il tipo current usa esattamente UnitHealth(unit); maximum usa esattamente UnitHealthMax(unit). I client con policy di sondaggio o ristretta accettano numeri leggibili, finiti e non negativi, zero incluso. Non vengono aggiunte chiamate ripetute di esistenza/GUID né ripieghi su tuple alternative.",
-- cd858e26 English: Read a normalized charge record: currentCharges, maxCharges, cooldownStartTime,
--     cooldownDuration, chargeModRate and isActive. Unsupported spells or restricted client data
--     return nil with a reason.
[2245] = "Legge un record normalizzato delle cariche: currentCharges, maxCharges, cooldownStartTime, cooldownDuration, chargeModRate e isActive. Incantesimi non supportati o dati del client soggetti a restrizioni restituiscono nil con un motivo.",
-- 3ba4fbdf English: Read a specified unit membership in the player party or raid. True raidOnly
--     queries only UnitInRaid; otherwise a true UnitInParty result short-circuits, false proceeds
--     to UnitInRaid, and unknown remains unavailable. Readable nil raid index means false; integer
--     raid index1..40 means true. Names are passed unchanged to native APIs; native name-query
--     acceptance requires client qualification.
[2246] = "Legge l'appartenenza di un'unità specificata al gruppo o all'incursione del giocatore. Con raidOnly true interroga solo UnitInRaid; altrimenti un risultato true di UnitInParty termina subito, false passa a UnitInRaid e un valore sconosciuto resta non disponibile. Un indice di incursione nil leggibile significa false; un indice intero da 1 a 40 significa true. I nomi vengono passati invariati alle API native; l'accettazione delle query per nome da parte delle API native richiede la qualificazione del client.",
-- 3db7feb7 English: Read and normalize a spell cooldown across supported clients. The returned
--     record contains startTime, duration, isEnabled and modRate. The timestamps and duration
--     already describe expiration in GetTime() seconds; do not divide them by modRate. When the
--     client hides the times (Retail and Forever in combat) the record is nil with reason
--     restricted-value, followed by the never-secret isEnabled, isActive and isOnGCD flags when
--     they can be read.
[2247] = "Legge e normalizza il tempo di recupero di un incantesimo su tutti i client supportati. Il record restituito contiene startTime, duration, isEnabled e modRate. Gli istanti e la durata descrivono già la scadenza in secondi di GetTime(); non dividerli per modRate. Quando il client nasconde i tempi (Retail e Forever in combattimento) il record è nil con motivo restricted-value, seguito dai flag isEnabled, isActive e isOnGCD, mai segreti, quando possono essere letti.",
-- 4ae0aa42 English: Read normalized native item classification metadata. The record contains
--     canonical itemID, classID and subClassID, plus equipLoc, the non-localized INVTYPE_* equip
--     location token, when it is readable and nonempty; it does not require loaded item display
--     text. Missing, failed, malformed or restricted metadata returns nil with a reason.
[2248] = "Legge i metadati nativi normalizzati di classificazione dell'oggetto. Il record contiene itemID, classID e subClassID canonici, oltre a equipLoc, il token INVTYPE_* non localizzato della posizione di equipaggiamento, quando è leggibile e non vuoto; non richiede che il testo visualizzato dell'oggetto sia caricato. I metadati mancanti, non riusciti, malformati o limitati restituiscono nil con un motivo.",
-- 5286a3fe English: Read one documented active loss-of-control row by its native index and
--     requested subject kind. Type queries require only the readable control type string; school
--     queries require only the readable finite nonnegative integer school mask. Optional timing is
--     returned as a finite timeRemaining or an explicit per-field reason, so an unrelated subject
--     does not require a usable timer. Missing rows are unavailable snapshot observations. No
--     display fields, inferred deadline, duration sum, maximum or native alias fallback is used.
[2249] = "Legge una riga documentata di perdita di controllo attiva tramite il suo indice nativo e il tipo di soggetto richiesto. Le query di tipo richiedono solo la stringa leggibile del tipo di controllo; le query di scuola richiedono solo la maschera di scuola leggibile, finita, intera e non negativa. La tempistica facoltativa viene restituita come timeRemaining finito o come motivo esplicito per campo, così un soggetto non correlato non richiede un timer utilizzabile. Le righe mancanti sono osservazioni non disponibili dell'istantanea. Non vengono usati campi di visualizzazione, scadenze dedotte, somme delle durate, massimi o ripieghi su alias nativi.",
-- 5a423c22 English: Read one explicitly selected point-resource quantity with an exact two-argument
--     UnitPower or UnitPowerMax query. The selector is required; no primary-resource inference or
--     actor remapping occurs. Preserve finite signed, fractional and zero quantities without
--     clamping. Missing, failed, restricted or nonfinite data remains unavailable. Current and
--     maximum are separate observations so callers can share current snapshots while requesting
--     maximum lazily.
[2250] = "Legge la quantità di una singola risorsa a punti selezionata esplicitamente, con una query esatta a due argomenti UnitPower o UnitPowerMax. Il selettore è obbligatorio; non avvengono deduzioni della risorsa primaria né rimappature dell'attore. Preserva le quantità finite con segno, frazionarie e zero senza limitarle. Dati mancanti, falliti, soggetti a restrizioni o non finiti restano non disponibili. Attuale e massimo sono osservazioni separate, così i chiamanti possono condividere le istantanee attuali richiedendo il massimo solo quando serve.",
-- 9f37d74c English: Read one protected GetRuneCooldown tuple for an exact native slot. Normalize
--     ready, start and duration independently: ready requires a readable Boolean, while each time
--     requires a readable finite number and preserves signed, fractional and zero values. Every
--     unavailable field carries its own reason. A successful empty tuple yields a partial record;
--     missing capability, policy or native-call failure yields nil. Never infer ready from timing
--     or timing from ready. Cache this complete record at the caller to share one observation
--     between rune-count and cooldown predicates.
[2251] = "Legge una singola tupla protetta di GetRuneCooldown per uno slot nativo esatto. Normalizza ready, start e duration in modo indipendente: ready richiede un booleano leggibile, mentre ogni tempo richiede un numero leggibile e finito e preserva i valori con segno, frazionari e zero. Ogni campo non disponibile ha il proprio motivo. Una tupla vuota restituita con successo produce un record parziale; funzionalità mancante, policy o errore della chiamata nativa producono nil. Non dedurre mai ready dai tempi né i tempi da ready. Memorizza in cache questo record completo nel chiamante per condividere una sola osservazione tra i predicati di conteggio delle rune e di tempo di recupero.",
-- 0ab0e9af English: Read optional MobInfo2 historical observations on probe- and restricted-policy
--     clients. Cache only exact selected-unit presence; UnitName result one, UnitLevel result one
--     and the three-argument MI2_GetMobData(name,level,unit) dot call stay fresh each invocation.
--     Known absent units and successful unrecorded nil or omitted history remain distinct from
--     unavailable native/provider facts. Preserve readable runner scalar truthiness, school signs
--     and missing-Hits default one. Positive resistance ratios must be finite; complete immunity
--     consumes finite Hits while partial immunity needs only its negative school observation. Never
--     infer native resistance or borrow old records.
[2252] = "Legge le osservazioni storiche facoltative di MobInfo2 sui client con policy di sondaggio o ristretta. Memorizza in cache solo la presenza esatta dell'unità selezionata; il primo risultato di UnitName, il primo risultato di UnitLevel e la chiamata con punto a tre argomenti MI2_GetMobData(name,level,unit) vengono rieseguiti a ogni chiamata. Le unità accertate come assenti e una cronologia nil o omessa restituita con successo restano distinte dai dati nativi/del fornitore non disponibili. Preserva la veridicità dello scalare runner leggibile, i segni delle scuole e il valore predefinito uno per Hits mancante. I rapporti di resistenza positivi devono essere finiti; l'immunità completa consuma Hits finito, mentre l'immunità parziale richiede solo l'osservazione negativa della propria scuola. Non dedurre mai la resistenza nativa né prendere in prestito record vecchi.",
-- a27fc0e3 English: Read optional RealMobHealth using its exact one-argument dot call. Absent
--     nil/false namespace returns an empty record. Normalize current and maximum independently:
--     nil/false fields permit native fallback, numeric zero remains present. Malformed, failed,
--     restricted, negative or nonfinite consumed provider facts are unavailable. No provider or
--     stale fallback cache is used.
[2253] = "Legge RealMobHealth facoltativo usando la sua chiamata con punto esatta a un argomento. Uno spazio dei nomi assente nil/false restituisce un record vuoto. Normalizza attuale e massimo in modo indipendente: i campi nil/false consentono il ripiego nativo, lo zero numerico resta presente. Dati del fornitore consumati malformati, falliti, soggetti a restrizioni, negativi o non finiti sono non disponibili. Non viene usata alcuna cache di ripiego del fornitore o obsoleta.",
-- 0a7395cc English: Read public group membership on identified client families. Unknown clients are
--     unsupported. True raidOnly checks IsInRaid; false or nil checks IsInGroup using its native
--     default group category. A readable false result stays false. Missing, failed, malformed or
--     restricted observations return nil with a reason.
[2254] = "Legge l'appartenenza pubblica al gruppo sulle famiglie di client identificate. I client sconosciuti non sono supportati. Con raidOnly true controlla IsInRaid; con false o nil controlla IsInGroup usando la categoria di gruppo nativa predefinita. Un risultato false leggibile resta false. Osservazioni mancanti, fallite, malformate o soggette a restrizioni restituiscono nil con un motivo.",
-- 4a264ad3 English: Read public roster identity on identified client families. Input routing is
--     limited to player, party1 through party4 and raid1 through raid40. Call UnitExists with that
--     exact one-argument token first; known false returns false without querying class. For a
--     present unit, consume only UnitClass return two as a readable nonempty class filename string,
--     without a class enum restriction. Missing, failed, malformed or restricted required facts
--     return nil with a reason.
[2255] = "Legge l'identità pubblica dei membri sulle famiglie di client identificate. L'instradamento degli input è limitato a player, da party1 a party4 e da raid1 a raid40. Chiama prima UnitExists con quell'esatto identificativo come unico argomento; un false accertato restituisce false senza interrogare la classe. Per un'unità presente, consuma solo il secondo valore restituito da UnitClass come stringa leggibile e non vuota del nome file della classe, senza limitarla a un enum di classi. Dati richiesti mancanti, falliti, malformati o soggetti a restrizioni restituiscono nil con un motivo.",
-- 1f3c0a57 English: Read spell-specific range for a unit using the appropriate client API or
--     spell-book slot. A spell without a range restriction returns applicable=false; otherwise
--     applicable=true and inRange records whether the unit is in range. Unknown or inaccessible
--     observations return nil with a reason.
[2256] = "Legge la portata specifica di un incantesimo per un'unità usando l'API del client appropriata o lo slot del libro degli incantesimi. Un incantesimo senza limite di portata restituisce applicable=false; altrimenti applicable=true e inRange indica se l'unità è entro portata. Osservazioni sconosciute o inaccessibili restituiscono nil con un motivo.",
-- d3d07abb English: Read the current positive nameplate visibility distance using the supported
--     CVar API. This limits a Distance Count query; it does not prove that all nearby units have
--     been observed. Missing, malformed, restricted or failed observations return nil with a
--     reason.
[2257] = "Legge l'attuale distanza positiva di visibilità delle targhette usando l'API CVar supportata. Limita una query di Conteggio distanza; non dimostra che tutte le unità vicine siano state osservate. Osservazioni mancanti, malformate, soggette a restrizioni o fallite restituiscono nil con un motivo.",
-- f4bc8da4 English: Read the documented active loss-of-control count with a protected zero-argument
--     dot call. Require a readable finite nonnegative integer. Zero is a complete empty scan and
--     does not require a row API. RM limits a scan to 256 rows and returns unavailable beyond that
--     resource budget; this is not a declared native maximum. Required missing, failed, restricted
--     or malformed observations remain unavailable.
[2258] = "Legge il conteggio documentato delle perdite di controllo attive con una chiamata con punto protetta senza argomenti. Richiede un intero leggibile, finito e non negativo. Zero è una scansione vuota completa e non richiede un'API per le righe. RM limita una scansione a 256 righe e oltre questo budget restituisce non disponibile; non si tratta di un massimo nativo dichiarato. Osservazioni richieste mancanti, fallite, soggette a restrizioni o malformate restano non disponibili.",
-- 597a72b9 English: Read the player auto-repeat state for a spell such as Shoot or Auto Shot. This
--     is distinct from a current or queued cast. Modern clients receive the exact spell ID; a
--     legacy query resolves the player spell-book slot first. Restricted client policies,
--     unreadable results and unavailable book slots return nil with a reason. This observes state
--     and never starts or stops a spell.
[2259] = "Legge lo stato di ripetizione automatica del giocatore per un incantesimo come Shoot o Auto Shot. È distinto da un lancio attuale o in coda. I client moderni ricevono l'ID esatto dell'incantesimo; una query del sistema precedente risolve prima lo slot del libro degli incantesimi del giocatore. Policy del client con restrizioni, risultati illeggibili e slot del libro non disponibili restituiscono nil con un motivo. Osserva lo stato e non avvia né interrompe mai un incantesimo.",
-- 89759fd9 English: Read the public LibRangeCheck interval for a unit. A successful upper bound is
--     inclusive; a positive failed lower bound is strict. A zero lower floor is synthetic. Neither
--     bound is an exact distance, and a missing upper bound is not proof that the unit is outside
--     every radius. Unavailable, malformed, restricted or failed observations return nil with a
--     reason.
[2260] = "Legge l'intervallo pubblico di LibRangeCheck per un'unità. Un limite superiore riuscito è inclusivo; un limite inferiore positivo non riuscito è stretto. Un limite inferiore pari a zero è sintetico. Nessuno dei due limiti è una distanza esatta, e l'assenza di un limite superiore non prova che l'unità sia al di fuori di ogni raggio. Osservazioni non disponibili, malformate, soggette a restrizioni o fallite restituiscono nil con un motivo.",
-- 41e0213a English: Readability authority for consumed values.
[2261] = "Autorità di leggibilità per i valori consumati.",
-- 7f7e5283 English: Readable canonical item classification record (itemID, classID, subClassID and
--     optional equipLoc), or nil when unavailable.
[2262] = "Record canonico e leggibile di classificazione dell'oggetto (itemID, classID, subClassID ed equipLoc facoltativo), oppure nil se non disponibile.",
-- 708f11a6 English: Readable canonical itemID/classID/subClassID record when the item is a glyph
--     for the requested class; nil for invalid or unavailable metadata.
[2263] = "Record canonico leggibile itemID/classID/subClassID quando l'oggetto è un glifo per la classe richiesta; nil per metadati non validi o non disponibili.",
-- b7b27422 English: Readable charge record, or nil when unavailable.
[2264] = "Record leggibile delle cariche, oppure nil se non disponibile.",
-- 5274b7b7 English: Readable consumed metadata string, false for a known absent unit, or nil when
--     required data is unavailable.
[2265] = "Stringa leggibile dei metadati consumati, false per un'unità accertata come assente, oppure nil quando i dati richiesti non sono disponibili.",
-- 041c7f05 English: Readable cooldown record, or nil when unavailable.
[2266] = "Record leggibile del tempo di recupero, oppure nil se non disponibile.",
-- c171ab16 English: Readable current state, or nil when unavailable.
[2267] = "Stato attuale leggibile, oppure nil se non disponibile.",
-- ea709ff8 English: Readable finite current-form observation, including zero for the current
--     unshifted comparison; nil when unavailable.
[2268] = "Osservazione leggibile e finita della forma attuale, zero incluso per il confronto con la forma normale attuale; nil se non disponibile.",
-- 5fe2cef3 English: Readable finite positive integral rune type, or nil when unavailable.
[2269] = "Tipo di runa leggibile, finito, intero e positivo, oppure nil se non disponibile.",
-- 243ee644 English: Readable interval with optional minimum and maximum bounds in yards. At least
--     one bound is present; nil when unavailable.
[2270] = "Intervallo leggibile con limiti minimo e massimo facoltativi in metri. È presente almeno un limite; nil se non disponibile.",
-- 7c9763dd English: Readable nonempty selected unit token, passed unchanged as the single argument
--     to existence and creature metadata queries.
[2271] = "Identificativo leggibile e non vuoto dell'unità selezionata, passato invariato come unico argomento alle query di esistenza e di metadati della creatura.",
-- 2ce03ebb English: Readable nonempty unit token or native-recognized name, passed unchanged.
[2272] = "Identificativo unità leggibile e non vuoto o nome riconosciuto dal client, passato invariato.",
-- 30a14f21 English: Readable nonempty unit token to match, unchanged in the native observation.
[2273] = "Identificativo unità leggibile e non vuoto da confrontare, invariato nell'osservazione nativa.",
-- 4421ce67 English: Readable nonempty unit token, passed unchanged as the single native argument.
[2274] = "Identificativo unità leggibile e non vuoto, passato invariato come unico argomento nativo.",
-- 831ff884 English: Readable record with Boolean exists and the requested class filename when
--     present; nil when required data is unavailable.
[2275] = "Record leggibile con exists booleano e, se presente, il nome file della classe richiesto; nil quando i dati richiesti non sono disponibili.",
-- e5d5a0bd English: Readable selected flag or nil when required data is unavailable.
[2276] = "Indicatore selezionato leggibile, oppure nil quando i dati richiesti non sono disponibili.",
-- ae99174e English: Readable selected flag, false for a known absent unit, or nil when a required
--     observation is unavailable.
[2277] = "Indicatore selezionato leggibile, false per un'unità accertata come assente, oppure nil quando un'osservazione richiesta non è disponibile.",
-- 15d71981 English: Readable unit equality, false for a known absent first unit, or nil when
--     required observations are unavailable.
[2278] = "Uguaglianza leggibile tra unità, false se la prima unità è accertata come assente, oppure nil quando le osservazioni richieste non sono disponibili.",
-- c72ce8bc English: Record with exists=false, or exists=true and finite value; nil when
--     unavailable.
[2279] = "Record con exists=false, oppure exists=true e un valore finito; nil se non disponibile.",
-- bbdbf34c English: Record with exists=false; recorded=false for known no history; or runner,
--     ratio, or immune with hits/hitsReason. Nil means a required observation is unavailable.
[2280] = "Record con exists=false; recorded=false se è accertata l'assenza di cronologia; oppure runner, ratio o immune con hits/hitsReason. Nil indica che un'osservazione richiesta non è disponibile.",
-- d2443dc7 English: Record with inInstance and, when inside, instanceType or instanceTypeReason;
--     nil when membership is unavailable.
[2281] = "Record con inInstance e, se all'interno, instanceType o instanceTypeReason; nil quando l'appartenenza non è disponibile.",
-- b2c4007b English: Reference input kind, such as Spec_EditBox, used for spell suggestions.
[2282] = "Tipo di input di riferimento, ad esempio Spec_EditBox, usato per i suggerimenti degli incantesimi.",
-- 27542d97 English: Remove entries in place, preserving only keys listed among except values by
--     default. With invert true, remove listed keys and retain unlisted keys. Without an exception
--     list, the default removes every entry and invert true retains every entry. Nil input does
--     nothing.
[2283] = "Rimuove voci sul posto, mantenendo per impostazione predefinita solo le chiavi elencate tra i valori di except. Con invert true rimuove le chiavi elencate e mantiene quelle non elencate. Senza un elenco di eccezioni, l'impostazione predefinita rimuove tutte le voci e invert true le mantiene tutte. Un input nil non fa nulla.",
-- e6ab096c English: Remove leading and trailing Lua-pattern whitespace from a string.
[2284] = "Rimuove da una stringa gli spazi iniziali e finali secondo i pattern Lua.",
-- a3fc9f6e English: Resolve a readable raw unit level for condition evaluation. Known absence
--     returns false; unavailable observations return nil with a reason. Cache observations within
--     the supplied evaluation pass. Only valid player levels are retained between passes until a
--     skill, profile or level refresh.
[2285] = "Risolve un livello grezzo leggibile dell'unità per la valutazione delle condizioni. Un'assenza accertata restituisce false; le osservazioni non disponibili restituiscono nil con un motivo. Memorizza in cache le osservazioni all'interno del passaggio di valutazione fornito. Tra un passaggio e l'altro vengono mantenuti solo i livelli validi del giocatore, fino a un aggiornamento di abilità, profilo o livello.",
-- 1be3efe7 English: Resolve an exact cast-recipient name against the current bounded party or raid
--     roster, then observe membership through a unit token. Missing, ambiguous or changing roster
--     data remains unavailable; never reads the selected target or retains state across casts.
[2286] = "Risolve il nome esatto del destinatario di un lancio rispetto all'elenco limitato attuale dei membri del gruppo o dell'incursione, poi osserva l'appartenenza tramite un identificativo unità. Dati dei membri mancanti, ambigui o in cambiamento restano non disponibili; non legge mai il bersaglio selezionato né mantiene stato tra un lancio e l'altro.",
-- bf87a408 English: Resolve point resources using the original live class mapping and identity
--     cache, with an explicit TBC player ComboPoints-fallback transport policy. A player fallback
--     matching the readable raw Enum.PowerType table and ComboPoints value captured at module load
--     selects target-combo; explicit class-map entries, other actors and other families retain
--     power. Replaced, inherited or unprovable fallback provenance retains power. This versioned
--     policy does not claim native UnitPower is broken or equivalent. Known unit absence returns
--     false; unavailable required observations return nil with a reason. No current or maximum
--     quantity is queried here.
[2287] = "Risolve le risorse a punti usando la corrispondenza originale attuale delle classi e la cache dell'identità, con una policy di trasporto esplicita di ripiego su ComboPoints per il giocatore di TBC. Un ripiego del giocatore che corrisponde alla tabella grezza leggibile Enum.PowerType e al valore ComboPoints acquisiti al caricamento del modulo seleziona target-combo; le voci esplicite della mappa delle classi, gli altri attori e le altre famiglie mantengono power. Un ripiego sostituito, ereditato o di provenienza non dimostrabile mantiene power. Questa policy versionata non afferma che UnitPower nativo sia difettoso o equivalente. Un'unità accertata come assente restituisce false; osservazioni richieste non disponibili restituiscono nil con un motivo. Qui non viene interrogata alcuna quantità attuale o massima.",
-- b9173e02 English: Resolve the selected unit point-resource selector using the live
--     class-to-resource map and ComboPoints fallback. Known absence returns false; unavailable
--     required identity or selector data returns nil with a reason. Share complete identity
--     observations within the evaluation pass. Only successful player class observations persist in
--     the current longterm cache, tied to the native UnitClass identity; existence is refreshed
--     each pass. This selects a resource without reading its current or maximum quantity.
[2288] = "Risolve il selettore delle risorse a punti dell'unità selezionata usando la mappa attuale classe-risorsa e il ripiego su ComboPoints. Un'assenza accertata restituisce false; dati di identità o del selettore richiesti non disponibili restituiscono nil con un motivo. Condivide le osservazioni complete dell'identità all'interno del passaggio di valutazione. Solo le osservazioni riuscite della classe del giocatore persistono nella cache a lungo termine attuale, legate all'identità nativa di UnitClass; l'esistenza viene aggiornata a ogni passaggio. Seleziona una risorsa senza leggerne la quantità attuale o massima.",
-- 718644e5 English: Resolve the spell identifier stored by a condition. With exact rank enabled the
--     supplied ID is retained; otherwise ranked Classic clients resolve the currently known rank
--     through the spell catalog. Returns nil and an availability reason if resolution cannot be
--     completed.
[2289] = "Risolve l'identificatore dell'incantesimo memorizzato da una condizione. Con il grado esatto attivato, l'ID fornito viene mantenuto; altrimenti i client Classic con gradi risolvono il grado attualmente conosciuto tramite il catalogo degli incantesimi. Restituisce nil e un motivo di indisponibilità se la risoluzione non può essere completata.",
-- 1d0d55d1 English: Resolved spell ID, or nil when unavailable.
[2290] = "ID dell'incantesimo risolto, oppure nil se non disponibile.",
-- 6ffafa71 English: Resolver mapping a typed spell name to its ID.
[2291] = "Risolutore che associa un nome di incantesimo digitato al suo ID.",
-- 09cbb92e English: Return a present value unchanged, or a red display placeholder for nil. Use for
--     readable condition labels, not as a boolean fallback.
[2292] = "Restituisce invariato un valore presente, oppure un segnaposto rosso di visualizzazione per nil. Da usare per etichette leggibili delle condizioni, non come ripiego booleano.",
-- d42a9ff5 English: Return the first key whose value equals the supplied value during pairs
--     traversal. Nil or false input tables and absent values return nil. Multiple matching keys
--     have no guaranteed selection order.
[2293] = "Restituisce la prima chiave il cui valore è uguale al valore fornito durante l'attraversamento con pairs. Tabelle di input nil o false e valori assenti restituiscono nil. Se più chiavi corrispondono, l'ordine di selezione non è garantito.",
-- 3f5f3e62 English: Right operand; DIVISIBLE requires a nonzero divisor.
[2294] = "Operando destro; DIVISIBLE richiede un divisore diverso da zero.",
-- 6734885b English: Rotation Master addon instance (implicit with colon calls).
[2295] = "Istanza dell'addon Rotation Master (implicita nelle chiamate con due punti).",
-- 46daa133 English: Rotation Master platform adapter (implicit with colon calls).
[2296] = "Adattatore di piattaforma di Rotation Master (implicito nelle chiamate con due punti).",
-- f0f9c415 English: Rotation Master platform adapter. A dot reference requires addon.Platform as
--     the first argument; a colon call supplies it implicitly.
[2297] = "Adattatore di piattaforma di Rotation Master. Un riferimento con punto richiede addon.Platform come primo argomento; una chiamata con due punti lo fornisce implicitamente.",
-- 3f1284ef English: Round with the existing floor(num * 10^places + 0.5) / 10^places formula.
--     Places defaults to zero and may be negative. Halfway negative values round toward positive
--     infinity; no finite-number validation or alternative rounding policy is added.
[2298] = "Arrotonda con la formula esistente floor(num * 10^places + 0.5) / 10^places. Places è zero per impostazione predefinita e può essere negativo. I valori negativi a metà vengono arrotondati verso più infinito; non vengono aggiunte una convalida dei numeri finiti né criteri di arrotondamento alternativi.",
-- 885bcca4 English: Run the historical health-snapshot trend formula using the live profile history
--     window, clock and legacy rounding service. Preserve its maximum-health transitions, early
--     stop at full or zero health, weighting, errors and return counts. An empty array, or
--     snapshots that record no weighted change, return only zero rather than a 0/0 result; this is
--     the legacy algorithm rather than a validated forecast.
[2299] = "Esegue la formula storica di tendenza delle istantanee della salute usando la finestra attuale della cronologia del profilo, l'orologio e il servizio di arrotondamento precedente. Preserva le sue transizioni della salute massima, l'arresto anticipato a salute piena o nulla, la ponderazione, gli errori e il numero di valori restituiti. Un array vuoto, o istantanee che non registrano alcuna variazione ponderata, restituiscono solo zero invece di un risultato 0/0; è l'algoritmo precedente, non una previsione convalidata.",
-- 472af904 English: Second exact unit token, passed unchanged to UnitIsUnit.
[2300] = "Secondo identificativo unità esatto, passato invariato a UnitIsUnit.",
-- 89bc8587 English: Second table to compare.
[2301] = "Seconda tabella da confrontare.",
-- 181d7eb2 English: Selected nonempty unit token, unchanged in native calls.
[2302] = "Identificativo unità selezionato non vuoto, invariato nelle chiamate native.",
-- ad96e1f2 English: Selected nonempty unit token, unchanged in native/provider calls.
[2303] = "Identificativo unità selezionato non vuoto, invariato nelle chiamate native/del fornitore.",
-- 0fe63d0e English: Selected nonempty unit token.
[2304] = "Identificativo unità selezionato non vuoto.",
-- 2228fc20 English: Selected nonempty unit token; this call alone does not establish presence.
[2305] = "Identificativo unità selezionato non vuoto; questa chiamata da sola non stabilisce la presenza.",
-- f67a8632 English: Selected nonempty unit token; unchanged native argument.
[2306] = "Identificativo unità selezionato non vuoto; argomento nativo invariato.",
-- 9aeb1b04 English: Selected unit token forwarded as the only provider argument.
[2307] = "Identificativo unità selezionato, inoltrato come unico argomento del fornitore.",
-- 91d2e43e English: Selected unit token, unchanged in observations.
[2308] = "Identificativo unità selezionato, invariato nelle osservazioni.",
-- 169d575d English: Selector widget supporting SetList, SetValue, SetLabel, SetDisabled and
--     callbacks.
[2309] = "Widget selettore che supporta SetList, SetValue, SetLabel, SetDisabled e le callback.",
-- c4649a76 English: Shared evaluation cache; nil observes directly without a per-pass cache.
[2310] = "Cache di valutazione condivisa; con nil osserva direttamente senza cache per passaggio.",
-- 32b53cb5 English: Source array whose ipairs prefix is inserted without copying nested values.
[2311] = "Array di origine il cui prefisso ipairs viene inserito senza copiare i valori annidati.",
-- f292d1c8 English: Specialization scope used to resolve spell suggestions.
[2312] = "Ambito di specializzazione usato per risolvere i suggerimenti degli incantesimi.",
-- 78f0e3c1 English: Spell ID or client-recognized spell name whose charges should be read.
[2313] = "ID dell'incantesimo o nome riconosciuto dal client di cui leggere le cariche.",
-- 3b34f727 English: Spell ID or client-recognized spell name whose cooldown should be checked.
[2314] = "ID dell'incantesimo o nome riconosciuto dal client di cui controllare il tempo di recupero.",
-- 2d3ce2ab English: Spell ID or client-recognized spell name whose cooldown should be read.
[2315] = "ID dell'incantesimo o nome riconosciuto dal client di cui leggere il tempo di recupero.",
-- 55538bf5 English: Spell ID whose range should be checked.
[2316] = "ID dell'incantesimo di cui controllare la portata.",
-- b7614a02 English: Spell field group containing an action icon, reference input and optional rank
--     control.
[2317] = "Gruppo di campi incantesimo contenente un'icona di azione, un input di riferimento e un controllo facoltativo del grado.",
-- 31f8edf3 English: Spell-book scope: spell, pet or any.
[2318] = "Ambito del libro degli incantesimi: spell, pet o any.",
-- 05372e4c English: Split a string into nonempty runs between separator characters. The separator
--     is inserted into a Lua pattern character class; it is not a literal multi-character
--     delimiter. Empty fields are omitted.
[2319] = "Divide una stringa in sequenze non vuote tra i caratteri separatori. Il separatore viene inserito in una classe di caratteri di un pattern Lua; non è un delimitatore letterale di più caratteri. I campi vuoti vengono omessi.",
-- db7ca748 English: Stored spell ID to resolve.
[2320] = "ID dell'incantesimo memorizzato da risolvere.",
-- 9379f3fe English: Successful observation record with pvpType string or nil; nil record means
--     unavailable.
[2321] = "Record di osservazione riuscita con stringa pvpType o nil; un record nil indica non disponibile.",
-- e41b12b3 English: Table to copy shallowly, or nil.
[2322] = "Tabella da copiare in modo superficiale, oppure nil.",
-- 07e8d4d0 English: Table to count, or nil for zero.
[2323] = "Tabella da contare, oppure nil per zero.",
-- 58e2d717 English: Table to inspect.
[2324] = "Tabella da esaminare.",
-- 90809a03 English: Table to modify, or nil to do nothing.
[2325] = "Tabella da modificare, oppure nil per non fare nulla.",
-- ff2b1485 English: Table to search; nil or false returns nil.
[2326] = "Tabella in cui cercare; nil o false restituisce nil.",
-- 259ede57 English: Table to traverse; keys must be mutually comparable when no custom ordering is
--     supplied.
[2327] = "Tabella da attraversare; le chiavi devono essere confrontabili tra loro quando non viene fornito un ordinamento personalizzato.",
-- f4e4becf English: Table whose keys should be converted to strings.
[2328] = "Tabella le cui chiavi devono essere convertite in stringhe.",
-- a59c785e English: Table whose values must be mutually comparable.
[2329] = "Tabella i cui valori devono essere confrontabili tra loro.",
-- 2074ad97 English: Target line width, default 72 characters.
[2330] = "Larghezza di riga desiderata, predefinita 72 caratteri.",
-- f3db5e09 English: Test a literal byte prefix using a Lua string slice. Empty prefixes match;
--     pattern characters have no special meaning and case is preserved.
[2331] = "Verifica un prefisso letterale di byte usando una sottostringa Lua. I prefissi vuoti corrispondono; i caratteri dei pattern non hanno significato speciale e maiuscole e minuscole vengono rispettate.",
-- 1f02a40c English: Test a literal byte suffix using a Lua string slice. Empty suffixes match;
--     pattern characters have no special meaning and case is preserved.
[2332] = "Verifica un suffisso letterale di byte usando una sottostringa Lua. I suffissi vuoti corrispondono; i caratteri dei pattern non hanno significato speciale e maiuscole e minuscole vengono rispettate.",
-- e2c64484 English: Text or number shown after the comparison wording.
[2333] = "Testo o numero mostrato dopo la formulazione del confronto.",
-- 026b376c English: Text or number shown before the comparison wording.
[2334] = "Testo o numero mostrato prima della formulazione del confronto.",
-- b84e9fc7 English: Text to inspect.
[2335] = "Testo da esaminare.",
-- 95d67c5a English: Text to split.
[2336] = "Testo da dividere.",
-- a672408d English: Text to trim.
[2337] = "Testo da ripulire.",
-- 332756da English: Text to wrap.
[2338] = "Testo da mandare a capo.",
-- 33010633 English: Text widget supporting label, text, pending-edit and callback methods.
[2339] = "Widget di testo che supporta metodi per etichetta, testo, modifica in sospeso e callback.",
-- f6be6e89 English: Text with line breaks inserted at word boundaries.
[2340] = "Testo con interruzioni di riga inserite ai confini delle parole.",
-- 6f85c46a English: The selected value, including false or nil.
[2341] = "Il valore selezionato, inclusi false o nil.",
-- 6af26a9c English: Transient trusted phrase recognized by condition summary rendering; do not
--     persist it as condition data.
[2342] = "Frase temporanea attendibile riconosciuta dalla generazione del riepilogo della condizione; non salvarla come dato della condizione.",
-- 2bae0b3f English: Transient typed predicate used as a named phrase value; do not persist it as
--     condition data.
[2343] = "Predicato tipizzato temporaneo usato come valore di una frase con nome; non salvarlo come dato della condizione.",
-- 4cf99d8d English: Trimmed text.
[2344] = "Testo ripulito.",
-- e0249036 English: True also observes maximum health; false or nil reads current health only.
[2345] = "True osserva anche la salute massima; false o nil legge solo la salute attuale.",
-- 9ba98a90 English: True also observes the selected resource maximum; false or nil reads current
--     quantity only.
[2346] = "True osserva anche il massimo della risorsa selezionata; false o nil legge solo la quantità attuale.",
-- 19d0b8a3 English: True also requires the present unit class filename; false reads existence only.
[2347] = "True richiede anche il nome file della classe dell'unità presente; false legge solo l'esistenza.",
-- ac4e613c English: True checks raid membership only; false or nil checks party or raid.
[2348] = "True controlla solo l'appartenenza all'incursione; false o nil controlla gruppo o incursione.",
-- 9cf4986d English: True checks raid membership only; false or nil checks party then raid.
[2349] = "True controlla solo l'appartenenza all'incursione; false o nil controlla il gruppo e poi l'incursione.",
-- 4bf4841d English: True for a readable attackable non-dead unit, false for a conclusive negative
--     result, or nil when a required observation is unavailable.
[2350] = "True per un'unità leggibile, attaccabile e non morta, false per un risultato negativo conclusivo, oppure nil quando un'osservazione richiesta non è disponibile.",
-- 72d71c8f English: True for an exact identity match; false for known absence or mismatch; nil when
--     required data or the query is unavailable.
[2351] = "True per una corrispondenza esatta di identità; false per assenza accertata o mancata corrispondenza; nil quando i dati richiesti o la query non sono disponibili.",
-- 3286d546 English: True includes only listed entries; false or nil excludes listed entries.
[2352] = "True include solo le voci elencate; false o nil esclude le voci elencate.",
-- b3108208 English: True marks the main comparison to negate; false or nil leaves it eligible only
--     when no primary predicate exists.
[2353] = "True indica il confronto principale da negare; false o nil lo lascia idoneo solo quando non esiste un predicato primario.",
-- 00d420e2 English: True permits the raid roster when raid membership is known true; false or nil
--     uses the solo or party roster.
[2354] = "True consente l'elenco dei membri dell'incursione quando l'appartenenza all'incursione è accertata; false o nil usa l'elenco in solitario o del gruppo.",
-- 9865f6c6 English: True removes listed entries; false or nil preserves only listed entries.
[2355] = "True rimuove le voci elencate; false o nil mantiene solo le voci elencate.",
-- 9e3983eb English: True requests raid membership; false or nil requests any group membership.
[2356] = "True richiede l'appartenenza a un'incursione; false o nil richiede l'appartenenza a qualsiasi gruppo.",
-- d660860e English: True requests the formatted pet name; false or omitted reads presence only.
[2357] = "True richiede il nome formattato del famiglio; false o omesso legge solo la presenza.",
-- d60dacff English: True selects percentage target and optional fresh provider facts.
[2358] = "True seleziona la salute bersaglio in percentuale e dati del fornitore facoltativi appena letti.",
-- 755a2020 English: True skips all access to the damage stream.
[2359] = "True salta qualsiasi accesso al flusso dei danni.",
-- 0ff2c956 English: True skips all access to the healing stream.
[2360] = "True salta qualsiasi accesso al flusso delle cure.",
-- e23b6035 English: True to require this exact rank; false or nil follows the available rank.
[2361] = "True per richiedere esattamente questo grado; false o nil segue il grado disponibile.",
-- bd4e75af English: True when array[value] is non-nil.
[2362] = "True quando array[value] non è nil.",
-- af070544 English: True when every visited entry compares equal in both directions.
[2363] = "True quando ogni voce visitata risulta uguale in entrambe le direzioni.",
-- 38e1fab8 English: True when ready by the end of the global cooldown; false when its own cooldown
--     prevents recommendation; nil when the client cannot supply a readable result.
[2364] = "True quando è pronto entro la fine del tempo di recupero globale; false quando il suo tempo di recupero ne impedisce la raccomandazione; nil quando il client non può fornire un risultato leggibile.",
-- 11ccb8e3 English: True when the client reports this spell auto-repeating; false when it reports
--     inactive; nil when unavailable.
[2365] = "True quando il client segnala che l'incantesimo si ripete automaticamente; false quando lo segnala inattivo; nil se non disponibile.",
-- 1b4d0696 English: Truthy skips the damage stream without reading its array.
[2366] = "Un valore truthy salta il flusso dei danni senza leggerne l'array.",
-- 09c7ad07 English: Truthy skips the heals stream without reading its array.
[2367] = "Un valore truthy salta il flusso delle cure senza leggerne l'array.",
-- 1a26aa88 English: Unit key-to-display-name map shown in the selector.
[2368] = "Mappa da chiave dell'unità a nome visualizzato, mostrata nel selettore.",
-- 72d92ef1 English: Unit token to compare with the literal player token.
[2369] = "Identificativo unità da confrontare con l'identificativo letterale player.",
-- a3b5e12b English: Unit token whose current cast or channel should be observed.
[2370] = "Identificativo dell'unità di cui osservare il lancio o l'incanalamento attuale.",
-- 8978c94b English: Unit token whose current health should be observed.
[2371] = "Identificativo dell'unità di cui osservare la salute attuale.",
-- 16f17c11 English: Unit token whose raw level should be observed.
[2372] = "Identificativo dell'unità di cui osservare il livello grezzo.",
-- bb787bde English: Unit token whose raw level should be resolved.
[2373] = "Identificativo dell'unità di cui risolvere il livello grezzo.",
-- 4b2caef5 English: Unit token, such as target; nil uses target.
[2374] = "Identificativo unità, ad esempio target; con nil usa target.",
-- 8b73a7bd English: Validation or availability reason for a nil result.
[2375] = "Motivo di convalida o di indisponibilità quando il risultato è nil.",
-- 193551e6 English: Validation, policy or availability reason for a nil result.
[2376] = "Motivo di convalida, di policy o di indisponibilità quando il risultato è nil.",
-- 2b8bf1ec English: Validation, policy or required-fact availability reason for a nil count.
[2377] = "Motivo di convalida, di policy o di indisponibilità di un dato richiesto quando il conteggio è nil.",
-- f4896f62 English: Value compared with each table value using Lua equality.
[2378] = "Valore confrontato con ciascun valore della tabella usando l'uguaglianza di Lua.",
-- 682b55a9 English: Value passed to the original arithmetic formula.
[2379] = "Valore passato alla formula aritmetica originale.",
-- 53d931f9 English: Value record field to edit; defaults to unit.
[2380] = "Campo del record del valore da modificare; predefinito unit.",
-- 48c786d6 English: Value returned for every other unit.
[2381] = "Valore restituito per ogni altra unità.",
-- 35f7fff6 English: Value returned when unit is player.
[2382] = "Valore restituito quando l'unità è player.",
-- 59731a4c English: Value to display; false is preserved.
[2383] = "Valore da visualizzare; false viene preservato.",
-- d488fb09 English: Visit entries in both tables and compare each value with the indexed value in
--     the other table using Lua equality. Normal indexing and equality metamethods apply; nested
--     contents are not compared recursively.
[2384] = "Visita le voci di entrambe le tabelle e confronta ogni valore con il valore allo stesso indice nell'altra tabella usando l'uguaglianza di Lua. Si applicano la normale indicizzazione e i metametodi di uguaglianza; i contenuti annidati non vengono confrontati ricorsivamente.",
-- b4707a12 English: Weighted health-snapshot change from the original total/count formula; zero for
--     falsy input or when no weighted change was recorded.
[2385] = "Variazione ponderata delle istantanee della salute secondo la formula originale totale/conteggio; zero per un input falso o quando non è stata registrata alcuna variazione ponderata.",
-- c3ba802c English: Weighting window in seconds; nil or false uses the current profile
--     damage_history setting.
[2386] = "Finestra di ponderazione in secondi; nil o false usa l'impostazione damage_history del profilo attuale.",
-- c6cfccd1 English: Whether the original floor-equality or exact numeric-spelling predicate
--     matches.
[2387] = "Indica se corrisponde il predicato originale di uguaglianza dopo floor o di rappresentazione numerica esatta.",
-- 8c0b7ad7 English: Whether the text begins with the exact prefix.
[2388] = "Indica se il testo inizia con il prefisso esatto.",
-- 37054b01 English: Whether the text ends with the exact suffix.
[2389] = "Indica se il testo termina con il suffisso esatto.",
-- 2ae8305f English: With restricted-value only: isActive, true while a cooldown (its own or the
--     global one) is running.
[2390] = "Solo con restricted-value: isActive, true mentre è in corso un tempo di recupero (il proprio o quello globale).",
-- 08c56f26 English: With restricted-value only: isEnabled, false while the cooldown is on hold.
[2391] = "Solo con restricted-value: isEnabled, false mentre il tempo di recupero è sospeso.",
-- 11f0d805 English: With restricted-value only: isOnGCD, true when the running cooldown is the
--     global cooldown; may be nil.
[2392] = "Solo con restricted-value: isOnGCD, true quando il tempo di recupero in corso è quello globale; può essere nil.",
-- 303e2b6b English: Work-limit, data or arithmetic availability reason for nil rate/age.
[2393] = "Motivo di indisponibilità per limite di lavoro, dati o aritmetica quando tasso/età è nil.",
-- 01efc08d English: Wrap text at whitespace boundaries near a target column count. Long words are
--     retained intact.
[2394] = "Manda a capo il testo in corrispondenza degli spazi vicino a un numero di colonne desiderato. Le parole lunghe vengono mantenute intere.",
-- 07e1e312 English: mana selects the explicit live Mana enum; current reads and forwards the actual
--     UnitPowerType identity, including Mana zero.
[2395] = "mana seleziona esplicitamente l'enum Mana attuale; current legge e inoltra l'identità effettiva di UnitPowerType, incluso Mana zero.",
-- c383f3b4 English: noheals selects damage only; nodmg selects healing only; other readable values
--     select both.
[2396] = "noheals seleziona solo i danni; nodmg seleziona solo le cure; altri valori leggibili selezionano entrambi.",
-- d6f5cde1 English: Observe memory for ten minutes without changing polling or forcing garbage
--     collection. /rm perf memory accepts 1–1800 seconds (default 600), plus stop and report.
--     Whole-Lua heap is sampled each second; bounded retained counts every thirty seconds. Addon
--     attribution refreshes only at start and completion; intermediate values are cached with
--     unknown age. Stop completes the final boundary before you open the report. Refreshes can
--     hitch, and their cost is reported. Heap decreases do not prove collection or a leak.
[2397] = "Osserva la memoria per dieci minuti senza modificare il polling né forzare la garbage collection. /rm perf memory accetta da 1 a 1800 secondi (600 per impostazione predefinita), più stop e report. L'heap Lua completo viene campionato ogni secondo; i conteggi trattenuti entro un limite, ogni trenta secondi. L'attribuzione per addon si aggiorna solo all'inizio e al termine; i valori intermedi vengono memorizzati con un'età sconosciuta. Stop completa il limite finale prima che tu apra il report. Gli aggiornamenti possono causare scatti e il loro costo viene riportato. Un calo dell'heap non dimostra né una raccolta né una perdita.",
-- 65848052 English: Open the copyable lifetime report: whole-heap range and decreases, start/end
--     addon attribution, explicitly cached intermediate values, retained key/row counts and capture
--     overhead. Counts are not bytes; unavailable and capped observations stay explicit. Viewing
--     the report never resamples memory.
[2398] = "Apri il report completo dell'intera durata, copiabile: intervallo e cali dell'heap completo, attribuzione per addon all'inizio e alla fine, valori intermedi memorizzati esplicitamente, conteggi di chiavi e righe trattenute e overhead della cattura. I conteggi non sono byte; le osservazioni non disponibili e quelle limitate restano esplicite. Visualizzare il report non ricampiona mai la memoria.",
-- 35fde7b4 English: Measure normal rotation evaluation calls for ten seconds with the native
--     profiler. /rm perf runtime accepts 1–60 seconds (default 10), plus stop and report. The
--     512-dispatch safety limit can end a longer capture sooner. Polling stays unchanged. Stop
--     finalizes partial measurements; the legacy Cancel capture action still cancels. Close
--     configuration after starting. Instrumentation adds overhead; allocation is not retained
--     memory or proof of a leak. Cumulative CPU captures cannot overlap this capture.
[2399] = "Misura per dieci secondi, con il profiler nativo, le normali chiamate di valutazione delle rotazioni. /rm perf runtime accetta da 1 a 60 secondi (predefinito 10), oltre a stop e report. Il limite di sicurezza di 512 dispatch può terminare prima un'acquisizione più lunga. Il polling resta invariato. Interrompi finalizza le misurazioni parziali; l'azione precedente Annulla acquisizione continua ad annullare. Chiudi la configurazione dopo l'avvio. La strumentazione aggiunge un sovraccarico; l'allocazione non è memoria trattenuta né la prova di una perdita di memoria. Le acquisizioni CPU cumulative non possono sovrapporsi a questa acquisizione.",
-- b429fad0 English: Open the copyable runtime report: measured evaluation calls, native elapsed
--     time and gross allocation/deallocation counters. Missing metrics remain unavailable.
--     Measurement covers evaluation calls only, not all addon events or rendering. Reading the
--     report does not sample gameplay.
[2400] = "Apri il report runtime copiabile: chiamate di valutazione misurate, tempo trascorso nativo e contatori lordi di allocazione/deallocazione. Le metriche mancanti restano non disponibili. La misurazione copre solo le chiamate di valutazione, non tutti gli eventi dell'addon né il rendering. Leggere il report non campiona il gioco.",
-- 0eebb1cd English: Enable observation cache
-- Context: Help topic title (General settings help) for the option in the performance section that
--     turns the observation cache on or off.
[2401] = "Attiva la cache delle osservazioni",
-- 5309abf9 English: Optional reuse of repeated getCached and getRetryCached lookups. Observation
--     caching is off by default to reduce table allocations; enabling it can help conditions that
--     repeat the same lookup. Compiled condition facts are independent of this option. The checkbox
--     shows the saved choice for the next reload. Pending means it differs from the running mode.
--     Use /reload to apply it; no full game restart is needed. This choice saves immediately
--     without applying or discarding other pending settings.
[2402] = "Riutilizzo opzionale delle ricerche ripetute di getCached e getRetryCached. La cache delle osservazioni è disattivata per impostazione predefinita per ridurre le allocazioni di tabelle; attivarla può aiutare le condizioni che ripetono la stessa ricerca. I dati compilati delle condizioni sono indipendenti da questa opzione. La casella mostra la scelta salvata per il prossimo ricaricamento. In sospeso significa che differisce dalla modalità in uso. Usa /reload per applicarla; non serve riavviare il gioco. Questa scelta viene salvata subito, senza applicare né scartare altre impostazioni in sospeso.",
-- e2747e8f English: Capture native cumulative function CPU costs and call counts for ten seconds.
--     /rm perf cpu starts the same capture; /rm perf cpu 30 chooses 30 seconds (range 1–60). /rm
--     perf cpu stop finalizes partial counters; /rm perf cpu report opens the copyable result.
--     Capture uses live settings and does not apply pending changes. Close configuration after
--     starting. WoW scriptProfile must already be enabled before a reload; RM never changes it or
--     resets shared counters. Profiling itself adds overhead.
[2403] = "Acquisisci per dieci secondi i costi CPU cumulativi nativi delle funzioni e il numero di chiamate. /rm perf cpu avvia la stessa acquisizione; /rm perf cpu 30 sceglie 30 secondi (intervallo 1–60). /rm perf cpu stop finalizza i contatori parziali; /rm perf cpu report apre il risultato copiabile. L'acquisizione usa le impostazioni attive e non applica le modifiche in sospeso. Chiudi la configurazione dopo l'avvio. scriptProfile di WoW deve essere già attivato prima di un ricaricamento; RM non lo modifica mai e non azzera i contatori condivisi. La profilazione stessa aggiunge un sovraccarico.",
-- 144f6416 English: Open a selectable, copyable report with total addon CPU, measured function
--     costs and calls, sample boundaries, and unavailable or replaced functions. Inclusive costs
--     overlap and must not be added together. Boundary state does not prove configuration or combat
--     stayed unchanged throughout the capture. Untracked functions and native work may account for
--     remaining costs.
[2404] = "Apri un report selezionabile e copiabile con la CPU totale dell'addon, i costi e le chiamate delle funzioni misurate, i limiti del campione e le funzioni non disponibili o sostituite. I costi inclusivi si sovrappongono e non vanno sommati. Lo stato ai limiti non dimostra che la configurazione o il combattimento siano rimasti invariati per tutta l'acquisizione. I costi rimanenti possono dipendere da funzioni non tracciate e lavoro nativo.",
-- 8c53a218 English: Choose a source helper and its name in this Lua body, such as custom.ready or
--     utils.getCached. These are dependency records even when the source and local names match; a
--     different local name is an optional alias. The records identify helpers for loading, export
--     and availability checks. Accepting a completion records the dependency automatically. Typing
--     a call does not infer a dependency: add its qualified name explicitly or accept a completion.
--     WoW globals and existing addon APIs remain directly available. Namespaces are private to this
--     callback and do not supply self. Pass a method receiver explicitly in a namespaced dot call;
--     object:method(x) is shorthand for object.method(object, x). Click the bound source name to
--     open its function; the adjacent arrow changes the mapping. Pending edits offer Apply, Discard
--     or Cancel before navigation. Renaming a function, namespace or binding does not rewrite code.
--     Missing, disabled or invalid dependencies keep consumers unavailable.
[2405] = "Scegli un helper sorgente e il suo nome in questo corpo Lua, come custom.ready o utils.getCached. Sono record di dipendenza anche quando il nome sorgente e quello locale coincidono; un nome locale diverso è un alias opzionale. I record identificano gli helper per il caricamento, l'esportazione e i controlli di disponibilità. Accettare un completamento registra automaticamente la dipendenza. Scrivere una chiamata non deduce una dipendenza: aggiungi esplicitamente il suo nome qualificato o accetta un completamento. Le variabili globali di WoW e le API esistenti degli addon restano direttamente disponibili. I namespace sono privati di questo callback e non forniscono self. In una chiamata con punto su un namespace passa esplicitamente il ricevitore del metodo; object:method(x) è un'abbreviazione di object.method(object, x). Clicca il nome sorgente associato per aprirne la funzione; la freccia accanto cambia la mappatura. Le modifiche in sospeso propongono Applica, Scarta o Annulla prima della navigazione. Rinominare una funzione, un namespace o un'associazione non riscrive il codice. Le dipendenze mancanti, disattivate o non valide mantengono non disponibili chi le usa.",
-- 476ed166 English: Validity Function
-- Context: Yellow heading in the custom condition help: the function that checks the condition
--     itself is valid (all required fields have valid values).
[2406] = "Funzione di validità",
-- fb4e0028 English: Evaluation Function
-- Context: Yellow heading in the custom condition help: the function that evaluates the condition
--     at run time and returns true or false.
[2407] = "Funzione di valutazione",
-- d7868586 English: Print Function
-- Context: Yellow heading in the custom condition help: the function that produces the condition's
--     one-line summary text.
[2408] = "Funzione di stampa",
-- d548d39d English: Widget Function
-- Context: Yellow heading in the custom condition help: the function that builds the condition's
--     editing widgets.
[2409] = "Funzione del widget",
-- e136f1bc English: Help Function
-- Context: Yellow heading in the custom condition help: the function that builds the condition's
--     own help page.
[2410] = "Funzione di aiuto",
-- 4efca0d1 English: About
-- Context: Name of the About page of the settings window (version, author, credits and links); also
--     the title of its help window.
[2411] = "Informazioni",
-- 96c34a07 English: Invalid
-- Context: Status label (with icon) in the rotation help: the rotation or step is not valid, so it
--     cannot be used.
[2412] = "Non valido",
-- 29ab8f0c English: Currently satisfied
-- Context: Status label (with icon) in the rotation help and on rotation cards: the conditions are
--     true right now (shown green).
[2413] = "Attualmente soddisfatta",
-- 28f0d12b English: Not currently satisfied
-- Context: Status label (with icon) in the rotation help and on rotation cards: the conditions are
--     not true right now (shown red).
[2414] = "Attualmente non soddisfatta",
-- 82e28aca English: True while your enabled boss mod (DBM or BigWigs, chosen on the Integrations
--     page) reports a boss encounter in progress. Leave Encounter ID blank for any encounter, or
--     enter the game's encounter ID, which DBM and BigWigs share, to match one boss; while an
--     encounter is active the editor shows its name and ID. This is the boss mod's report, not game
--     state: it starts when the boss mod engages and ends when it records a win, wipe or reset. Use
--     it as a switch condition for encounter-specific rotations; automatic switching picks it up on
--     its normal re-check interval. Unavailable, never simply false, when no boss mod is enabled or
--     loaded.
[2415] = "Vera mentre il boss mod attivo (DBM o BigWigs, scelto nella pagina Integrazioni) segnala uno scontro con un boss in corso. Lascia vuoto ID scontro per qualsiasi scontro, oppure inserisci l'ID scontro del gioco, condiviso da DBM e BigWigs, per riconoscere un solo boss; mentre uno scontro è attivo l'editor ne mostra il nome e l'ID. Questo è ciò che segnala il boss mod, non lo stato del gioco: inizia quando il boss mod rileva l'ingaggio e termina quando registra una vittoria, una disfatta o un azzeramento. Usala come condizione di cambio per rotazioni specifiche di uno scontro; il cambio automatico la rileva al normale intervallo di ricontrollo. Non disponibile, mai semplicemente falsa, quando nessun boss mod è attivato o caricato.",
-- 67327949 English: The stage (phase) your boss mod reports for the current encounter. An encounter
--     whose boss mod has not reported a stage counts as stage 1, and some intermissions are
--     reported as half stages such as 1.5. False when no encounter is in progress; unavailable when
--     no boss mod is enabled or loaded.
[2416] = "La fase che il boss mod segnala per lo scontro attuale. Uno scontro per cui il boss mod non ha segnalato alcuna fase conta come fase 1, e alcuni intermezzi vengono segnalati come mezze fasi, ad esempio 1.5. Falsa quando nessuno scontro è in corso; non disponibile quando nessun boss mod è attivato o caricato.",
-- 0aea56a9 English: Compares the time left on your boss mod's timer for one boss ability,
--     identified by the ability's spell ID; while timers run, the editor lists them with their IDs.
--     Timers are the boss mod's predictions and can shift, pause or be canceled. When no timer for
--     that ability is running the condition is false, so 'is less than 5 seconds' is only true
--     while a timer is actually counting down. Bars without a spell ID, such as pull or respawn
--     timers, are not tracked. Unavailable when no boss mod is enabled or loaded.
[2417] = "Confronta il tempo rimasto sul timer del boss mod per un'abilità del boss, identificata dall'ID incantesimo dell'abilità; mentre i timer sono in corso, l'editor li elenca con i loro ID. I timer sono previsioni del boss mod e possono spostarsi, andare in pausa o essere annullati. Quando nessun timer per quell'abilità è in corso la condizione è falsa, quindi 'è inferiore a 5 secondi' è vera solo mentre un timer sta effettivamente scorrendo. Le barre senza ID incantesimo, come i timer di ingaggio o di ricomparsa, non vengono tracciate. Non disponibile quando nessun boss mod è attivato o caricato.",
-- 68c38a65 English: Sound Alert
-- Context: Yellow heading in the rotation help, in the announcements part: the sound that can be
--     played along with an announcement.
[2418] = "Avviso sonoro",
-- 7a0ac7f9 English: Any (OR) checks children in order and stops at the first match. An empty group
--     does not match. Encountered unavailable data remains unavailable; later children are skipped.
[2419] = "Qualsiasi (OR) controlla i figli in ordine e si ferma alla prima corrispondenza. Un gruppo vuoto non corrisponde. I dati non disponibili incontrati restano non disponibili; i figli successivi vengono saltati.",
-- 0cda3eb2 English: Every rotation has an identifier (ID), shown beside its priority: type /rm set
--     <id> to choose it (any case), /rm set auto to go back to automatic switching, and /rm list to
--     see every identifier. A Built In's identifier is fixed; yours is made from its name until you
--     change it.
[2420] = "Ogni rotazione ha un identificatore (ID), mostrato accanto alla sua priorità: scrivi /rm set <id> per sceglierla (maiuscole e minuscole non contano), /rm set auto per tornare al cambio automatico e /rm list per vedere tutti gli identificatori. L'identificatore di una rotazione integrata è fisso; il tuo è ricavato dal suo nome finché non lo cambi.",
-- 5530025a English: Choosing a rotation
-- Context: Heading in the rotation help: how the addon decides which rotation is used. Noun phrase
--     with gerund.
[2421] = "Scegliere una rotazione",
-- 359bbdff English: Automatic switching tries the enabled rotations in priority order, yours and
--     Built Ins alike: higher numbers are tried first, equal priorities by name. It picks the first
--     that matches; a rotation with no switch condition always matches, so turn it off to keep it
--     from being chosen. The fallback (Default) is used only when none matches. The rotation list
--     is sorted in this same order and shows each priority.
[2422] = "Il cambio automatico prova le rotazioni attivate in ordine di priorità, le tue e le integrate allo stesso modo: i numeri più alti vengono provati per primi, a parità di priorità in base al nome. Sceglie la prima che corrisponde; una rotazione senza condizione di cambio corrisponde sempre, quindi disattivala per evitare che venga scelta. La rotazione di riserva (Predefinito) viene usata solo quando nessuna corrisponde. L'elenco delle rotazioni è ordinato nello stesso modo e mostra ogni priorità.",
-- 1adf9c9d English: Priority sits beside Enabled at the top of the editor. A Built In cannot be
--     edited, but its Enabled setting and priority are yours to change for this profile: they are
--     saved at once, shown in amber when they differ from how it ships, and Reset to default puts
--     it back. Copy a Built In to your rotations to edit anything else.
[2423] = "La priorità si trova accanto ad Attivato, in cima all'editor. Una rotazione integrata non si può modificare, ma la sua impostazione Attivato e la sua priorità sono tue per questo profilo: vengono salvate subito, mostrate in ambra quando differiscono da come vengono fornite, e Ripristina predefinito le riporta com'erano. Copia una rotazione integrata tra le tue rotazioni per modificare qualsiasi altra cosa.",
-- 89d48b07 English: A Built In shows a blue Read-Only pill in place of Undo and Redo; Duplicate
--     makes your own copy. It loads only for the edition and class it was written for (the pill's
--     tooltip). The specializations it is for show in the picker before its name; any level it
--     needs is part of its switch condition. The switch's tooltip says when it can be selected
--     together with another rotation, or is for another specialization.
[2424] = "Una rotazione integrata mostra un indicatore blu Sola lettura al posto di Annulla e Ripeti; Duplica ne crea una copia tua. Si carica solo per l'edizione e la classe per cui è stata scritta (il tooltip dell'indicatore). Le specializzazioni a cui è destinata compaiono nel selettore prima del suo nome; qualsiasi livello richiesto fa parte della sua condizione di cambio. Il tooltip dell'interruttore indica quando può essere selezionata insieme a un'altra rotazione, o se è per un'altra specializzazione.",
-- c85105a0 English: In the list, a red border means the rotation cannot be selected (the tooltip
--     names why), gray means it is switched off, and an amber bar means it can be selected at the
--     same time as another rotation (yours or Built In), so only priority decides between them; a
--     wider bar means they also have the same priority and the name decides. /rm why lists the
--     order and what automatic switching would choose now.
[2425] = "Nell'elenco, un bordo rosso significa che la rotazione non può essere selezionata (il tooltip ne indica il motivo), grigio che è disattivata, e una barra ambra che può essere selezionata contemporaneamente a un'altra rotazione (tua o integrata), quindi decide tra loro solo la priorità; una barra più larga significa che hanno anche la stessa priorità e decide il nome. /rm why elenca l'ordine e ciò che il cambio automatico sceglierebbe ora.",
-- 929902f7 English: Each rotation says which specializations it is for, in the picker before its
--     name: several, or Any. It is listed, in the minimap menu and for /rm set, only while you play
--     one of them; its switch condition never hides it. Automatic switching checks the
--     specialization first, then the switch condition, then priority; a rotation with no switch
--     condition matches whenever its specialization and level apply, so priority alone decides;
--     turn it off to keep it for choosing by hand. The specialization menu above the list's search
--     box starts at the one you are playing; choose another, or All specializations, to see theirs.
--     Where the game has dual specialization instead of named specializations (Classic Era, TBC,
--     Wrath, Cataclysm and Forever), they are your primary and secondary talents: exports leave
--     them out, and an import is for the talents the list shows.
[2426] = "Ogni rotazione indica per quali specializzazioni è pensata, nel selettore prima del suo nome: più di una, oppure Qualsiasi. Compare nell'elenco, nel menu della minimappa e per /rm set solo mentre giochi una di esse; la sua condizione di cambio non la nasconde mai. Il cambio automatico controlla prima la specializzazione, poi la condizione di cambio, poi la priorità; una rotazione senza condizione di cambio corrisponde ogni volta che si applicano la sua specializzazione e il suo livello, quindi decide solo la priorità; disattivala per tenerla da scegliere a mano. Il menu delle specializzazioni sopra la casella di ricerca dell'elenco parte da quella che stai giocando; scegline un'altra, o Tutte le specializzazioni, per vedere le loro. Dove il gioco ha la doppia specializzazione invece di specializzazioni con nome (Classic Era, TBC, Wrath, Cataclysm e Forever), esse sono i tuoi talenti primari e secondari: le esportazioni le omettono, e un'importazione vale per i talenti mostrati nell'elenco.",
-- 4c969557 English: Stop ends lower priority actions. The implicit auto-attack (Attack or Shoot)
--     remains eligible unless you suppress it. An unavailable Stop condition also suppresses it.
--     Optional reminders remain independent.
[2427] = "Stop termina le azioni a priorità inferiore. L'attacco automatico implicito (Attacco o Tiro) resta idoneo a meno che tu non lo sopprima. Una condizione di Stop non disponibile sopprime anche questo. I promemoria opzionali restano indipendenti.",
-- 4db9065c English: All (AND) checks children in order and stops at the first non-match. An empty
--     group matches. Encountered unavailable data remains unavailable; later children are skipped.
[2428] = "Tutte (AND) controlla i figli in ordine e si ferma alla prima mancata corrispondenza. Un gruppo vuoto corrisponde. I dati non disponibili incontrati restano non disponibili; i figli successivi vengono saltati.",
-- 2253ae22 English: Select cards with Ctrl-click or Shift-click. Group with All or Any, negate
--     each, move or drag, and remove. Undo and Redo affect only the draft until Apply. Groups can
--     be named and collapsed.
[2429] = "Seleziona le schede con Ctrl+clic o Maiusc+clic. Raggruppa con Tutte o Qualsiasi, nega ciascuna, sposta o trascina e rimuovi. Annulla e Ripeti agiscono solo sulla bozza fino ad Applica. I gruppi possono avere un nome ed essere compressi.",
-- ef5cde35 English: Built In and custom rotations use the same cards. Built In rotations are
--     read-only; enable or disable them, inspect their conditions, or Duplicate to edit.
[2430] = "Le rotazioni integrate e personalizzate usano le stesse schede. Le rotazioni integrate sono in sola lettura: attivale o disattivale, esaminane le condizioni, oppure usa Duplica per modificarle.",
-- 598c73a5 English: Custom edits stay in a private draft. Apply saves; Discard restores the saved
--     rotation. Undo and Redo include card deletion, movement, fields and conditions. Apply before
--     reloading or logging out.
[2431] = "Le modifiche personalizzate restano in una bozza privata. Applica salva; Scarta ripristina la rotazione salvata. Annulla e Ripeti includono eliminazione e spostamento delle schede, campi e condizioni. Applica prima di ricaricare o uscire dal gioco.",
-- 55e4c200 English: Closing the window retains drafts for this session. Switching rotations or
--     opening comparison or transfer asks whether to Apply, Discard or Cancel when changes are
--     pending.
[2432] = "Chiudere la finestra conserva le bozze per questa sessione. Cambiare rotazione o aprire il confronto o il trasferimento chiede se Applicare, Scartare o Annullare quando ci sono modifiche in sospeso.",
-- 770e0bb6 English: The switch condition selects the rotation automatically; with none, it is
--     selected whenever its specialization and level apply. Edit changes its condition tree. The
--     fallback rotation is selected when no other rotation matches.
[2433] = "La condizione di cambio seleziona automaticamente la rotazione; se non c'è, viene selezionata ogni volta che si applicano la sua specializzazione e il suo livello. Modifica cambia il suo albero di condizioni. La rotazione di riserva viene selezionata quando nessun'altra rotazione corrisponde.",
-- 7423362f English: Cooldown cards have their own scrolling workspace and highlight independently
--     of the sequence. Add cooldown creates a reminder; clicking its action shows local highlight
--     settings.
[2434] = "Le schede dei tempi di recupero hanno un'area di lavoro scorrevole propria e vengono evidenziate indipendentemente dalla sequenza. Aggiungi tempo di recupero crea un promemoria; cliccarne l'azione mostra le impostazioni di evidenziazione locali.",
-- 758bf6a1 English: Add action appends a priority action. Drag an Add control into a gap to insert
--     there. Click a card name to rename it, expand for action fields, or click its condition text
--     to edit the guard.
[2435] = "Aggiungi azione aggiunge in fondo un'azione prioritaria. Trascina un controllo Aggiungi in uno spazio vuoto per inserirla lì. Clicca il nome di una scheda per rinominarla, espandila per i campi dell'azione, o clicca il testo della sua condizione per modificare la guardia.",
-- 9b6cac99 English: Adding a branch moves following steps into its True arm. False is on the left
--     in red; True is on the right in green. The mode pill cycles Evaluate condition, Always true
--     and Always false. Unreachable cards are gray.
[2436] = "Aggiungere un ramo sposta i passi successivi nel suo braccio Vero. Falso è a sinistra in rosso; Vero è a destra in verde. L'etichetta della modalità alterna Valuta condizione, Sempre vero e Sempre falso. Le schede irraggiungibili sono grigie.",
-- 5fc9817f English: Ordinary dragging moves one card and its own subtree. Hold Ctrl when starting a
--     drag to carry that card and every following sibling, including their branch subtrees. Drop
--     into a branch arm gap to move there. Up / Down always moves one card. A group cannot be
--     dropped into itself or a carried descendant.
[2437] = "Il normale trascinamento sposta una scheda e il suo sottoalbero. Tieni premuto Ctrl all'inizio del trascinamento per portare con sé quella scheda e tutte quelle successive allo stesso livello, inclusi i sottoalberi dei loro rami. Rilascia in uno spazio vuoto di un braccio per spostarla lì. Su / Giù sposta sempre una sola scheda. Un gruppo non può essere rilasciato dentro sé stesso o dentro un discendente trasportato.",
-- a6e094f9 English: An evaluated branch follows one arm, then rejoins later siblings. Stop ends the
--     sequence. Independent cooldowns still apply; implicit auto-attack (Attack or Shoot) remains
--     available unless the Stop suppresses it.
[2438] = "Un ramo valutato segue un braccio, poi si ricongiunge agli elementi successivi. Stop termina la sequenza. I tempi di recupero indipendenti si applicano comunque; l'attacco automatico implicito (Attacco o Tiro) resta disponibile a meno che lo Stop non lo sopprima.",
-- 4e0f26c5 English: Invalid or incomplete cards remain editable. Apply validates both branch arms
--     without running custom condition code. Deleting a whole custom rotation requires confirmation
--     and cannot be undone.
[2439] = "Le schede non valide o incomplete restano modificabili. Applica convalida entrambi i bracci del ramo senza eseguire il codice delle condizioni personalizzate. Eliminare un'intera rotazione personalizzata richiede una conferma e non può essere annullato.",
-- c54e950a English: List and Cooldowns use flat scrollbars or the mouse wheel. Diagram uses wheel
--     zoom and dragging empty space to pan. Window scaling applies when the slider is released and
--     also affects RM child windows.
[2440] = "Elenco e Tempi di recupero usano barre di scorrimento piatte o la rotellina del mouse. Il diagramma usa la rotellina per lo zoom e il trascinamento dello spazio vuoto per spostarsi. Il ridimensionamento della finestra si applica al rilascio del cursore e riguarda anche le finestre secondarie di RM.",
-- e90e0aef English: Highlight preview
-- Context: Help topic title in General settings help for the highlight preview (the example that
--     shows the chosen highlight).
[2441] = "Anteprima evidenziazione",
-- aafdf428 English: Add category
-- Context: Help topic title in the Conditions help for the Add category button.
[2442] = "Aggiungi categoria",
-- 539a15c9 English: Choose and edit
-- Context: Section title in the condition editor help: how to choose a condition type and edit its
--     fields.
[2443] = "Scegli e modifica",
-- cfb4186c English: Click a condition type to search or browse categories. Dismissing the picker or
--     choosing the same type keeps its fields. Click the condition summary to edit its fields. The
--     chevron switches between name only and summary; the double chevron closes the fields.
[2444] = "Clicca su un tipo di condizione per cercare o sfogliare le categorie. Chiudendo il selettore o scegliendo lo stesso tipo, i suoi campi restano invariati. Clicca sul riepilogo della condizione per modificarne i campi. La freccia alterna tra solo nome e riepilogo; la doppia freccia chiude i campi.",
-- 0e19bead English: Click a name to rename it. Clear a custom step name to restore its action name.
--     Click a collapsed title to show its summary. Click action or condition text to open its
--     details; the double chevron returns from fields to the summary.
[2445] = "Clicca su un nome per rinominarlo. Svuota il nome personalizzato di un passo per ripristinare il nome della sua azione. Clicca su un titolo compresso per mostrarne il riepilogo. Clicca sul testo di un'azione o di una condizione per aprirne i dettagli; la doppia freccia torna dai campi al riepilogo.",
-- 73ff3024 English: Click condition text to edit when this card can run. Enabled / Disabled
--     preserves the card while switching its participation. Actions also require known or carried
--     actions, usable resources, cooldown readiness and valid range.
[2446] = "Clicca sul testo della condizione per modificare quando questa scheda può essere eseguita. Attivata / Disattivata conserva la scheda cambiandone solo la partecipazione. Le azioni richiedono inoltre azioni conosciute o trasportate, risorse utilizzabili, tempo di recupero pronto e portata valida.",
-- 9c1c1630 English: Click the action to edit its type, spell or item. The leading icon previews the
--     effect. Effect selects a style; Magnification changes its size. Click the swatch or edit RGBA
--     on the 0–1 scale. Arrows adjust position; V / H show offsets. Default restores profile
--     values. Sound selection and Play preview an audible reminder.
[2447] = "Clicca sull'azione per modificarne il tipo, l'incantesimo o l'oggetto. L'icona iniziale mostra un'anteprima dell'effetto. Effetto seleziona uno stile; Ingrandimento ne cambia le dimensioni. Clicca sul campione di colore o modifica i valori RGBA sulla scala 0–1. Le frecce regolano la posizione; V / O mostrano gli scostamenti. Predefinito ripristina i valori del profilo. La scelta del suono e Riproduci forniscono un'anteprima di un promemoria sonoro.",
-- 3edd382d English: Click the guard text to edit the branch condition. Evaluate uses that
--     condition; Always true / Always false skips it. False is left and red; True is right and
--     green. The branch icon hides both arms without changing them. Click True or False to fold
--     only that arm; its hidden count remains visible. Gray cards in a forced arm are unreachable.
[2448] = "Clicca sul testo della guardia per modificare la condizione del ramo. Valuta usa quella condizione; Sempre vero / Sempre falso la salta. Falso è a sinistra e rosso; Vero è a destra e verde. L'icona del ramo nasconde entrambi i rami senza modificarli. Clicca su Vero o Falso per comprimere solo quel ramo; il numero di elementi nascosti resta visibile. Le schede grigie in un ramo forzato non sono raggiungibili.",
-- 55129537 English: Conditions and state
-- Context: Section title in the rotation editor help for the cards that combine conditions and the
--     state they show.
[2449] = "Condizioni e stato",
-- eacf49cb English: Configure recommendation timing, automatic switching, history, preview and
--     profile highlight defaults. Labels are on the left. Checkboxes toggle options, sliders show
--     numeric values, and fields validate before saving.
[2450] = "Configura i tempi dei suggerimenti, il cambio automatico, la cronologia, l'anteprima e le evidenziazioni predefinite del profilo. Le etichette sono a sinistra. Le caselle attivano o disattivano le opzioni, i cursori mostrano valori numerici e i campi vengono convalidati prima del salvataggio.",
-- 63ee762f English: Drag one card into a highlighted gap; hold Ctrl when starting the drag to carry
--     that card and all following siblings. A branch always carries its children. Use Up / Down on
--     the left to move one card. Duplicate copies the card and the red trash can deletes it.
--     Cooldowns are independent, so they have no move arrows.
[2451] = "Trascina una scheda in uno spazio evidenziato; tieni premuto Ctrl all'inizio del trascinamento per portare con sé quella scheda e tutte quelle successive dello stesso livello. Un ramo porta sempre con sé i suoi figli. Usa Su / Giù a sinistra per spostare una scheda. Duplica copia la scheda e il cestino rosso la elimina. I tempi di recupero sono indipendenti, quindi non hanno frecce di spostamento.",
-- 24e03e5b English: Drag a card into one highlighted gap, or use the left-side Up / Down arrows.
--     Hold Ctrl when starting a drag to carry the card and all following siblings. Groups always
--     carry their children. Unavailable moves are gray. Ctrl-click or Shift-click selects several
--     cards for grouping; dragging an existing selection moves that selection. Duplicate copies a
--     card; Split group removes its wrapper; the red trash can deletes it. Add condition and Add
--     group append when clicked or insert where dropped.
[2452] = "Trascina una scheda in uno spazio evidenziato oppure usa le frecce Su / Giù a sinistra. Tieni premuto Ctrl all'inizio del trascinamento per portare con sé la scheda e tutte quelle successive dello stesso livello. I gruppi portano sempre con sé i loro figli. Gli spostamenti non disponibili sono grigi. Ctrl-clic o Maiusc-clic seleziona più schede da raggruppare; trascinare una selezione esistente sposta quella selezione. Duplica copia una scheda; Dividi gruppo rimuove il suo contenitore; il cestino rosso la elimina. Aggiungi condizione e Aggiungi gruppo aggiungono in fondo se cliccati o inseriscono dove vengono rilasciati.",
-- adb0a440 English: Editing settings
-- Context: Section title in the settings help: how text fields and the Apply/Discard draft work.
[2453] = "Modifica delle impostazioni",
-- 1352b3ca English: Highlight effects
-- Context: Section title in the rotation editor help for the highlight effect options of an action
--     card.
[2454] = "Effetti di evidenziazione",
-- fc1e5a5a English: If / Unless toggles negation. Enabled / Disabled keeps the saved fields while
--     skipping evaluation. All / Any changes AND / OR. Click a group name to rename it; the branch
--     icon hides or shows its children. Gray descendants cannot be reached.
[2455] = "Se / Se non alterna la negazione. Attivata / Disattivata conserva i campi salvati ma salta la valutazione. Tutte / Qualsiasi alterna tra AND / OR. Clicca sul nome di un gruppo per rinominarlo; l'icona del ramo nasconde o mostra i suoi figli. I discendenti grigi non sono raggiungibili.",
-- 0e86051f English: Names and details
-- Context: Section title in the rotation editor help: how to rename steps and open their details.
[2456] = "Nomi e dettagli",
-- e0d1f576 English: Search or filter the rotation roster, then select a rotation. Blue Built In
--     rotations use the same editor but remain read-only; Duplicate makes an editable copy. The
--     name and Metadata describe the rotation. Switch condition selects when it applies. Use the
--     Rotation and Cooldowns tabs to select the content below the switch condition. Cooldowns
--     highlight independently of the ordered rotation.
[2457] = "Cerca o filtra l'elenco delle rotazioni, poi seleziona una rotazione. Le rotazioni Integrate in blu usano lo stesso editor ma restano in sola lettura; Duplica crea una copia modificabile. Il nome e i Metadati descrivono la rotazione. La condizione di cambio stabilisce quando si applica. Usa le schede Rotazione e Tempi di recupero per scegliere il contenuto sotto la condizione di cambio. I tempi di recupero vengono evidenziati indipendentemente dalla rotazione ordinata.",
-- 42691826 English: The question mark opens full Help for its subject. Hover controls for brief
--     tips. Undo / Redo affect the draft. Apply saves; Discard or Cancel abandons draft changes.
--     Red borders mark invalid or incomplete data.
[2458] = "Il punto interrogativo apre l'Aiuto completo sull'argomento. Passa il mouse sui controlli per brevi suggerimenti. Annulla / Ripeti agiscono sulla bozza. Applica salva; Scarta o Annulla abbandonano le modifiche della bozza. I bordi rossi indicano dati non validi o incompleti.",
-- d68ae9c9 English: Using this page
-- Context: Section title at the top of the help for the Functions and Integrations pages: a short
--     guide to the page.
[2459] = "Uso di questa pagina",
-- 642f28cb English: Version, author, credits and project links are shown here. Click a link field
--     to select its text for copying.
[2460] = "Qui sono mostrati versione, autore, riconoscimenti e link del progetto. Clicca su un campo link per selezionarne il testo e copiarlo.",
-- 9cea69fd English: Window controls
-- Context: Section title in the help: the buttons and controls of the window frame.
[2461] = "Controlli della finestra",
-- efe10c80 English: Primary
-- Context: Help topic title for the settings made for the first (primary) talent specialization;
--     used only when the game has no word for it.
[2462] = "Principale",
-- 62f2ccff English: Secondary
-- Context: Help topic title for the settings made for the second (secondary) talent specialization;
--     used only when the game has no word for it.
[2463] = "Secondario",
-- a91d0087 English: Delete category
-- Context: Help topic title in the Conditions help for the Delete category button.
[2464] = "Elimina categoria",
-- 315dca68 English: Rename the selected category in Manage categories. Built-in categories cannot
--     be renamed or deleted.
[2465] = "Rinomina la categoria selezionata in Gestisci categorie. Le categorie integrate non possono essere rinominate né eliminate.",
-- f6fad90e English: Add an empty named category from the category-management list. Move To in
--     condition settings assigns a condition to it.
[2466] = "Aggiungi una categoria vuota con nome dall'elenco di gestione delle categorie. Sposta in, nelle impostazioni della condizione, vi assegna una condizione.",
-- b31029f7 English: In Manage categories, move the selected category earlier in the category list.
[2467] = "In Gestisci categorie, sposta la categoria selezionata più in alto nell'elenco delle categorie.",
-- 277b5e7b English: In Manage categories, move the selected category later in the category list.
[2468] = "In Gestisci categorie, sposta la categoria selezionata più in basso nell'elenco delle categorie.",
-- 32a806a4 English: Delete a named category after confirmation. Its conditions remain available
--     under Other; their definitions are preserved.
[2469] = "Elimina una categoria con nome dopo la conferma. Le sue condizioni restano disponibili in Altro; le loro definizioni vengono conservate.",
-- e20c9279 English: Filter the visible condition list by name or identifier. The category filter
--     still applies.
[2470] = "Filtra l'elenco delle condizioni visibili per nome o identificativo. Il filtro per categoria resta applicato.",
-- 2715ffec English: Allow this condition type to be used when automatically selecting a rotation.
[2471] = "Consenti l'uso di questo tipo di condizione nella selezione automatica di una rotazione.",
-- 91c0665b English: Hide this condition from the Other picker category. Explicit named-category and
--     Switch membership remain available.
[2472] = "Nascondi questa condizione dalla categoria Altro del selettore. L'appartenenza esplicita a categorie con nome e a Cambio resta disponibile.",
-- 4a954399 English: Condition order
-- Context: Help topic title in the Conditions help: how to reorder conditions and categories.
[2473] = "Ordine delle condizioni",
-- 54375409 English: Apply / Cancel
-- Context: Help topic title for the pair of buttons that save or abandon changes in the announce
--     and effect editors.
[2474] = "Applica / Annulla",
-- af06c200 English: Choose a named category or Other, then use Apply beside the destination to
--     stage the move. Page Apply saves all pending changes. Use Switch Condition separately for
--     automatic-switch availability.
[2475] = "Scegli una categoria con nome o Altro, poi usa Applica accanto alla destinazione per preparare lo spostamento. Applica della pagina salva tutte le modifiche in sospeso. Usa Condizione di cambio a parte per la disponibilità nel cambio automatico.",
-- 304b61a5 English: Select several cards
-- Context: Section title in the rotation editor help: how to select more than one rotation card.
[2476] = "Seleziona più schede",
-- 1e77459b English: Ctrl-click cards to add or remove them from the selection; Shift-click selects
--     the siblings between it and the last clicked card. Shift-drag on empty canvas draws a box
--     that selects every card it touches (Ctrl+Shift-drag adds). With several cards selected, the
--     strip above the canvas groups them as All or Any, and Duplicate, Enable, Disable and Delete
--     act on every selected card; one Undo reverses each. Drag any selected card to move the
--     selection.
[2477] = "Ctrl-clic sulle schede le aggiunge o le rimuove dalla selezione; Maiusc-clic seleziona le schede dello stesso livello comprese tra quella e l'ultima cliccata. Maiusc-trascinamento su un'area vuota disegna un riquadro che seleziona ogni scheda che tocca (Ctrl+Maiusc-trascinamento aggiunge). Con più schede selezionate, la barra sopra l'area di lavoro le raggruppa come Tutte o Qualsiasi, e Duplica, Attiva, Disattiva ed Elimina agiscono su ogni scheda selezionata; un solo Annulla le ripristina tutte. Trascina una qualsiasi scheda selezionata per spostare la selezione.",
-- 47834c1a English: Ctrl-click cards to add or remove them from the selection; Shift-click a title
--     or condition to select the siblings between it and the last clicked card. Shift-drag on empty
--     canvas draws a box that selects every card it touches (Ctrl+Shift-drag adds). Drag any
--     selected card to move the whole selection to one gap. Beside Apply, Duplicate, Enable,
--     Disable and Delete act on every selected card, and one Undo reverses each. Branches keep
--     their Evaluate / Always mode. Click empty canvas to clear the selection.
[2478] = "Ctrl-clic sulle schede le aggiunge o le rimuove dalla selezione; Maiusc-clic su un titolo o una condizione seleziona le schede dello stesso livello comprese tra quella e l'ultima cliccata. Maiusc-trascinamento su un'area vuota disegna un riquadro che seleziona ogni scheda che tocca (Ctrl+Maiusc-trascinamento aggiunge). Trascina una qualsiasi scheda selezionata per spostare l'intera selezione in uno spazio. Accanto ad Applica, Duplica, Attiva, Disattiva ed Elimina agiscono su ogni scheda selezionata, e un solo Annulla le ripristina tutte. I rami mantengono la loro modalità Valuta / Sempre. Clicca su un'area vuota per annullare la selezione.",
-- 2c6fdc3c English: Select a profile in the sidebar to inspect it, then Activate profile to switch.
--     New and Duplicate open a named draft with Apply and Cancel. Import stages a validated new
--     profile; Compare shows setting differences. Copy and Reset replace the active profile after
--     confirmation; the red trash deletes an inactive profile.
[2479] = "Seleziona un profilo nella barra laterale per esaminarlo, poi usa Attiva profilo per passare a quello. Nuovo e Duplica aprono una bozza con nome con Applica e Annulla. Importa prepara un nuovo profilo convalidato; Confronta mostra le differenze nelle impostazioni. Copia e Reimposta sostituiscono il profilo attivo dopo la conferma; il cestino rosso elimina un profilo non attivo.",
-- 80f29cb1 English: The condition ordering controls are arrows and draggable rows in the sidebar of
--     the selected category. In Manage categories, the same controls order the categories
--     themselves.
[2480] = "I controlli di ordinamento delle condizioni sono le frecce e le righe trascinabili nella barra laterale della categoria selezionata. In Gestisci categorie, gli stessi controlli ordinano le categorie stesse.",
-- fdef8f0b English: Unticked, any rank of the spell matches: a numeric spell selection also
--     recognizes auras with the same readable localized spell name. Ticked, only the exact spell ID
--     you chose matches. Conditions saved before this option keep the exact ID until you untick it.
--     Spell names already match by name. Unavailable metadata or restricted aura identity stays
--     unavailable, including under NOT. Different spells sharing a name can match; tick the option
--     when that distinction matters.
[2481] = "Se deselezionata, corrisponde qualsiasi grado dell'incantesimo: una selezione numerica riconosce anche le aure con lo stesso nome di incantesimo localizzato leggibile. Se selezionata, corrisponde solo l'ID incantesimo esatto scelto. Le condizioni salvate prima di questa opzione mantengono l'ID esatto finché non la deselezioni. I nomi di incantesimo corrispondono già per nome. Metadati non disponibili o un'identità dell'aura con restrizioni restano non disponibili, anche sotto NOT. Incantesimi diversi con lo stesso nome possono corrispondere; seleziona l'opzione quando questa distinzione conta.",
-- a851dbf4 English: Unticked (the default), any rank of the spell matches. Ticked, only the rank
--     you chose matches.
[2482] = "Se deselezionata (predefinito), corrisponde qualsiasi grado dell'incantesimo. Se selezionata, corrisponde solo il grado scelto.",
-- 6ef93df0 English: Unticked (the default), any rank of the spell matches. Ticked, only the rank
--     you chose matches, and that rank must be on your action bars.
[2483] = "Se deselezionata (predefinito), corrisponde qualsiasi grado dell'incantesimo. Se selezionata, corrisponde solo il grado scelto, e quel grado deve trovarsi sulle tue barre delle azioni.",
-- 5c9c3144 English: A spell picked in the editor is matched by its spell ID, so the condition works
--     on every client language. Conditions saved with a spell name keep matching by that name. If
--     the client cannot read the spell being cast, the condition is unavailable, including under
--     NOT.
[2484] = "Un incantesimo scelto nell'editor viene riconosciuto dal suo ID, quindi la condizione funziona in ogni lingua del client. Le condizioni salvate con il nome di un incantesimo continuano a corrispondere per quel nome. Se il client non riesce a leggere l'incantesimo lanciato, la condizione non è disponibile, anche sotto NOT.",
-- c647cb40 English: A spell picked in the editor is matched by its spell ID, so the condition works
--     on every client language. Any rank of that spell matches unless Use this exact spell rank is
--     ticked. Conditions saved with a spell name keep matching by that name. If the client cannot
--     read the spell being cast, the condition is unavailable, including under NOT.
[2485] = "Un incantesimo scelto nell'editor viene riconosciuto dal suo ID incantesimo, quindi la condizione funziona in ogni lingua del client. Qualsiasi grado di quell'incantesimo corrisponde, a meno che non sia selezionato Usa esattamente questo grado dell'incantesimo. Le condizioni salvate con il nome di un incantesimo continuano a corrispondere a quel nome. Se il client non riesce a leggere l'incantesimo in lancio, la condizione non è disponibile, anche con NOT.",
-- 51b10901 English: Navigating rotations
-- Context: Section title in the rotation editor help: zooming, panning and switching views.
[2486] = "Navigare tra le rotazioni",
-- 35f68027 English: Enabled / Disabled
-- Context: Help topic title in the Announces help for the checkbox that switches an announcement on
--     or off.
[2487] = "Attivato / Disattivato",
-- 922d8056 English: Announcement substitutions
-- Context: Help topic title in the Announces help: the {{target}}, {{spell}} and {{event}}
--     placeholders that can be put into announcement text.
[2488] = "Sostituzioni negli annunci",
-- 63ff2d53 English: New, Duplicate, Import/Export and Compare
[2489] = "Nuovo, Duplica, Importa/Esporta e Confronta",
-- baa6c2fc English: Announcement details stay always expanded while editing. Press Enter or leave a
--     text field to stage its value; Apply saves the draft. Invalid fields must be corrected before
--     Apply; Discard abandons pending changes. Searchable selectors open on click and filter as you
--     type. The page Help icon explains every option and text substitution.
[2490] = "I dettagli dell'annuncio restano sempre espansi durante la modifica. Premi Invio o esci da un campo di testo per preparare il suo valore; Applica salva la bozza. I campi non validi vanno corretti prima di Applica; Scarta abbandona le modifiche in sospeso. I selettori con ricerca si aprono con un clic e filtrano mentre scrivi. L'icona Aiuto della pagina spiega ogni opzione e sostituzione di testo.",
-- 79d463fa English: Announce selected spell casts or item uses independently of your active
--     rotation, or invoke a configured Via Script/Macro entry directly. Select an entry in the
--     sidebar, or use New to prepare one. The trigger applies to every ordered output card; each
--     card has its own destination and conditions. These settings do not cast spells or use items.
--     Cast-triggered announcements follow RM's combat-data policy and do not run on reference-only
--     clients.
[2491] = "Annuncia i lanci di incantesimi o gli usi di oggetti selezionati indipendentemente dalla rotazione attiva, oppure richiama direttamente una voce Tramite script/macro configurata. Seleziona una voce nella barra laterale o usa Nuovo per prepararne una. L'attivatore vale per ogni scheda di uscita ordinata; ogni scheda ha la propria destinazione e le proprie condizioni. Queste impostazioni non lanciano incantesimi né usano oggetti. Gli annunci attivati dai lanci seguono la politica di RM sui dati di combattimento e non funzionano sui client di sola consultazione.",
-- 405280cc English: An optional name identifies this announcement in the sidebar. Without one, the
--     action name or Via Script/Macro identifier is used. Changing this display name does not
--     change the watched action or callable identifier.
[2492] = "Un nome facoltativo identifica questo annuncio nella barra laterale. Se manca, viene usato il nome dell'azione o l'identificativo Tramite script/macro. Cambiare questo nome visualizzato non cambia l'azione osservata né l'identificativo richiamabile.",
-- d90e5cae English: Choose Spell, Pet Spell, Item or Via Script/Macro. Changing type clears the
--     previous action and exact-rank choice. Via Script/Macro uses an Identifier instead of a cast
--     event or stored action; switching back restores the event selector. Choosing the current type
--     keeps its fields.
[2493] = "Scegli Incantesimo, Incantesimo del famiglio, Oggetto o Tramite script/macro. Cambiare tipo cancella l'azione precedente e la scelta del grado esatto. Tramite script/macro usa un Identificativo invece di un evento di lancio o di un'azione memorizzata; tornando indietro il selettore dell'evento viene ripristinato. Scegliendo il tipo attuale i suoi campi restano invariati.",
-- 198d0d82 English: Watch one of your spells. Choose the spell in the searchable field below Action
--     Type.
[2494] = "Osserva uno dei tuoi incantesimi. Scegli l'incantesimo nel campo con ricerca sotto Tipo di azione.",
-- bb010073 English: Watch a spell from your pet spellbook. The spell selector uses the pet catalog
--     for this action type.
[2495] = "Osserva un incantesimo del libro del tuo famiglio. Per questo tipo di azione il selettore usa il catalogo del famiglio.",
-- c331b8d1 English: Watch item-use spells from a reusable item set or a custom list. This is an
--     announcement trigger; it does not choose an item to use for you.
[2496] = "Osserva gli incantesimi d'uso degli oggetti di un set di oggetti riutilizzabile o di un elenco personalizzato. È un attivatore di annuncio; non sceglie per te un oggetto da usare.",
-- 6e216ab8 English: Search by spell name, select a result, or drag a spell from your spellbook or
--     action bar into the field. The icon and name identify the selected spell. Spell and pet spell
--     choices keep their respective catalog scope.
[2497] = "Cerca per nome dell'incantesimo, seleziona un risultato o trascina nel campo un incantesimo dal libro degli incantesimi o dalla barra delle azioni. L'icona e il nome identificano l'incantesimo selezionato. Le scelte di incantesimi e di incantesimi del famiglio mantengono il rispettivo catalogo.",
-- 691e05e6 English: Unchecked (the default), any known rank of the spell matches. Checked limits
--     matching to the rank you chose. This checkbox is shown only for Spell and Pet Spell, and only
--     on clients with spell ranks.
[2498] = "Se deselezionata (predefinito), corrisponde qualsiasi grado conosciuto dell'incantesimo. Se selezionata, limita la corrispondenza al grado scelto. Questa casella compare solo per Incantesimo e Incantesimo del famiglio, e solo nei client con gradi degli incantesimi.",
-- c75f5c21 English: Choose a reusable set, or Custom to edit this announcement's own list. For a
--     custom list, search for or drag items into the fields; Add item appends one and a red trash
--     can removes an entry. Any matching item-use spell in the list can trigger the announcement;
--     list order does not limit announcements to the first carried item. Changes to a shared set
--     belong on the Item Sets page.
[2499] = "Scegli un set riutilizzabile, o Personalizzato per modificare l'elenco proprio di questo annuncio. In un elenco personalizzato, cerca o trascina gli oggetti nei campi; Aggiungi oggetto ne aggiunge uno in fondo e il cestino rosso rimuove una voce. Qualsiasi incantesimo d'uso corrispondente di un oggetto dell'elenco può attivare l'annuncio; l'ordine dell'elenco non limita gli annunci al primo oggetto trasportato. Le modifiche a un set condiviso vanno fatte nella pagina Set di oggetti.",
-- 09fd4592 English: For automatic action types, choose which observed cast event triggers this
--     entry. A start, stop, interruption, failure or delay is different from a successful cast.
--     Client support determines which events and observations are available. Via Script/Macro has
--     no cast event.
[2500] = "Per i tipi di azione automatici, scegli quale evento di lancio osservato attiva questa voce. Un inizio, un arresto, un'interruzione, un fallimento o un ritardo sono diversi da un lancio riuscito. Il supporto del client determina quali eventi e osservazioni sono disponibili. Tramite script/macro non ha eventi di lancio.",
-- d9dcc847 English: The cast or channel started. This event does not mean it will finish
--     successfully.
[2501] = "Il lancio o l'incanalamento è iniziato. Questo evento non significa che si concluderà con successo.",
-- 2e1b963f English: The cast or channel stopped. A stop alone does not establish whether it
--     succeeded.
[2502] = "Il lancio o l'incanalamento si è fermato. Un arresto da solo non stabilisce se è riuscito.",
-- 37c82b71 English: The client reported a successful spell cast or item-use spell. For a channel,
--     this can occur as channeling begins rather than after its final tick.
[2503] = "Il client ha segnalato il lancio riuscito di un incantesimo o di un incantesimo d'uso di un oggetto. Per un incanalamento può avvenire all'inizio dell'incanalamento anziché dopo l'ultimo impulso.",
-- 94a29d0b English: The client reported that the cast was interrupted. This can include canceling a
--     cast yourself.
[2504] = "Il client ha segnalato che il lancio è stato interrotto. Può includere l'annullamento del lancio da parte tua.",
-- 7c5f19c7 English: The client reported that the cast failed. This is separate from the
--     successful-cast event.
[2505] = "Il client ha segnalato che il lancio è fallito. È distinto dall'evento di lancio riuscito.",
-- 9ae70605 English: The client reported a delay to the cast. This event is not a completion or
--     success notification.
[2506] = "Il client ha segnalato un ritardo nel lancio. Questo evento non è una notifica di completamento o di successo.",
-- 326e2b60 English: Choose a chat destination, local output, a named Emote or Audible. Emote
--     replaces Text with an emote selector and optional recipient. Audible replaces Text with
--     Sound. Text is retained when switching modes. Say, Yell, Whisper and named joined channels
--     are offered only for Via Script/Macro and remain subject to native restrictions.
[2507] = "Scegli una destinazione di chat, l'uscita locale, un'emote con nome o Sonoro. Emote sostituisce Testo con un selettore di emote e un destinatario facoltativo. Sonoro sostituisce Testo con Suono. Il testo viene conservato quando cambi modalità. Parla, Urla, Sussurra e i canali a cui sei unito sono offerti solo per Tramite script/macro e restano soggetti alle restrizioni native.",
-- 8352df04 English: Play the selected sound locally on the Master audio channel; no chat message is
--     sent. Choose an available sound before applying the announcement.
[2508] = "Riproduci localmente il suono selezionato sul canale audio principale; non viene inviato alcun messaggio in chat. Scegli un suono disponibile prima di applicare l'annuncio.",
-- b952981f English: Use raid chat while in a raid, party chat while in a party, or your local chat
--     frame while solo.
[2509] = "Usa la chat dell'incursione in un'incursione, la chat del gruppo in un gruppo o la tua finestra di chat locale quando sei da solo.",
-- 0048ad2e English: Use party chat when grouped, including your party within a raid. This
--     destination produces no solo chat message.
[2510] = "Usa la chat del gruppo quando sei in gruppo, incluso il tuo gruppo all'interno di un'incursione. Da solo questa destinazione non produce messaggi in chat.",
-- 4dd62130 English: Request group warning output. Depending on group membership and permissions, RM
--     may use raid chat, party chat, or local output instead.
[2511] = "Richiedi un avviso al gruppo. A seconda dell'appartenenza al gruppo e dei permessi, RM può usare invece la chat dell'incursione, la chat del gruppo o l'uscita locale.",
-- 5a88e05c English: A saved free-text emote keeps its original message. Select Emote to use a named
--     client emote instead.
[2512] = "Un'emote a testo libero salvata mantiene il suo messaggio originale. Seleziona Emote per usare invece un'emote del client con nome.",
-- 0bab8021 English: Choose a named emote from this client's slash commands, such as /cheer. This
--     does not send the Text field as a custom emote.
[2513] = "Scegli un'emote con nome tra i comandi slash di questo client, come /cheer. Non invia il campo Testo come emote personalizzata.",
-- a7a449d8 English: Choose the emote to perform when the configured cast event is observed. The
--     client may restrict an emote or require a hardware action; RM does not retry through another
--     output path.
[2514] = "Scegli l'emote da eseguire quando viene osservato l'evento di lancio configurato. Il client può limitare un'emote o richiedere un'azione fisica; RM non riprova tramite un altro canale di uscita.",
-- 7c9bf8c3 English: For cast entries, checked directs the emote to the recipient recorded for this
--     exact cast, including click casting. It does not use your current target or a previous cast's
--     recipient. For Via Script/Macro, checked uses the supplied macro unit. A missing recipient
--     skips targeted output. Unchecked performs the emote without a target.
[2515] = "Per le voci di lancio, se selezionata indirizza l'emote al destinatario registrato per quel preciso lancio, incluso il lancio con clic. Non usa il tuo bersaglio attuale né il destinatario di un lancio precedente. Per Tramite script/macro, se selezionata usa l'unità fornita dalla macro. Se il destinatario manca, l'uscita mirata viene saltata. Se non selezionata, esegue l'emote senza bersaglio.",
-- 24d388c2 English: Write to your own chat frame. Other players do not receive this message.
[2516] = "Scrivi nella tua finestra di chat. Gli altri giocatori non ricevono questo messaggio.",
-- 2224d247 English: Enter the message for a chat destination. The substitutions below insert action
--     and cast information when it is available. This text is not used for Audible or named Emote
--     output.
[2517] = "Inserisci il messaggio per una destinazione di chat. Le sostituzioni qui sotto inseriscono informazioni sull'azione e sul lancio quando sono disponibili. Questo testo non viene usato per l'uscita Sonoro o per le emote con nome.",
-- 5625f190 English: For cast entries, {{spell}} is a spell link, {{item}} an item link and
--     {{event}} the localized event name. {{target}} uses the recorded cast target, with the last
--     recorded target for that spell as a fallback; it does not automatically use your selected
--     target or your name. Unavailable cast substitutions can remain unchanged. Via Script/Macro
--     instead uses its supplied target and spell, {{event}} becomes Via Script/Macro, and required
--     missing inputs skip output; this API supplies no {{item}}.
[2518] = "Per le voci di lancio, {{spell}} è un link all'incantesimo, {{item}} un link all'oggetto e {{event}} il nome localizzato dell'evento. {{target}} usa il bersaglio registrato del lancio, con l'ultimo bersaglio registrato per quell'incantesimo come ripiego; non usa automaticamente il bersaglio selezionato né il tuo nome. Le sostituzioni di lancio non disponibili possono restare invariate. Tramite script/macro usa invece il bersaglio e l'incantesimo forniti, {{event}} diventa Tramite script/macro e, se mancano dati obbligatori, l'uscita viene saltata; questa API non fornisce {{item}}.",
-- a7af0c5c English: Choose a sound supplied by the shared-media catalog, then click Play to preview
--     it. Preview is local and does not save the draft. An unavailable sound cannot be previewed;
--     Audible announcements require a nonempty sound selection.
[2519] = "Scegli un suono fornito dal catalogo dei media condivisi, poi clicca su Riproduci per ascoltarne un'anteprima. L'anteprima è locale e non salva la bozza. Un suono non disponibile non può essere riprodotto in anteprima; gli annunci Sonoro richiedono la scelta di un suono.",
-- 58fc69dd English: The pill turns this entry on or off while keeping its fields. Disabled entries
--     do not announce matching casts or macro invocations. Apply saves the changed state.
[2520] = "L'interruttore attiva o disattiva questa voce mantenendone i campi. Le voci disattivate non annunciano i lanci corrispondenti né le invocazioni da macro. Applica salva lo stato modificato.",
-- 2ca49225 English: Edits stay in a draft until Apply. Complete the action or Via Script/Macro
--     identifier and other required fields before saving. Discard abandons changes to saved
--     announcements; Cancel closes a new creation draft. Leaving pending changes offers Apply,
--     Discard or Cancel navigation.
[2521] = "Le modifiche restano in una bozza fino ad Applica. Completa l'azione o l'identificativo Tramite script/macro e gli altri campi obbligatori prima di salvare. Scarta abbandona le modifiche agli annunci salvati; Annulla chiude una bozza di nuova creazione. Se esci con modifiche in sospeso, ti vengono proposti Applica, Scarta o Annulla.",
-- af92b7de English: Use the sidebar buttons to create, duplicate, transfer or compare
--     announcements. Apply saves the imported draft; Compare does not merge entries. Via
--     Script/Macro Duplicate assigns a distinct identifier and every copied output gets a fresh
--     identity. Series exports use version 2; version 1 remains available for legacy single-output
--     entries. Imports and Apply reject ambiguous identifiers. The red trash permanently deletes
--     the selected saved entry after confirmation. Resolve pending edits first; deletion does not
--     carry into the next selected draft.
[2522] = "Usa i pulsanti della barra laterale per creare, duplicare, trasferire o confrontare gli annunci. Applica salva la bozza importata; Confronta non unisce le voci. Duplica di Tramite script/macro assegna un identificativo distinto e ogni uscita copiata riceve una nuova identità. Le esportazioni di serie usano la versione 2; la versione 1 resta disponibile per le vecchie voci a uscita singola. Le importazioni e Applica rifiutano gli identificativi ambigui. Il cestino rosso elimina definitivamente la voce salvata selezionata dopo la conferma. Risolvi prima le modifiche in sospeso; l'eliminazione non si trasferisce alla bozza selezionata successiva.",
-- 2aefc10f English: An item set is an ordered list of alternatives, such as different mana potions.
--     Runtime selection checks the list from the top for a carried or, where requested, equipped
--     item. Priority comes from the order you choose, not the item level. Selecting an item does
--     not by itself prove that it is usable, off cooldown, or in range; action readiness is checked
--     separately.
[2523] = "Un set di oggetti è un elenco ordinato di alternative, come diverse pozioni di mana. Durante il gioco la selezione scorre l'elenco dall'alto cercando un oggetto trasportato o, dove richiesto, equipaggiato. La priorità deriva dall'ordine che scegli, non dal livello dell'oggetto. Selezionare un oggetto non dimostra di per sé che sia utilizzabile, senza tempo di recupero o a portata; la disponibilità dell'azione viene controllata a parte.",
-- f684e8a2 English: Name the selected set so it can be found in the sidebar and referenced by
--     rotations or conditions. New opens a name form; its first Apply saves an empty named set. Add
--     items afterward and Apply again to save them. Discarding later item edits keeps that already
--     saved set. Renaming a set does not change its identity in saved references.
[2524] = "Dai un nome al set selezionato, così da trovarlo nella barra laterale e richiamarlo da rotazioni o condizioni. Nuovo apre un modulo per il nome; il primo Applica salva un set vuoto con nome. Aggiungi poi gli oggetti e premi di nuovo Applica per salvarli. Scartare le modifiche successive agli oggetti conserva il set già salvato. Rinominare un set non cambia la sua identità nei riferimenti salvati.",
-- 21312192 English: Checked stores this set in the shared global collection, available to other
--     profiles and characters using this addon database. Unchecked stores it in the current
--     profile, which can itself be shared by characters. This is a staged move; Apply saves it. A
--     profile set takes precedence if a global set has the same saved identity.
[2525] = "Se selezionata, memorizza questo set nella raccolta globale condivisa, disponibile agli altri profili e ai personaggi che usano questo database dell'addon. Se non selezionata, lo memorizza nel profilo attuale, che a sua volta può essere condiviso tra personaggi. È uno spostamento preparato; Applica lo salva. Un set del profilo ha la precedenza se un set globale ha la stessa identità salvata.",
-- 0ba4e811 English: The list of item cards is the priority order. Put preferred items first. RM can
--     leave a selection unavailable when required inventory or identity observations are missing;
--     it does not treat unknown data as proof that a lower-priority item should be used. The
--     sidebar icon represents the first defined item and need not be the currently carried or
--     highlighted one.
[2526] = "L'elenco delle schede degli oggetti è l'ordine di priorità. Metti per primi gli oggetti preferiti. RM può lasciare una selezione non disponibile quando mancano le osservazioni necessarie sull'inventario o sull'identità; non considera i dati sconosciuti una prova che vada usato un oggetto a priorità inferiore. L'icona nella barra laterale rappresenta il primo oggetto definito e non è necessariamente quello attualmente trasportato o evidenziato.",
-- a5bf7ef1 English: Search by item name and choose a result, or drag an item from your bags or
--     action bar into its field. The icon identifies the item; metadata can take time to load. Edit
--     a row to replace that entry. Use its red trash can to remove it rather than clearing a
--     required item field.
[2527] = "Cerca per nome dell'oggetto e scegli un risultato, oppure trascina un oggetto dalle borse o dalla barra delle azioni nel suo campo. L'icona identifica l'oggetto; il caricamento dei metadati può richiedere tempo. Modifica una riga per sostituire quella voce. Usa il suo cestino rosso per rimuoverla invece di svuotare un campo oggetto obbligatorio.",
-- 67b1eae9 English: Choose or drag an item into the empty item field above the list, then click Add
--     item to append it to the priority list, or drag Add item into a gap between cards to insert
--     it there. Entering an item in this field alone does not add a row.
[2528] = "Scegli o trascina un oggetto nel campo vuoto sopra l'elenco, poi clicca su Aggiungi oggetto per aggiungerlo in fondo all'elenco di priorità, oppure trascina Aggiungi oggetto in uno spazio tra le schede per inserirlo lì. Inserire un oggetto in questo campo non aggiunge da solo una riga.",
-- 50b0f89c English: Move Up / Move Down
[2529] = "Sposta su / Sposta giù",
-- 69b751c9 English: Use the arrows on the left, or drag an item row into a highlighted insertion
--     gap. Ctrl-drag moves that row and all following entries together. The floating preview
--     identifies what you are moving. Moves past the beginning or end are unavailable. Reordering
--     changes priority and stays in the draft until Apply.
[2530] = "Usa le frecce a sinistra o trascina la riga di un oggetto in uno spazio di inserimento evidenziato. Ctrl-trascinamento sposta insieme quella riga e tutte le voci successive. L'anteprima mobile indica cosa stai spostando. Gli spostamenti oltre l'inizio o la fine non sono disponibili. Riordinare cambia la priorità e resta nella bozza fino ad Applica.",
-- 2b906316 English: Bind / Unbind
-- Context: Help topic title in the item set help for the buttons that connect an item set to a
--     macro/action button or remove the link.
[2531] = "Associa / Dissocia",
-- 81abb5f4 English: Outside combat, apply pending item-set edits before binding. Drag the set (its
--     row in the list, or the Bind pill) onto any action bar slot; an occupied slot swaps, leaving
--     its previous action on the cursor. Or click Bind and then click an empty slot. Both pick up
--     the first available item of the set. RM records the slot and updates it as item availability
--     changes. The pill shows bound slot numbers; click it to unbind and remove still-matching bar
--     items. Replaced bar actions are preserved. Binding changes are immediate action-bar
--     operations, independent of the draft and its history.
[2532] = "Fuori combattimento, applica le modifiche in sospeso al set di oggetti prima di associarlo. Trascina il set (la sua riga nell'elenco o il pulsante Associa) su un qualsiasi slot della barra delle azioni; uno slot occupato viene scambiato, lasciando l'azione precedente sul cursore. Oppure clicca su Associa e poi su uno slot vuoto. In entrambi i casi viene preso il primo oggetto disponibile del set. RM registra lo slot e lo aggiorna al variare della disponibilità degli oggetti. Il pulsante mostra i numeri degli slot associati; cliccalo per dissociare e rimuovere gli oggetti ancora corrispondenti dalla barra. Le azioni sostituite sulla barra vengono conservate. Le modifiche alle associazioni sono operazioni immediate sulla barra delle azioni, indipendenti dalla bozza e dalla sua cronologia.",
-- 7c8417f1 English: Restore the packaged item list for this set. Reset is available only for a set
--     with a packaged default. The restored list is staged until Apply; the name is kept.
[2533] = "Ripristina l'elenco di oggetti incluso nell'addon per questo set. Reimposta è disponibile solo per un set con un'impostazione predefinita inclusa. L'elenco ripristinato resta preparato fino ad Applica; il nome viene mantenuto.",
-- 70b9c94e English: The red trash can at the top right permanently removes the selected saved set
--     after confirmation. Resolve pending edits before the final warning. References in rotations
--     or conditions then need another set. Deletion reconciles still-matching bound bar actions and
--     keeps the set if unbinding fails; the next selection opens without an unsaved deletion
--     marker.
[2534] = "Il cestino rosso in alto a destra rimuove definitivamente il set salvato selezionato dopo la conferma. Risolvi le modifiche in sospeso prima dell'avviso finale. I riferimenti in rotazioni o condizioni avranno poi bisogno di un altro set. L'eliminazione riconcilia le azioni associate ancora corrispondenti sulla barra e conserva il set se la dissociazione non riesce; la selezione successiva si apre senza un indicatore di eliminazione non salvata.",
-- 49c1588e English: Undo / Redo
-- Context: Help topic title in the item set help for the undo and redo buttons.
[2535] = "Annulla / Ripeti",
-- cd68dbfd English: Undo and Redo travel through recent item-set draft edits, including
--     replacements, additions, ordering and row removals. They are unavailable when that direction
--     has no history. Apply, Discard or leaving the page clears this bounded history. They do not
--     reverse confirmed entity deletion or explicit action-bar binding operations.
[2536] = "Annulla e Ripeti scorrono le modifiche recenti alla bozza del set di oggetti, comprese sostituzioni, aggiunte, riordini e rimozioni di righe. Non sono disponibili quando in quella direzione non c'è cronologia. Applica, Scarta o l'uscita dalla pagina cancellano questa cronologia limitata. Non annullano l'eliminazione confermata di un elemento né le operazioni esplicite di associazione alla barra delle azioni.",
-- 68ab50bb English: Ordinary item-set edits stay in a draft until Apply. Discard restores the saved
--     item sets. Cancel closes a new creation draft. Leaving with pending changes offers Apply,
--     Discard or Cancel navigation. Invalid fields must be corrected before Apply; Discard can
--     abandon them.
[2537] = "Le normali modifiche al set di oggetti restano in una bozza fino ad Applica. Scarta ripristina i set di oggetti salvati. Annulla chiude una bozza di nuova creazione. Se esci con modifiche in sospeso, ti vengono proposti Applica, Scarta o Annulla. I campi non validi vanno corretti prima di Applica; Scarta può abbandonarli.",
-- b81b94df English: Use the buttons below the sidebar to create, duplicate, transfer, or compare
--     sets. Duplicate makes an independent profile copy. Import shows the source name and can
--     create a renamed copy or replace the selected list; Apply saves the staged result. Compare
--     inspects differences without merging or modifying either set.
[2538] = "Usa i pulsanti sotto la barra laterale per creare, duplicare, trasferire o confrontare i set. Duplica crea una copia indipendente nel profilo. Importa mostra il nome di origine e può creare una copia rinominata o sostituire l'elenco selezionato; Applica salva il risultato preparato. Confronta esamina le differenze senza unire né modificare nessuno dei due set.",
-- 147db4bf English: Legacy macro buttons
-- Context: Help topic title in the item set help: older macro buttons made before the current
--     system.
[2539] = "Pulsanti macro legacy",
-- 77908784 English: Legacy clients may allow /click to invoke an RM item-set button separately from
--     action-bar binding. The name is RM_ followed by the set name with non-alphanumeric characters
--     removed, then an underscore and unit token. For a set named Bandages, an example is /click
--     [@mouseover,nodead,help] RM_Bandages_mouseover. Other unit suffixes include player, pet,
--     target, focus, pettarget, targettarget, focustarget, and mouseovertarget. These buttons
--     contain item-use macro lines and do not provide the same readiness or first-item guarantee as
--     the recommendation engine. Availability is subject to the client's secure-button and macro
--     restrictions; reference-only support does not promise executable macro buttons.
[2540] = "I client legacy possono consentire a /click di richiamare un pulsante di set di oggetti di RM separatamente dall'associazione alla barra delle azioni. Il nome è RM_ seguito dal nome del set privato dei caratteri non alfanumerici, poi un trattino basso e l'identificativo unità. Per un set chiamato Bandages, un esempio è /click [@mouseover,nodead,help] RM_Bandages_mouseover. Altri suffissi di unità sono player, pet, target, focus, pettarget, targettarget, focustarget e mouseovertarget. Questi pulsanti contengono righe di macro per l'uso di oggetti e non offrono le stesse garanzie di disponibilità o di primo oggetto del motore dei suggerimenti. La disponibilità è soggetta alle restrizioni del client sui pulsanti protetti e sulle macro; il supporto di sola consultazione non garantisce pulsanti macro eseguibili.",
-- 0378c27f English: Search for an item or drag it into the item field or icon. Choose the result to
--     retain its exact item identity. The icon and name may be unavailable until metadata loads.
--     Field clearing and save behavior belong to the editor that contains this list; use Delete
--     when you intend to remove an entry.
[2541] = "Cerca un oggetto o trascinalo nel campo dell'oggetto o sull'icona. Scegli il risultato per mantenere l'identità esatta dell'oggetto. L'icona e il nome possono non essere disponibili finché i metadati non vengono caricati. Lo svuotamento dei campi e il salvataggio dipendono dall'editor che contiene questo elenco; usa Elimina quando vuoi rimuovere una voce.",
-- 6a348c09 English: Move this entry to the first position in the item priority list, when that
--     control is offered.
[2542] = "Sposta questa voce in prima posizione nell'elenco di priorità degli oggetti, quando il controllo è disponibile.",
-- 3b1a1705 English: Move this entry one position earlier. A move before the first entry is
--     unavailable.
[2543] = "Sposta questa voce di una posizione più in alto. Non è possibile spostarla prima della prima voce.",
-- a147318d English: Move this entry one position later. A move past the final entry is unavailable.
[2544] = "Sposta questa voce di una posizione più in basso. Non è possibile spostarla oltre l'ultima voce.",
-- 4b77e29f English: Move this entry to the final position in the item priority list, when that
--     control is offered.
[2545] = "Sposta questa voce in ultima posizione nell'elenco di priorità degli oggetti, quando il controllo è disponibile.",
-- 0c112c0c English: Remove this entry from the list. In a draft editor this remains pending until
--     Apply, and Discard abandons the row edit. Undo is available where the containing editor
--     provides draft history. This differs from permanently deleting the entire set after
--     confirmation.
[2546] = "Rimuovi questa voce dall'elenco. In un editor con bozza la rimozione resta in sospeso fino ad Applica, e Scarta annulla la modifica della riga. Annulla è disponibile dove l'editor che la contiene fornisce una cronologia della bozza. È diverso dall'eliminazione definitiva dell'intero set dopo la conferma.",
-- df1955d5 English: Use All, Built In or Custom to choose the condition source, then filter by
--     Switch, Other or a named category. Search above these controls narrows the visible list
--     without changing assignments.
[2547] = "Usa Tutte, Integrate o Personalizzate per scegliere l'origine delle condizioni, poi filtra per Cambio, Altro o una categoria con nome. La ricerca sopra questi controlli restringe l'elenco visibile senza modificare le assegnazioni.",
-- 190e427d English: Open Manage categories below the list for category maintenance. Manage
--     conditions returns to individual condition settings.
[2548] = "Apri Gestisci categorie sotto l'elenco per gestire le categorie. Gestisci condizioni riporta alle impostazioni delle singole condizioni.",
-- a9dcdfe2 English: Below the condition list, Import/Export opens the selected custom definition
--     for transfer and code review; it is disabled for built-in conditions. In Manage categories,
--     transfer a category’s ordered condition identifiers. Named categories and Other are exclusive
--     destinations. Switch membership is independent.
[2549] = "Sotto l'elenco delle condizioni, Importa/Esporta apre la definizione personalizzata selezionata per il trasferimento e l'esame del codice; è disattivato per le condizioni integrate. In Gestisci categorie, trasferisci gli identificativi ordinati delle condizioni di una categoria. Le categorie con nome e Altro sono destinazioni esclusive. L'appartenenza a Cambio è indipendente.",
-- 936a161c English: Editor
-- Context: Help topic title in Integrations settings help for the Lua editor options.
[2550] = "Editor",
-- 0c601351 English: Optional addons
-- Context: Help topic title in Integrations help: the list of other addons Rotation Master can work
--     with.
[2551] = "Addon facoltativi",
-- 0413ac9a English: Undo and Redo edit the Lua body. Reset restores the saved body or new-function
--     template and can be undone. Check syntax executes no custom Lua. Apply saves the body and
--     metadata together; Discard abandons the draft. Leaving with changes offers Apply, Discard or
--     Cancel.
[2552] = "Annulla e Ripeti modificano il corpo Lua. Reimposta ripristina il corpo salvato o il modello di nuova funzione e può essere annullato. Verifica sintassi non esegue alcun Lua personalizzato. Applica salva insieme corpo e metadati; Scarta abbandona la bozza. Se esci con modifiche, ti vengono proposti Applica, Scarta o Annulla.",
-- 5e86a29a English: Include custom function dependencies exports their source with the selected
--     definition. Without it, the bundle records required helper identities and versions. Review
--     source shows every imported Lua body. Resolve each original name and destination with Reuse,
--     Replace or a new identifier. Apply import saves the complete reviewed bundle and can register
--     imported Lua. Only apply code you trust.
[2553] = "Includi le dipendenze delle funzioni personalizzate esporta il loro codice sorgente insieme alla definizione selezionata. Senza questa opzione, il pacchetto registra identità e versioni delle funzioni di supporto richieste. Esamina sorgente mostra ogni corpo Lua importato. Risolvi ogni nome originale e destinazione con Riusa, Sostituisci o un nuovo identificativo. Applica importazione salva l'intero pacchetto esaminato e può registrare il Lua importato. Applica solo codice di cui ti fidi.",
-- b696d1d1 English: Arguments and returns
-- Context: Section title in the Functions help: how the Arguments and Returns lists work.
[2554] = "Argomenti e valori restituiti",
-- 2be54423 English: Choose an existing namespace from the suggestions or type a new dotted
--     namespace. Built In namespaces follow source files; custom namespaces are implied by saved
--     functions and need no separate maintenance.
[2555] = "Scegli uno spazio dei nomi esistente dai suggerimenti o scrivine uno nuovo con i punti. Gli spazi dei nomi integrati seguono i file sorgente; quelli personalizzati derivano dalle funzioni salvate e non richiedono una gestione separata.",
-- f6a949d3 English: Function names use letters, numbers and underscores, beginning with a letter or
--     underscore. The code signature shows the qualified namespace.name used by callers.
[2556] = "I nomi delle funzioni usano lettere, numeri e trattini bassi, e iniziano con una lettera o un trattino basso. La firma del codice mostra il nome qualificato namespace.name usato dai chiamanti.",
-- 330af7d6 English: Search helpers by name or description, then filter Built In / Custom and
--     namespace. Packaged helpers use the same read-only pane. Duplicate creates an editable custom
--     copy.
[2557] = "Cerca le funzioni di supporto per nome o descrizione, poi filtra per Integrate / Personalizzate e per spazio dei nomi. Le funzioni di supporto incluse usano lo stesso riquadro in sola lettura. Duplica crea una copia personalizzata modificabile.",
-- e67ec7ba English: Click an Arguments or Returns heading to collapse or expand it. + Argument and
--     + Return append when clicked, or insert at a highlighted gap when dragged. Drag a row or use
--     Up / Down to reorder; Ctrl-drag carries following rows. The trash can removes a row. Type and
--     Nullable document accepted values; Description explains each input or result. Lua can return
--     several ordered results. Return rows describe those results; moving them does not rewrite
--     return statements. Reordering a saved function warns because positional callers may need
--     changes; RM does not rewrite call sites.
[2558] = "Clicca sull'intestazione Argomenti o Valori restituiti per comprimerla o espanderla. + Argomento e + Valore restituito aggiungono in fondo se cliccati, o inseriscono in uno spazio evidenziato se trascinati. Trascina una riga o usa Su / Giù per riordinare; Ctrl-trascinamento porta con sé le righe successive. Il cestino rimuove una riga. Tipo e Ammette nil documentano i valori accettati; Descrizione spiega ogni input o risultato. Lua può restituire più risultati ordinati. Le righe dei valori restituiti descrivono quei risultati; spostarle non riscrive le istruzioni return. Riordinare una funzione salvata mostra un avviso perché i chiamanti posizionali possono richiedere modifiche; RM non riscrive i punti di chiamata.",
-- 183f4958 English: Enable Rotation Master recommendations, automatic rotation switching and bound
--     item-set updates. Disabling clears active advice and highlights and hides the preview. Apply
--     saves the change.
[2559] = "Attiva i consigli di Rotation Master, il cambio automatico di rotazione e l'aggiornamento dei set di oggetti associati. La disattivazione cancella i consigli e le evidenziazioni attivi e nasconde l'anteprima. Applica salva la modifica.",
-- c25b80af English: Set how often Rotation Master reevaluates the active rotation and independent
--     cooldowns, in seconds. A shorter interval updates advice more often and uses more processing
--     time. It does not cast spells, queue actions, or predict future combat.
[2560] = "Imposta ogni quanti secondi Rotation Master rivaluta la rotazione attiva e i tempi di recupero indipendenti. Un intervallo più breve aggiorna i consigli più spesso e richiede più tempo di elaborazione. Non lancia incantesimi, non accoda azioni e non prevede il combattimento futuro.",
-- 693c25ac English: Out of combat with no target and no focus, Rotation Master skips a polling tick
--     unless something it watches has changed: auras, cooldowns, health or power of you, your pet
--     or party, movement, casting, equipment, bags, form, pets or group. It still re-checks at
--     least this often, for time-based conditions (aura or cooldown remaining), distance, and
--     custom code. In combat, with any target or focus, or while configuration is open, every
--     polling tick is evaluated. Zero evaluates every polling tick.
[2561] = "Fuori combattimento, senza bersaglio né focus, Rotation Master salta un ciclo di polling a meno che non sia cambiato qualcosa che osserva: aure, tempi di recupero, salute o risorsa tua, del tuo famiglio o del gruppo, movimento, lancio, equipaggiamento, borse, forma, famigli o gruppo. Ricontrolla comunque almeno con questa frequenza, per le condizioni basate sul tempo (durata residua di aure o tempi di recupero), la distanza e il codice personalizzato. In combattimento, con un bersaglio o un focus, o mentre la configurazione è aperta, viene valutato ogni ciclo di polling. Zero valuta ogni ciclo di polling.",
-- 658535de English: With automatic switching, Rotation Master checks this often, in and out of
--     combat, whether a different rotation's switch conditions now match, so conditions that change
--     on their own (nearby enemy count, threat, movement, health) take effect. Target, focus and
--     pet changes are checked straight away. Zero turns automatic switching off. Choosing a
--     rotation manually still overrides automatic switching until you choose Auto again.
[2562] = "Con il cambio automatico, Rotation Master controlla con questa frequenza, in combattimento e fuori, se ora sono soddisfatte le condizioni di cambio di un'altra rotazione, così hanno effetto anche le condizioni che cambiano da sole (numero di nemici vicini, minaccia, movimento, salute). I cambi di bersaglio, focus e famiglio vengono controllati subito. Zero disattiva il cambio automatico. Scegliere manualmente una rotazione ha comunque la precedenza sul cambio automatico finché non scegli di nuovo Auto.",
-- 93a9cab7 English: Hide the main rotation recommendation on action bars. Independent cooldown
--     highlights remain available. Enable Preview Spells if you want to see the main advice in a
--     separate window; with both displays off, the main recommendation has no visible icon.
[2563] = "Nascondi il consiglio principale della rotazione sulle barre delle azioni. Le evidenziazioni dei tempi di recupero indipendenti restano disponibili. Attiva Anteprima incantesimi se vuoi vedere il consiglio principale in una finestra separata; con entrambe le visualizzazioni disattivate, il consiglio principale non ha alcuna icona visibile.",
-- 186fa30f English: How often, in seconds, the rotation editor checks each card's condition for the
--     colored bar on the left of its condition field: green when it currently matches for you, red
--     when it does not, gray when it cannot be read at the moment (hover the condition for why and
--     when it was checked). Conditions are checked only while the editor is open; zero turns the
--     bars off. This is separate from the recommendation polling interval.
[2564] = "Ogni quanti secondi l'editor delle rotazioni controlla la condizione di ogni scheda per la barra colorata a sinistra del suo campo condizione: verde quando in questo momento è soddisfatta per te, rossa quando non lo è, grigia quando al momento non può essere letta (passa il puntatore sulla condizione per vedere perché e quando è stata controllata). Le condizioni vengono controllate solo mentre l'editor è aperto; zero disattiva le barre. È separato dall'intervallo di polling dei consigli.",
-- 8fc06fca English: Show the Rotation Master minimap icon. Left-click toggles the configuration
--     window. Right-click opens the quick menu for enabling recommendations and choosing a rotation
--     or automatic switching.
[2565] = "Mostra l'icona di Rotation Master sulla minimappa. Il clic sinistro apre o chiude la finestra di configurazione. Il clic destro apre il menu rapido per attivare i consigli e scegliere una rotazione o il cambio automatico.",
-- a64c178e English: Choose how many seconds of previous spell casts to retain for history-based
--     conditions. Older casts are removed as recommendations update. A longer history retains more
--     records.
[2566] = "Scegli quanti secondi di lanci precedenti conservare per le condizioni basate sulla cronologia. I lanci più vecchi vengono rimossi man mano che i consigli si aggiornano. Una cronologia più lunga conserva più registrazioni.",
-- 6572d0ab English: Choose how many seconds of combat events to retain for conditions such as
--     recent hits, parries and blocks. Older events are removed as recommendations update.
--     Availability depends on the client combat-data policy.
[2567] = "Scegli quanti secondi di eventi di combattimento conservare per condizioni come colpi, parate e blocchi recenti. Gli eventi più vecchi vengono rimossi man mano che i consigli si aggiornano. La disponibilità dipende dalla politica del client sui dati di combattimento.",
-- 6c970b96 English: Choose how many seconds of observed damage and healing to retain for burn-rate
--     and time-to-die estimates. Recent observations receive more weight. A longer window uses more
--     records and smooths short changes; it cannot supply events the client does not expose.
[2568] = "Scegli quanti secondi di danni e cure osservati conservare per le stime del ritmo di consumo e del tempo alla morte. Le osservazioni recenti hanno più peso. Una finestra più lunga usa più registrazioni e attenua le variazioni brevi; non può fornire eventi che il client non espone.",
-- 1826b95e English: Choose a whole number of upcoming recommendations, from zero (hidden) to five.
--     This is the only switch for the preview window: it is shown whenever this is above zero and
--     hidden at zero, and the window has no close button. The preview shows current priority
--     results, not a simulation of future cooldowns or combat. Icons start at 64 pixels; resizing
--     scales all icons while preserving their square shape and the window ratio.
[2569] = "Scegli un numero intero di consigli successivi, da zero (nascosti) a cinque. È l'unico interruttore della finestra di anteprima: viene mostrata finché il valore è superiore a zero e nascosta a zero, e la finestra non ha un pulsante di chiusura. L'anteprima mostra i risultati attuali delle priorità, non una simulazione di tempi di recupero o combattimenti futuri. Le icone partono da 64 pixel; il ridimensionamento scala tutte le icone mantenendone la forma quadrata e le proporzioni della finestra.",
-- 9a03212a English: Adjust the preview background opacity without fading its icons. At zero only
--     the icons remain, the hidden background does not intercept blank-space clicks and the resize
--     grip is unavailable; an unlocked preview can still be dragged by its icons. Restore opacity
--     in General to resize it.
[2570] = "Regola l'opacità dello sfondo dell'anteprima senza sbiadirne le icone. A zero restano solo le icone: lo sfondo nascosto non intercetta i clic negli spazi vuoti e la maniglia di ridimensionamento non è disponibile; un'anteprima sbloccata si può ancora trascinare dalle sue icone. Ripristina l'opacità in Generale per ridimensionarla.",
-- 7884cae2 English: Unlocked, drag the preview by any icon or its background to move it, and resize
--     it from the grip that appears at its lower-right corner on hover. Locked, it cannot be moved
--     or resized and its background lets clicks through. Right-click an icon (or the background
--     while unlocked) for a menu to lock, unlock or open these settings. Locking and unlocking take
--     effect immediately and are saved without Apply. Other pending General edits remain unchanged.
[2571] = "Da sbloccata, trascina l'anteprima da qualsiasi icona o dallo sfondo per spostarla e ridimensionala con la maniglia che compare nell'angolo in basso a destra al passaggio del cursore. Da bloccata non si può spostare né ridimensionare e il suo sfondo lascia passare i clic. Fai clic destro su un'icona (o sullo sfondo se è sbloccata) per un menu che blocca, sblocca o apre queste impostazioni. Il blocco e lo sblocco hanno effetto immediato e vengono salvati senza Applica. Le altre modifiche in sospeso in Generale restano invariate.",
-- 110dd6c2 English: Arrange preview icons horizontally (default) or vertically. Lock, Direction and
--     Reset share one row below the opacity slider. Changing direction keeps icons square and
--     adjusts the window ratio.
[2572] = "Disponi le icone dell'anteprima in orizzontale (predefinito) o in verticale. Blocca, Direzione e Reimposta condividono una riga sotto il cursore dell'opacità. Cambiare direzione mantiene le icone quadrate e adatta le proporzioni della finestra.",
-- 46417b1b English: This icon previews the selected profile effect, color, size, anchor and
--     offsets. Previewing an effect does not save the draft or change the spell being recommended.
[2573] = "Questa icona mostra in anteprima l'effetto, il colore, la dimensione, l'ancoraggio e gli scostamenti selezionati nel profilo. L'anteprima di un effetto non salva la bozza né cambia l'incantesimo consigliato.",
-- 0e030acc English: Choose the highlight used for the main recommendation and as the default for
--     independent cooldowns. Manage available effects on the Effects page. A cooldown can override
--     these profile settings in its action details.
[2574] = "Scegli l'evidenziazione usata per il consiglio principale e come predefinita per i tempi di recupero indipendenti. Gestisci gli effetti disponibili nella pagina Effetti. Un tempo di recupero può sovrascrivere queste impostazioni del profilo nei dettagli della sua azione.",
-- cf6729fa English: Scale the highlight relative to its action icon. A value of 1 uses the icon
--     size. Drag the slider or type its numeric value; the preview updates as you edit.
[2575] = "Scala l'evidenziazione rispetto all'icona dell'azione. Un valore di 1 usa la dimensione dell'icona. Trascina il cursore o digita il valore numerico; l'anteprima si aggiorna mentre modifichi.",
-- 15842be8 English: Choose the highlight color and opacity. Click the color swatch to open the
--     picker, or enter R, G, B and A values between 0 and 1. Alpha controls opacity; individual
--     cooldowns may override this profile color.
[2576] = "Scegli il colore e l'opacità dell'evidenziazione. Clicca sul campione di colore per aprire il selettore, oppure inserisci valori R, G, B e A compresi tra 0 e 1. Alfa controlla l'opacità; i singoli tempi di recupero possono sovrascrivere questo colore del profilo.",
-- 27eafca9 English: Choose the point on the action icon where a texture highlight is anchored by
--     its center. Changing Anchor resets the offsets. The preview shows the resulting placement;
--     non-texture glows may use offsets without a texture anchor.
[2577] = "Scegli il punto dell'icona dell'azione a cui viene ancorata, tramite il suo centro, un'evidenziazione a texture. Cambiare Ancoraggio azzera gli scostamenti. L'anteprima mostra la posizione risultante; i bagliori non basati su texture possono usare gli scostamenti senza un ancoraggio della texture.",
-- 24139be0 English: Vertical offset in pixels. Use Up or Down on the position control, or edit V
--     directly. Hold Shift while using an arrow for ten pixels. Center resets both offsets and the
--     anchor to Center.
[2578] = "Scostamento verticale in pixel. Usa Su o Giù sul controllo della posizione, oppure modifica direttamente V. Tieni premuto Maiusc mentre usi una freccia per spostarti di dieci pixel. Centro azzera entrambi gli scostamenti e riporta l'ancoraggio su Centro.",
-- 64fcca62 English: Horizontal offset in pixels. Use Left or Right on the position control, or edit
--     H directly. Hold Shift while using an arrow for ten pixels. Non-texture glows interpret
--     offsets according to their effect shape.
[2579] = "Scostamento orizzontale in pixel. Usa Sinistra o Destra sul controllo della posizione, oppure modifica direttamente H. Tieni premuto Maiusc mentre usi una freccia per spostarti di dieci pixel. I bagliori non basati su texture interpretano gli scostamenti in base alla forma del loro effetto.",
-- 199fbfc5 English: Choose the display name for your primary specialization. This changes its label
--     in Rotation Master, not your character talents or specialization.
[2580] = "Scegli il nome visualizzato per la tua specializzazione primaria. Cambia la sua etichetta in Rotation Master, non i talenti o la specializzazione del personaggio.",
-- 1647f2ad English: Choose the display name for your secondary specialization. This changes its
--     label in Rotation Master, not your character talents or specialization.
[2581] = "Scegli il nome visualizzato per la tua specializzazione secondaria. Cambia la sua etichetta in Rotation Master, non i talenti o la specializzazione del personaggio.",
-- b49fc138 English: Choose the amount of Rotation Master chat output. Silent suppresses routine
--     output. Default reports normal changes such as rotation switching. Debug adds runtime
--     statistics and trigger information. Verbose includes detailed condition and highlight
--     activity and can produce substantial output.
[2582] = "Scegli la quantità di messaggi di Rotation Master in chat. Silenzioso sopprime i messaggi di routine. Predefinito segnala le modifiche normali, come il cambio di rotazione. Debug aggiunge statistiche di esecuzione e informazioni sugli attivatori. Dettagliato include l'attività dettagliata di condizioni ed evidenziazioni e può produrre molti messaggi.",
-- d0d316d9 English: Include component timings in the periodic Debug or Verbose profiling report.
--     Reports show measured runs, total, minimum, average and maximum in milliseconds. Timings
--     include child work; nested scopes overlap and must not be added together. The overall scope
--     starts after rotation preparation. This is elapsed timing, not the native addon CPU report.
[2583] = "Includi i tempi dei singoli componenti nel report periodico di profilazione Debug o Dettagliato. I report mostrano esecuzioni misurate, totale, minimo, media e massimo in millisecondi. I tempi includono il lavoro dei sottocomponenti; gli ambiti annidati si sovrappongono e non vanno sommati. L'ambito complessivo inizia dopo la preparazione della rotazione. Si tratta di tempo trascorso, non del report nativo della CPU degli addon.",
-- fd1963a1 English: Effects define how action-bar icons are highlighted. They are shared across
--     characters. General settings select the main recommendation effect and cooldown default;
--     individual cooldowns can choose another effect. Select an effect in the sidebar to inspect or
--     edit it.
[2584] = "Gli effetti definiscono come vengono evidenziate le icone della barra delle azioni. Sono condivisi tra i personaggi. Le impostazioni di Generale selezionano l'effetto del consiglio principale e quello predefinito dei tempi di recupero; i singoli tempi di recupero possono sceglierne un altro. Seleziona un effetto nella barra laterale per esaminarlo o modificarlo.",
-- 40b0b9e0 English: Give the effect a name used by selectors in General and cooldown action
--     details. New drafts can change type and fields before being named, but Apply requires a
--     nonempty, unique name.
[2585] = "Dai all'effetto un nome, usato dai selettori in Generale e nei dettagli delle azioni dei tempi di recupero. Le nuove bozze possono cambiare tipo e campi prima di ricevere un nome, ma Applica richiede un nome non vuoto e univoco.",
-- 5a00db51 English: Choose the highlight implementation. Changing type stages the new fields and
--     resets its sequence because different sequence types store different values. Choosing the
--     current type preserves existing values. Apply saves the change; Discard restores the saved
--     effect.
[2586] = "Scegli l'implementazione dell'evidenziazione. Cambiare tipo prepara i nuovi campi e azzera la sequenza, perché tipi di sequenza diversi memorizzano valori diversi. Scegliere il tipo attuale conserva i valori esistenti. Applica salva la modifica; Scarta ripristina l'effetto salvato.",
-- c228a709 English: Texture: overlay a single image from game data or an installed addon. Its
--     color, magnification and position come from the profile or the individual cooldown.
[2587] = "Texture: sovrappone una singola immagine dai dati di gioco o da un addon installato. Colore, ingrandimento e posizione provengono dal profilo o dal singolo tempo di recupero.",
-- cd1a7948 English: Pixel: animate short lines around the action icon border. Lines, Frequency,
--     Length and Thickness control this library glow.
[2588] = "Pixel: anima brevi linee lungo il bordo dell'icona dell'azione. Linee, Frequenza, Lunghezza e Spessore controllano questo bagliore della libreria.",
-- 8f767bf7 English: Auto Cast: animate groups of glowing particles around the action icon.
--     Particles, Frequency and Scale control this library glow.
[2589] = "Lancio automatico: anima gruppi di particelle luminose intorno all'icona dell'azione. Particelle, Frequenza e Scala controllano questo bagliore della libreria.",
-- 0984e57a English: Glow: use the familiar Blizzard-style button glow. Frequency controls its
--     animation rate.
[2590] = "Bagliore: usa il classico bagliore dei pulsanti in stile Blizzard. Frequenza controlla la velocità dell'animazione.",
-- 4f13ce4d English: Dazzle: keep one texture and cycle through the sequence of colors. Each
--     sequence card contains one RGBA color.
[2591] = "Abbaglio: mantiene una sola texture e scorre la sequenza di colori. Ogni scheda della sequenza contiene un colore RGBA.",
-- 518c7a0b English: Animate: cycle through the sequence of texture images. Each card selects one
--     image and previews that selection.
[2592] = "Animazione: scorre la sequenza di immagini texture. Ogni scheda seleziona un'immagine e ne mostra l'anteprima.",
-- 7db1adc9 English: Pulse: keep one texture and cycle through the sequence of magnifications. Each
--     card selects one scale relative to the action icon.
[2593] = "Pulsazione: mantiene una sola texture e scorre la sequenza di ingrandimenti. Ogni scheda seleziona una scala relativa all'icona dell'azione.",
-- 04c25e44 English: Rotate: animate one texture through evenly spaced angles around a full circle.
--     Steps chooses the number of angles and Reverse changes their order.
[2594] = "Ruota: anima una texture attraverso angoli equidistanti lungo un giro completo. Passi sceglie il numero di angoli e Inverti ne cambia l'ordine.",
-- e239b9d1 English: Custom: cycle through cards containing a texture, angle, magnification and
--     color. Each card supplies its own settings instead of relying on one shared texture.
[2595] = "Personalizzato: scorre schede che contengono texture, angolo, ingrandimento e colore. Ogni scheda fornisce le proprie impostazioni invece di basarsi su un'unica texture condivisa.",
-- 1b35109f English: The image beside Name and Type previews the current draft with a white color
--     and standard size. Texture and sequence changes update the preview without saving. Actual
--     recommendations use their profile or cooldown color, size and offsets.
[2596] = "L'immagine accanto a Nome e Tipo mostra l'anteprima della bozza attuale con colore bianco e dimensione standard. Le modifiche a texture e sequenza aggiornano l'anteprima senza salvare. I consigli effettivi usano il colore, la dimensione e gli scostamenti del profilo o del tempo di recupero.",
-- 69030e6a English: For Texture, Dazzle, Pulse and Rotate, choose the image used throughout the
--     effect. The arrow beside an image field opens the bundled overlay catalog with previews.
--     Enter an available texture path or numeric file ID to use another image. Animate and Custom
--     choose images in their sequence cards using the same controls. Selections update the draft
--     and preview; Apply saves them.
[2597] = "Per Texture, Abbaglio, Pulsazione e Ruota, scegli l'immagine usata per tutto l'effetto. La freccia accanto a un campo immagine apre il catalogo di sovrapposizioni incluso, con anteprime. Inserisci il percorso di una texture disponibile o un ID file numerico per usare un'altra immagine. Animazione e Personalizzato scelgono le immagini nelle schede della sequenza con gli stessi controlli. Le selezioni aggiornano la bozza e l'anteprima; Applica le salva.",
-- 06895a3f English: Pixel effects: choose the number of animated lines around the button, from 1 to
--     20.
[2598] = "Effetti Pixel: scegli il numero di linee animate intorno al pulsante, da 1 a 20.",
-- 5a02f176 English: Pixel effects: signed cycles per second. A larger magnitude moves faster; a
--     negative value reverses direction. Zero uses the glow library default of one cycle every four
--     seconds.
[2599] = "Effetti Pixel: cicli al secondo, con segno. Un valore assoluto maggiore si muove più velocemente; un valore negativo inverte la direzione. Zero usa il valore predefinito della libreria del bagliore, un ciclo ogni quattro secondi.",
-- 912f8432 English: Pixel effects: choose line length in pixels. The glow library limits it to the
--     smaller button dimension.
[2600] = "Effetti Pixel: scegli la lunghezza delle linee in pixel. La libreria del bagliore la limita alla dimensione minore del pulsante.",
-- 888c1858 English: Pixel effects: choose line thickness in pixels, from 1 to 5.
[2601] = "Effetti Pixel: scegli lo spessore delle linee in pixel, da 1 a 5.",
-- f169cd48 English: Auto Cast effects: choose 1 to 4 particles in each of the glow library particle
--     groups.
[2602] = "Effetti Lancio automatico: scegli da 1 a 4 particelle in ciascun gruppo di particelle della libreria del bagliore.",
-- 439eb6b4 English: Auto Cast effects: signed cycles per second. A larger magnitude moves faster; a
--     negative value reverses direction. Zero uses the glow library default of one cycle every
--     eight seconds.
[2603] = "Effetti Lancio automatico: cicli al secondo, con segno. Un valore assoluto maggiore si muove più velocemente; un valore negativo inverte la direzione. Zero usa il valore predefinito della libreria del bagliore, un ciclo ogni otto secondi.",
-- ee4e74b2 English: Auto Cast effects: scale the particles relative to the glow library default. A
--     value of 1 uses their normal size.
[2604] = "Effetti Lancio automatico: scala le particelle rispetto al valore predefinito della libreria del bagliore. Un valore di 1 usa la loro dimensione normale.",
-- 7a5e1fd3 English: Glow effects: adjust the library animation rate. Larger positive values animate
--     faster. Zero uses the library default rather than stopping the glow.
[2605] = "Effetti Bagliore: regola la velocità di animazione della libreria. Valori positivi più alti animano più velocemente. Zero usa il valore predefinito della libreria invece di fermare il bagliore.",
-- a09487cf English: Dazzle effects: seconds between color cards. A smaller positive interval
--     changes colors more often; the sequence repeats after the last color.
[2606] = "Effetti Abbaglio: secondi tra una scheda colore e la successiva. Un intervallo positivo più breve cambia colore più spesso; la sequenza ricomincia dopo l'ultimo colore.",
-- 9e3ad582 English: Animate effects: seconds between texture cards. A smaller positive interval
--     changes images more often; the sequence repeats after the last image.
[2607] = "Effetti Animazione: secondi tra una scheda texture e la successiva. Un intervallo positivo più breve cambia immagine più spesso; la sequenza ricomincia dopo l'ultima immagine.",
-- 73861ddb English: Pulse effects: seconds between magnification cards. A smaller positive interval
--     changes size more often; the sequence repeats after the last size.
[2608] = "Effetti Pulsazione: secondi tra una scheda di ingrandimento e la successiva. Un intervallo positivo più breve cambia dimensione più spesso; la sequenza ricomincia dopo l'ultima dimensione.",
-- 6f691c60 English: Rotate effects: seconds between angle steps. A smaller positive interval
--     rotates faster. One full cycle uses this interval multiplied by Steps.
[2609] = "Effetti Ruota: secondi tra un passo angolare e il successivo. Un intervallo positivo più breve ruota più velocemente. Un ciclo completo dura questo intervallo moltiplicato per Passi.",
-- 78b58b96 English: Rotate effects: choose 2 to 36 evenly spaced angles for a full turn. More steps
--     at the same Frequency interval make a longer complete cycle.
[2610] = "Effetti Ruota: scegli da 2 a 36 angoli equidistanti per un giro completo. Più passi con lo stesso intervallo di Frequenza rendono più lungo il ciclo completo.",
-- 98768f9e English: Rotate effects: reverse the order of angle steps. Changing this checkbox does
--     not alter the texture or number of steps.
[2611] = "Effetti Ruota: inverti l'ordine dei passi angolari. Cambiare questa casella non modifica la texture né il numero di passi.",
-- 0eaebb24 English: Custom effects: seconds between sequence cards. A smaller positive interval
--     changes settings more often; the sequence repeats after the last card.
[2612] = "Effetti Personalizzato: secondi tra una scheda della sequenza e la successiva. Un intervallo positivo più breve cambia le impostazioni più spesso; la sequenza ricomincia dopo l'ultima scheda.",
-- a85d837a English: Sequence cards play in order and repeat. Add step, on the Sequence header row,
--     appends a card; drag Add step into a gap to insert one there. Drag a card into an insertion
--     gap to reorder it; hold Ctrl when starting to carry it and all following cards. Up and Down
--     move one card and are disabled at their respective ends. The red trash removes a card from
--     the draft. Canceling a drag restores its original position.
[2613] = "Le schede della sequenza vengono riprodotte in ordine e ripetute. Aggiungi passo, nella riga di intestazione Sequenza, aggiunge una scheda in fondo; trascina Aggiungi passo in uno spazio per inserirne una lì. Trascina una scheda in uno spazio di inserimento per riordinarla; tieni premuto Ctrl all'inizio del trascinamento per spostare anche tutte le schede successive. Su e Giù spostano una scheda di una posizione e sono disattivati alle rispettive estremità. Il cestino rosso rimuove una scheda dalla bozza. Annullare un trascinamento ripristina la posizione originale.",
-- d5a4691e English: Animate and Custom cards: choose a texture path or numeric file ID. The card
--     preview shows the selected image. Custom also keeps an independent angle, magnification and
--     color on that card.
[2614] = "Schede Animazione e Personalizzato: scegli il percorso di una texture o un ID file numerico. L'anteprima della scheda mostra l'immagine selezionata. Personalizzato mantiene inoltre angolo, ingrandimento e colore indipendenti per quella scheda.",
-- e9c4d7cb English: Custom cards: set the texture angle in degrees from 0 to 359. This is the angle
--     for this card, rather than a continuous rotation speed.
[2615] = "Schede Personalizzato: imposta l'angolo della texture in gradi, da 0 a 359. È l'angolo di questa scheda, non una velocità di rotazione continua.",
-- f9eb09ea English: Pulse and Custom cards: scale the texture relative to the action icon. A value
--     of 1 uses the icon size. Use the slider or edit its numeric value.
[2616] = "Schede Pulsazione e Personalizzato: scala la texture rispetto all'icona dell'azione. Un valore di 1 usa la dimensione dell'icona. Usa il cursore o modifica il valore numerico.",
-- a6ca83b6 English: Dazzle and Custom cards: choose an RGBA color. Click the swatch to open the
--     picker, or edit channels between 0 and 1. Alpha controls opacity.
[2617] = "Schede Abbaglio e Personalizzato: scegli un colore RGBA. Clicca sul campione per aprire il selettore, oppure modifica i canali con valori tra 0 e 1. Alfa controlla l'opacità.",
-- d838f5ee English: Edits and sequence changes remain in a draft. Apply saves; Discard restores the
--     saved effect. Cancel closes a new creation draft. View Changes compares saved and unsaved
--     values. New drafts require a unique name and valid fields before Apply. Leaving with edits
--     offers Apply, Discard or Cancel.
[2618] = "Le modifiche e le variazioni della sequenza restano in una bozza. Applica salva; Scarta ripristina l'effetto salvato. Annulla chiude una bozza di nuova creazione. Mostra modifiche confronta i valori salvati e non salvati. Le nuove bozze richiedono un nome univoco e campi validi prima di Applica. Uscire con modifiche in sospeso propone Applica, Scarta o Annulla.",
-- 781f5d06 English: The red trash at the upper right deletes the selected effect after a
--     permanent-deletion warning. Resolve pending edits first. Choose a replacement for any profile
--     or cooldown using that effect; deletion does not silently rewrite those references.
[2619] = "Il cestino rosso in alto a destra elimina l'effetto selezionato dopo un avviso di eliminazione definitiva. Risolvi prima le modifiche in sospeso. Scegli un sostituto per ogni profilo o tempo di recupero che usa quell'effetto; l'eliminazione non riscrive di nascosto quei riferimenti.",
-- a8f923ca English: New, Duplicate, Import/Export and Compare are below the sidebar. Duplicate
--     copies the selected effect into a draft. Transfers show the original name and let you create
--     a renamed copy or replace the selection when allowed. Compare inspects differences without
--     saving them.
[2620] = "Nuovo, Duplica, Importa/Esporta e Confronta si trovano sotto la barra laterale. Duplica copia l'effetto selezionato in una bozza. I trasferimenti mostrano il nome originale e ti permettono di creare una copia rinominata o, se consentito, di sostituire la selezione. Confronta esamina le differenze senza salvarle.",
-- fe52fcf9 English: Selecting a sidebar row only inspects that profile. Activate profile switches
--     the live profile immediately, including its rotations and settings. The active profile shows
--     Active profile instead. This operation does not wait for page Apply.
[2621] = "Selezionare una riga della barra laterale si limita a esaminare quel profilo. Attiva profilo cambia subito il profilo in uso, comprese rotazioni e impostazioni. Il profilo attivo mostra invece Profilo attivo. Questa operazione non attende Applica della pagina.",
-- 605ecea0 English: Choose a source to replace the active profile after confirmation. This copies
--     settings and rotations into the active profile, even when the sidebar is inspecting a
--     different profile. It does not switch to the source or rename the active profile. Cancel at
--     the confirmation preserves the current profile.
[2622] = "Scegli un'origine con cui sostituire il profilo attivo dopo la conferma. Copia impostazioni e rotazioni nel profilo attivo, anche quando la barra laterale sta esaminando un altro profilo. Non passa all'origine né rinomina il profilo attivo. Annulla nella conferma mantiene il profilo attuale.",
-- d403202f English: Reset current profile replaces the active profile with its defaults after
--     confirmation. Custom rotations and settings in it are replaced. The control is disabled while
--     inspecting another profile. Reset is immediate after confirmation; there is no later page
--     Apply to undo it.
[2623] = "Reimposta il profilo attuale sostituisce il profilo attivo con i suoi valori predefiniti dopo la conferma. Le rotazioni e le impostazioni personalizzate che contiene vengono sostituite. Il controllo è disattivato mentre esamini un altro profilo. Il ripristino è immediato dopo la conferma; non c'è un Applica successivo della pagina con cui annullarlo.",
-- 071e02f8 English: The red trash can permanently removes the selected inactive profile after
--     confirmation. The active profile and Default cannot be deleted here. Selecting another
--     profile does not delete or activate it.
[2624] = "Il cestino rosso rimuove definitivamente il profilo inattivo selezionato dopo la conferma. Il profilo attivo e Default non possono essere eliminati qui. Selezionare un altro profilo non lo elimina né lo attiva.",
-- e0223ba4 English: New and Duplicate open a named draft. Use a nonblank, unused name of at most 50
--     characters. Apply creates the profile; Cancel abandons creation. Creating a profile leaves
--     the previously active profile active, so use Activate profile when you want to switch to the
--     new copy.
[2625] = "Nuovo e Duplica aprono una bozza con nome. Usa un nome non vuoto, non ancora usato e lungo al massimo 50 caratteri. Applica crea il profilo; Annulla abbandona la creazione. Creare un profilo lascia attivo quello precedente, quindi usa Attiva profilo quando vuoi passare alla nuova copia.",
-- c85ff72a English: The buttons below the list create a new profile, duplicate the selected
--     profile, transfer profiles or compare saved settings. Search narrows the list without
--     activating a profile. Import/Export shows the original name and lets you replace the
--     selection or create a renamed copy. Importing a new profile opens a creation draft; Apply
--     saves it. Replacing a selected profile happens when you confirm the import, and replacing the
--     active profile updates its runtime settings. Compare does not apply changes.
[2626] = "I pulsanti sotto l'elenco creano un nuovo profilo, duplicano il profilo selezionato, trasferiscono profili o confrontano le impostazioni salvate. La ricerca restringe l'elenco senza attivare alcun profilo. Importa/Esporta mostra il nome originale e ti permette di sostituire la selezione o di creare una copia rinominata. Importare un nuovo profilo apre una bozza di creazione; Applica la salva. La sostituzione di un profilo selezionato avviene quando confermi l'importazione, e sostituire il profilo attivo ne aggiorna le impostazioni in uso. Confronta non applica modifiche.",
-- d58adae2 English: Status pills show Not loaded, Supported, Disabled, Enabled or Selected. Click
--     Enabled to Select or Disable. Disabling Selected chooses the sole enabled available editor,
--     offers a choice when several exist, or leaves none selected. Enabling an editor when none is
--     selected selects it automatically. Native is always available; its Syntax highlighting option
--     is independent of editor selection. With no enabled editor, emergency plain text remains
--     usable. Apply saves preferences for the next source-editor opening; Discard keeps saved
--     settings. An open editor keeps its current provider.
[2627] = "Le etichette di stato mostrano Non caricato, Supportato, Disattivato, Attivato o Selezionato. Clicca su Attivato per selezionarlo o disattivarlo. Disattivare l'editor Selezionato sceglie l'unico editor attivato disponibile, propone una scelta se ce ne sono diversi, oppure non ne lascia nessuno selezionato. Attivare un editor quando nessuno è selezionato lo seleziona automaticamente. Nativo è sempre disponibile; la sua opzione Evidenziazione della sintassi è indipendente dalla selezione dell'editor. Senza editor attivati resta utilizzabile il testo semplice di emergenza. Applica salva le preferenze per la prossima apertura dell'editor del codice sorgente; Scarta mantiene le impostazioni salvate. Un editor già aperto mantiene il fornitore attuale.",
-- 3bdeb012 English: Show line numbers controls the gutter in every condition and function code
--     editor. It defaults to enabled. Apply saves the preference and updates open code panes;
--     Discard keeps the saved setting. It does not change the Lua source or its line breaks.
[2628] = "Mostra numeri di riga controlla la colonna dei numeri in ogni editor di codice di condizioni e funzioni. È attivo per impostazione predefinita. Applica salva la preferenza e aggiorna i riquadri di codice aperti; Scarta mantiene l'impostazione salvata. Non modifica il codice sorgente Lua né i suoi a capo.",
-- e69d5940 English: Addon names open copyable official release and source links across available
--     providers. Edition filtering follows declared support for the matching addon identity;
--     unknown compatibility remains visible. An older release date alone does not prove
--     incompatibility. Listed game-edition support describes publisher release evidence, not
--     certification of the integration on your client. Some integrations have only historical or
--     unverified releases. Not loaded means unavailable to RM; Supported identifies an available
--     integration without an enable switch. Bundled libraries are excluded. Rotation Master does
--     not install or enable other addons.
[2629] = "I nomi degli addon aprono link copiabili alle versioni ufficiali e al codice sorgente presso i fornitori disponibili. Il filtro per edizione segue il supporto dichiarato per l'addon corrispondente; una compatibilità sconosciuta resta visibile. Una data di rilascio più vecchia, da sola, non dimostra l'incompatibilità. Il supporto alle edizioni del gioco indicato descrive quanto dichiarato dall'autore nelle versioni, non una certificazione dell'integrazione sul tuo client. Alcune integrazioni hanno solo versioni storiche o non verificate. Non caricato significa non disponibile per RM; Supportato indica un'integrazione disponibile senza interruttore di attivazione. Le librerie incluse sono escluse. Rotation Master non installa né attiva altri addon.",
-- 6c182d42 English: Apply / Discard
-- Context: Help topic title for the buttons that save or abandon edits in an item list dialog and
--     the window.
[2630] = "Applica / Scarta",
-- d04a65ba English: Edits stay in a draft until Apply. Discard abandons pending changes. Leaving
--     with changes offers Apply, Discard or Cancel; Cancel keeps the page and draft open. Effect
--     previews do not save changes. Action-bar binding operations are explicit and immediate.
[2631] = "Le modifiche restano in una bozza fino ad Applica. Scarta abbandona le modifiche in sospeso. Uscire con modifiche propone Applica, Scarta o Annulla; Annulla mantiene aperte la pagina e la bozza. Le anteprime degli effetti non salvano le modifiche. Le operazioni di associazione alla barra delle azioni sono esplicite e immediate.",
-- 2be8c485 English: Diagram / List changes only the rotation view; General settings choose the
--     default. Diagram has floating minus, percentage and plus controls at the bottom right. Scroll
--     to zoom from 25% to 200%; click the percentage or middle-click to reset to 100%. Drag empty
--     diagram space to pan. List uses normal scrollbars with touching cards and boxed branch arms,
--     False before True. Cooldowns use a separate scrolling grid. Dragging cards reorders them in
--     every view. Valid rotation bodies can contain up to 2,000 total steps; large workspaces reuse
--     nearby card controls as you navigate. Folded branches intentionally hide their children.
[2632] = "Diagramma / Elenco cambia solo la vista della rotazione; quella predefinita si sceglie in Generale. Diagramma ha controlli mobili meno, percentuale e più in basso a destra. Scorri per ingrandire dal 25% al 200%; clicca sulla percentuale o usa il clic centrale per tornare al 100%. Trascina lo spazio vuoto del diagramma per spostare la vista. Elenco usa normali barre di scorrimento, con schede adiacenti e rami racchiusi in riquadri, Falso prima di Vero. I tempi di recupero usano una griglia scorrevole separata. Trascinare le schede le riordina in ogni vista. I corpi di rotazione validi possono contenere fino a 2.000 passi in totale; le aree di lavoro grandi riutilizzano i controlli delle schede vicine mentre navighi. I rami compressi nascondono di proposito i propri figli.",
-- 76bac84a English: New / Duplicate / Import / Compare
[2633] = "Nuovo / Duplica / Importa / Confronta",
-- c4875790 English: Choose a category and search for a condition. Hidden removes it from pickers
--     without deleting its definition. Switch Condition controls its availability for automatic
--     rotation switching. Move To stages a category destination; its Apply button confirms the
--     move. The assigned category opens category management. Sidebar arrows and dragging order
--     entries. Page Apply saves the draft; Discard abandons edits to a saved entry. Custom
--     conditions can be edited, duplicated or deleted.
[2634] = "Scegli una categoria e cerca una condizione. Nascosta la rimuove dai selettori senza eliminarne la definizione. Condizione di cambio ne controlla la disponibilità per il cambio automatico di rotazione. Sposta in prepara una categoria di destinazione; il suo pulsante Applica conferma lo spostamento. La categoria assegnata apre la gestione delle categorie. Le frecce della barra laterale e il trascinamento ordinano le voci. Applica della pagina salva la bozza; Scarta abbandona le modifiche a una voce salvata. Le condizioni personalizzate possono essere modificate, duplicate o eliminate.",
-- be63470b English: Select an effect to edit its name, type and type-specific settings. The icon
--     previews it live. Sequence sections edit animation, color, pulse or custom frames in order.
--     Duplicate creates an independent effect. Drag a sequence card surface to reorder it; fields
--     remain editable. New effects can be configured before naming. Apply saves the draft; Discard
--     abandons edits to a saved entry. Import stages a validated replacement.
[2635] = "Seleziona un effetto per modificarne nome, tipo e impostazioni specifiche del tipo. L'icona ne mostra l'anteprima dal vivo. Le sezioni della sequenza modificano in ordine i fotogrammi di animazione, colore, pulsazione o personalizzati. Duplica crea un effetto indipendente. Trascina la superficie di una scheda della sequenza per riordinarla; i campi restano modificabili. I nuovi effetti possono essere configurati prima di ricevere un nome. Applica salva la bozza; Scarta abbandona le modifiche a una voce salvata. Importa prepara una sostituzione convalidata.",
-- e7df5868 English: Choose an item set and edit its priority list. Global shares the set across
--     profiles. Move arrows change item priority. Bind item set picks up an available item for
--     placement on an action bar; The binding pill removes matching bound bar actions when
--     unbinding, outside combat. Reset restores a packaged set. Search or drag items into reference
--     fields. Apply saves settings; Discard abandons edits to a saved entry. Binding changes are
--     explicit action-bar operations.
[2636] = "Scegli un set di oggetti e modificane l'elenco delle priorità. Globale condivide il set tra i profili. Le frecce di spostamento cambiano la priorità degli oggetti. Associa set di oggetti prende un oggetto disponibile da collocare su una barra delle azioni; quando annulli l'associazione, l'etichetta di associazione rimuove, fuori combattimento, le azioni associate corrispondenti dalla barra. Reimposta riporta un set incluso allo stato originale. Cerca o trascina oggetti nei campi di riferimento. Applica salva le impostazioni; Scarta abbandona le modifiche a una voce salvata. Le modifiche alle associazioni sono operazioni esplicite sulla barra delle azioni.",
-- 27a02657 English: Press Enter or leave a text field to stage its value; Apply saves the draft.
--     Invalid text stays red and must be corrected before Apply; Discard can abandon it. Searchable
--     selectors open on click and filter as you type. Section headings collapse or expand their
--     contents.
[2637] = "Premi Invio o esci da un campo di testo per preparare il suo valore; Applica salva la bozza. Il testo non valido resta rosso e va corretto prima di Applica; Scarta può abbandonarlo. I selettori con ricerca si aprono al clic e filtrano mentre digiti. Le intestazioni di sezione comprimono o espandono il loro contenuto.",
-- 53a70ff7 English: Editing this list
-- Context: Help topic title at the top of the item list dialog help.
[2638] = "Modifica di questo elenco",
-- d71ea291 English: This window edits only the item list you opened. Search or drag items into the
--     fields, then arrange preferred items first. A named item set is shared by its other users; a
--     custom list belongs to the calling condition or action draft. Applying this list does not
--     apply the parent editor.
[2639] = "Questa finestra modifica solo l'elenco di oggetti che hai aperto. Cerca o trascina oggetti nei campi, poi metti per primi quelli preferiti. Un set di oggetti con nome è condiviso con chi altro lo usa; un elenco personalizzato appartiene alla bozza della condizione o dell'azione che lo richiama. Applicare questo elenco non applica l'editor principale.",
-- 05cdc879 English: Use a row's red trash can to remove that entry from the draft list. This does
--     not delete a named item set or remove an item from your inventory. The removal takes effect
--     when you Apply this list.
[2640] = "Usa il cestino rosso di una riga per rimuovere quella voce dall'elenco in bozza. Non elimina un set di oggetti con nome né rimuove un oggetto dal tuo inventario. La rimozione ha effetto quando applichi questo elenco.",
-- 3cedce54 English: Apply validates every entry and writes the edited list back to its original
--     owner. Discard closes without changing it. Closing with pending edits offers Apply, Discard
--     or Cancel; Cancel keeps this window open. View Changes compares the original list with this
--     draft. If the original list changed elsewhere, close and reopen it before applying.
[2641] = "Applica convalida ogni voce e riscrive l'elenco modificato presso il suo proprietario originale. Scarta chiude senza modificarlo. Chiudere con modifiche in sospeso propone Applica, Scarta o Annulla; Annulla mantiene aperta questa finestra. Mostra modifiche confronta l'elenco originale con questa bozza. Se l'elenco originale è stato modificato altrove, chiudilo e riaprilo prima di applicare.",
-- 54637cac English: Proc Glow: use the animated actionbar proc border from LibCustomGlow. Rotation
--     Master checks the required game artwork and animation support before using it. Unsupported
--     clients use Pixel glow instead; the definition remains portable. Color and offsets come from
--     the profile or the cooldown.
[2642] = "Bagliore proc: usa il bordo animato dei proc della barra delle azioni di LibCustomGlow. Prima di usarlo, Rotation Master verifica che siano presenti la grafica di gioco e il supporto alle animazioni necessari. I client non supportati usano invece il bagliore Pixel; la definizione resta trasferibile. Colore e scostamenti provengono dal profilo o dal tempo di recupero.",
-- 265e2457 English: Time in seconds for one repeating proc-border animation, from 0.1 to 5. Use the
--     slider or enter an exact value in its number field. Changing the value updates the preview.
[2643] = "Durata in secondi di un ciclo dell'animazione ripetuta del bordo del proc, da 0,1 a 5. Usa il cursore o inserisci un valore esatto nel campo numerico. Cambiare il valore aggiorna l'anteprima.",
-- 50bd053e English: Play the opening burst when this highlight first appears, then repeat its
--     border animation. Off by default. Refreshing an already visible Proc Glow does not restart
--     the burst.
[2644] = "Riproduci il lampo iniziale quando questa evidenziazione compare per la prima volta, poi ripeti l'animazione del bordo. Disattivato per impostazione predefinita. Aggiornare un Bagliore proc già visibile non fa ripartire il lampo iniziale.",
-- a0515628 English: Rotations belong to the active settings profile. New copies use Class, shared
--     by your characters of that class; Metadata can change this to This character. Built In
--     rotations show only for their declared class or universal use. Equal identifiers in different
--     owners remain separate entries.
[2645] = "Le rotazioni appartengono al profilo di impostazioni attivo. Le nuove copie usano Classe, condivisa dai tuoi personaggi di quella classe; in Metadati puoi cambiarla in Questo personaggio. Le rotazioni integrate compaiono solo per la classe dichiarata o per l'uso universale. Identificatori uguali con proprietari diversi restano voci separate.",
-- 774a185e English: Older rotations without a recorded owner stay in an archive. Recover unassigned
--     rotations opens the current profile and character archives for inspection or copying. Choose
--     Class or This character to adopt one. Adoption preserves its identifier and evidence, refuses
--     an existing destination, and leaves incomplete records unavailable until repaired.
[2646] = "Le rotazioni più vecchie senza un proprietario registrato restano in un archivio. Recupera rotazioni non assegnate apre gli archivi del profilo e del personaggio attuali per esaminarle o copiarle. Scegli Classe o Questo personaggio per adottarne una. L'adozione conserva il suo identificatore e le prove, rifiuta una destinazione esistente e lascia non disponibili i record incompleti finché non vengono riparati.",
-- 4886d663 English: Enable Questie integration
-- Context: Help topic title in Integrations help for the checkbox that turns on the Questie
--     integration.
[2647] = "Attiva l'integrazione con Questie",
-- 3a9724aa English: Review supported addons, detected versions and status by integration type.
--     Expand or collapse each integration group. Click an addon name to choose a copyable release
--     or source link. Configure editor and optional provider preferences here; Apply saves
--     preferences for this profile and Discard keeps saved settings.
[2648] = "Esamina gli addon supportati, le versioni rilevate e lo stato per tipo di integrazione. Espandi o comprimi ogni gruppo di integrazioni. Clicca sul nome di un addon per scegliere un link copiabile alla versione o al codice sorgente. Configura qui le preferenze dell'editor e dei fornitori facoltativi; Applica salva le preferenze per questo profilo e Scarta mantiene le impostazioni salvate.",
-- 25f09788 English: Opt in to Questie callbacks for this profile, then Apply. Discard does not
--     change the saved connection. Readiness, API compatibility, source-tested version and native
--     acceptance are reported separately. The adapter retains recent update receipts only; they do
--     not prove quest progress or completion and do not select rotations. No background polling is
--     used.
[2649] = "Attiva le callback di Questie per questo profilo, poi usa Applica. Scarta non cambia il collegamento salvato. Disponibilità, compatibilità dell'API, versione testata sul sorgente e accettazione nativa sono riportate separatamente. L'adattatore conserva solo le ricevute degli aggiornamenti recenti; queste non dimostrano l'avanzamento o il completamento delle missioni e non selezionano rotazioni. Non viene usato alcun polling in background.",
-- 3877e4d7 English: Enable DBM or BigWigs to feed the Boss Mod conditions (encounter, stage and
--     ability timers), then Apply. Only one boss mod can be enabled; enabling one disables the
--     other. RM listens to the boss mod's own callbacks and never polls it or changes its settings.
--     With none enabled, or the enabled addon not loaded, Boss Mod conditions are unavailable.
--     Supported on Classic Era, TBC and Classic progression clients.
[2650] = "Attiva DBM o BigWigs per alimentare le condizioni Boss Mod (scontro, fase e timer delle abilità), poi usa Applica. Si può attivare un solo boss mod; attivarne uno disattiva l'altro. RM ascolta le callback del boss mod stesso e non lo interroga mai né ne modifica le impostazioni. Se nessuno è attivato, o se l'addon attivato non è caricato, le condizioni Boss Mod non sono disponibili. Supportato sui client Classic Era, TBC e Classic progression.",
-- c9949fc6 English: Rotation Master publishes a LibDataBroker data source with the active rotation,
--     a tooltip and click menus. Titan Panel and other LibDataBroker displays show it without
--     further setup: in Titan, add Rotation Master from the plugin menu. Panel absence has no
--     effect on rotation selection.
[2651] = "Rotation Master pubblica una fonte dati LibDataBroker con la rotazione attiva, un tooltip e menu al clic. Titan Panel e gli altri visualizzatori LibDataBroker la mostrano senza ulteriori configurazioni: in Titan, aggiungi Rotation Master dal menu dei plugin. L'assenza di un pannello non influisce sulla selezione della rotazione.",
-- 59df493c English: Record spell cast receipts for thirty seconds without changing settings or
--     gameplay polling. While it runs this button reads Stop cast capture and ends the capture
--     early, keeping what was recorded.
[2652] = "Registra le ricevute dei lanci degli incantesimi per trenta secondi senza cambiare le impostazioni né il polling di gioco. Durante l'acquisizione questo pulsante diventa Interrompi acquisizione lanci e la termina in anticipo, conservando quanto registrato.",
-- 0ffbf212 English: Open the copyable cast receipt report. It stays disabled until a cast capture
--     has produced a report and while a capture is running.
[2653] = "Apri il report copiabile delle ricevute dei lanci. Resta disattivato finché un'acquisizione dei lanci non ha prodotto un report e mentre un'acquisizione è in corso.",
-- 472590ae English: Provider
-- Context: Column heading in the addon download links dialog: the website that hosts the download
--     (e.g. CurseForge).
[2654] = "Fornitore",
-- e7a241de English: URL
-- Context: Column heading in the addon download links dialog: the web address of the download page.
[2655] = "URL",
-- 8ea4edb6 English: Select URL for copying (Ctrl+C)
[2656] = "Seleziona l'URL da copiare (Ctrl+C)",
-- 42592899 English: Syntax highlighting applies only to the Native Lua editor. Apply saves this
--     preference for the next source-editor opening; it does not switch a selected external editor.
--     Show line numbers under the editor heading applies to every provider.
[2657] = "L'evidenziazione della sintassi si applica solo all'editor Lua Nativo. Applica salva questa preferenza per la prossima apertura dell'editor del codice sorgente; non cambia un editor esterno selezionato. Mostra numeri di riga, sotto l'intestazione dell'editor, si applica a ogni fornitore.",
-- eb084da9 English: Enable separately installed Masque here and Apply. General > Preview then
--     provides a Skin dropdown that updates the preview immediately. Masque owns the skin
--     selection; /masque opens its other settings. The preview window keeps its native appearance.
--     Missing or incompatible APIs and provider errors retain the native preview.
[2658] = "Attiva qui Masque, installato separatamente, e usa Applica. Generale > Anteprima offre allora un menu a tendina Skin che aggiorna subito l'anteprima. La scelta della skin spetta a Masque; /masque apre le sue altre impostazioni. La finestra di anteprima mantiene il suo aspetto nativo. Se le API mancano o sono incompatibili, o se il fornitore genera errori, l'anteprima resta nativa.",
-- 34199d23 English: Enable Masque in Integrations to choose a skin. Skin changes update the open
--     preview immediately and are saved by Masque, independently of Apply or Discard. Without
--     enabled Masque support, the preview uses Blizzard Classic. Preview toggles sample icons
--     whether Masque is enabled or not.
[2659] = "Attiva Masque in Integrazioni per scegliere una skin. I cambi di skin aggiornano subito l'anteprima aperta e vengono salvati da Masque, indipendentemente da Applica o Scarta. Senza il supporto a Masque attivato, l'anteprima usa Blizzard Classic. Anteprima mostra o nasconde le icone di esempio, che Masque sia attivato o meno.",
-- 5b167013 English: Click Preview to toggle temporary sample icons when no real recommendations are
--     available. Real recommendations replace the samples. This does not change Preview Spells,
--     cast spells, or save the sample state.
[2660] = "Clicca su Anteprima per mostrare o nascondere icone di esempio temporanee quando non ci sono consigli reali disponibili. I consigli reali sostituiscono gli esempi. Non modifica Anteprima incantesimi, non lancia incantesimi e non salva lo stato degli esempi.",
-- 04025773 English: Optional conditions use the Announcement condition list and All, Any and Not
--     groups. For spell, pet and item announcements, they run when the configured action and event
--     match. For Via Script/Macro, they run when you invoke the saved identifier. Each output card
--     checks its own conditions. Only a matching result allows that output; unavailable data skips
--     that card while later cards remain independent. In Group can check the Spell recipient
--     recorded for this cast, including click casting, without using your selected target. Choose
--     Announcement target to check the spell recipient for automatic entries, or the supplied unit
--     for Via Script/Macro; Whisper uses that same supplied unit. Automatic entries pass the
--     recorded recipient name to native unit queries. A missing or unresolvable recipient skips its
--     required condition; an unrelated selected target is never substituted. Missing or ambiguous
--     required recipients do not match. Apply in the condition editor updates the announcement
--     draft; Apply on Announces saves it. Cancel or Discard abandons draft changes.
[2661] = "Le condizioni facoltative usano l'elenco delle condizioni di Annuncio e i gruppi Tutte, Qualsiasi e Non. Per gli annunci di incantesimi, famigli e oggetti, vengono eseguite quando l'azione e l'evento configurati corrispondono. Per Tramite script/macro, vengono eseguite quando richiami l'identificatore salvato. Ogni scheda di output controlla le proprie condizioni. Solo un risultato corrispondente consente quell'output; i dati non disponibili fanno saltare quella scheda, mentre le schede successive restano indipendenti. Nel gruppo può controllare il Destinatario dell'incantesimo registrato per questo lancio, compreso il lancio con clic, senza usare il bersaglio selezionato. Scegli Bersaglio dell'annuncio per controllare il destinatario dell'incantesimo per le voci automatiche, oppure l'unità fornita per Tramite script/macro; Sussurra usa la stessa unità fornita. Le voci automatiche passano il nome del destinatario registrato alle interrogazioni native sulle unità. Un destinatario mancante o non risolvibile fa saltare la condizione che lo richiede; non viene mai usato al suo posto un bersaglio selezionato non pertinente. I destinatari richiesti mancanti o ambigui non corrispondono. Applica nell'editor delle condizioni aggiorna la bozza dell'annuncio; Applica in Annunci la salva. Annulla o Scarta abbandona le modifiche alla bozza.",
-- 6c64ce13 English: Choose the unit whose membership in your party or raid is checked. Player keeps
--     the original player group-status behavior. Spell recipient uses only the current announcement
--     event context; without that readable context the result is unavailable. It never substitutes
--     your selected target or a previous cast.
[2662] = "Scegli l'unità di cui verificare l'appartenenza al tuo gruppo o alla tua incursione. Giocatore mantiene il comportamento originale dello stato di gruppo del giocatore. Destinatario dell'incantesimo usa solo il contesto dell'evento di annuncio attuale; senza un contesto leggibile, il risultato non è disponibile. Non usa mai al suo posto il bersaglio selezionato o un lancio precedente.",
-- 27cc3255 English: Checked tests raid membership only. Unchecked tests party membership or raid
--     membership. A known nonmember is false; unavailable native data stays unavailable, including
--     under NOT.
[2663] = "Se selezionato, verifica solo l'appartenenza all'incursione. Se deselezionato, verifica l'appartenenza al gruppo o all'incursione. Un non membro noto dà falso; i dati nativi non disponibili restano non disponibili, anche con NOT.",
-- d44133b4 English: Choose tabs to browse Rotations, General, Conditions, Functions, Effects, Item
--     Sets, Announces, Profiles and Integrations. The opened panes have their own Help for page
--     controls. Search and filters belong to the current page. Built In entries remain read-only;
--     Duplicate creates an editable copy.
[2664] = "Usa le schede per sfogliare Rotazioni, Generale, Condizioni, Funzioni, Effetti, Set di oggetti, Annunci, Profili e Integrazioni. I riquadri aperti hanno un proprio Aiuto per i controlli della pagina. Ricerca e filtri appartengono alla pagina attuale. Le voci integrate restano di sola lettura; Duplica crea una copia modificabile.",
-- 28510b80 English: Scale changes the whole workbench and its child windows from 70% to 130%. Drag
--     the top-left slider or enter an integer percentage and press Enter. Escape restores the saved
--     scale text. Drag the title bar to move; drag the lower-right corner to resize.
[2665] = "Scala modifica l'intero banco di lavoro e le sue finestre secondarie dal 70% al 130%. Trascina il cursore in alto a sinistra o inserisci una percentuale intera e premi Invio. Esc ripristina il testo della scala salvata. Trascina la barra del titolo per spostare la finestra; trascina l'angolo in basso a destra per ridimensionarla.",
-- 81701f02 English: Close with X, Escape, or right-click inside the frontmost RM window. Child
--     dialogs have their own close controls and follow the window scale. The language selector
--     changes the workbench language; project links open a copyable address.
[2666] = "Chiudi con X, Esc o con il clic destro all'interno della finestra di RM in primo piano. Le finestre di dialogo secondarie hanno i propri controlli di chiusura e seguono la scala della finestra. Il selettore della lingua cambia la lingua del banco di lavoro; i link del progetto aprono un indirizzo copiabile.",
-- ae7a65d1 English: Most settings and source editors keep drafts until Apply. Leaving a dirty page
--     offers Apply, Discard or Cancel; invalid fields remain visible. Profile activation and
--     confirmed replacement, action-bar binding and diagnostic capture have their own explicit
--     actions. Help never applies or discards edits.
[2667] = "La maggior parte delle impostazioni e degli editor del codice sorgente mantiene le bozze fino ad Applica. Uscire da una pagina con modifiche propone Applica, Scarta o Annulla; i campi non validi restano visibili. L'attivazione del profilo e la sostituzione confermata, l'associazione alla barra delle azioni e l'acquisizione diagnostica hanno azioni esplicite proprie. L'Aiuto non applica né scarta mai le modifiche.",
-- 2d6b5cc8 English: Gold question marks open full Help for their window, page or card. Hover
--     controls for brief tips. Help does not save settings or commit pending text; spell and item
--     fields keep their native reference tooltips.
[2668] = "I punti interrogativi dorati aprono l'Aiuto completo della loro finestra, pagina o scheda. Passa il mouse sui controlli per brevi suggerimenti. L'Aiuto non salva le impostazioni né conferma il testo in sospeso; i campi di incantesimi e oggetti mantengono i loro tooltip di riferimento nativi.",
-- 8fb57308 English: Open full Help for these controls without applying edits.
[2669] = "Apri l'Aiuto completo per questi controlli senza applicare le modifiche.",
-- b9cc9038 English: Explain window navigation, scaling, closing and drafts.
[2670] = "Spiega la navigazione, il ridimensionamento, la chiusura e le bozze della finestra.",
-- 859a4f2c English: Open full Help for this page without switching tabs or applying edits.
[2671] = "Apri l'Aiuto completo per questa pagina senza cambiare scheda né applicare le modifiche.",
-- c0a96039 English: Set the workbench and child-window scale from 70% to 130%; enter a whole
--     percentage or drag the slider.
[2672] = "Imposta la scala del banco di lavoro e delle finestre secondarie dal 70% al 130%; inserisci una percentuale intera o trascina il cursore.",
-- 36760759 English: Edit the value; Enter or leaving the field checks and accepts valid text. Page
--     Help explains when changes are saved.
[2673] = "Modifica il valore; Invio o l'uscita dal campo controllano e accettano il testo valido. L'Aiuto della pagina spiega quando le modifiche vengono salvate.",
-- 43f47d2a English: Click to toggle this option. Page Help explains when changes are saved.
[2674] = "Clicca per attivare o disattivare questa opzione. L'Aiuto della pagina spiega quando le modifiche vengono salvate.",
-- 1b2d4c57 English: Use this control for the current page; page Help explains its options and
--     consequences.
[2675] = "Usa questo controllo per la pagina attuale; l'Aiuto della pagina ne spiega le opzioni e le conseguenze.",
-- d885c6a2 English: Help for this condition is unavailable. Its registered definition is missing,
--     disabled or waiting for required functions. Opening Help does not register pending or
--     imported source.
[2676] = "L'Aiuto per questa condizione non è disponibile. La sua definizione registrata manca, è disattivata o attende le funzioni richieste. Aprire l'Aiuto non registra codice sorgente in sospeso o importato.",
-- 711bb065 English: This registered condition does not provide Help.
[2677] = "Questa condizione registrata non fornisce un Aiuto.",
-- d9c613e5 English: Open Help for this condition without changing its fields.
[2678] = "Apri l'Aiuto per questa condizione senza modificarne i campi.",
-- ac330ed0 English: Select all export text for manual copying. This button does not send it
--     anywhere.
[2679] = "Seleziona tutto il testo esportato per copiarlo manualmente. Questo pulsante non lo invia da nessuna parte.",
-- d8332c9a English: Clear the transfer text. A previous preview becomes invalid; saved settings
--     stay unchanged.
[2680] = "Cancella il testo del trasferimento. Un'anteprima precedente diventa non valida; le impostazioni salvate restano invariate.",
-- 7b980fdf English: Import into the displayed destination. Read the destination and review
--     requirements before continuing.
[2681] = "Importa nella destinazione visualizzata. Leggi la destinazione ed esamina i requisiti prima di continuare.",
-- f71901b9 English: Close this dialog without importing its text.
[2682] = "Chiudi questa finestra senza importarne il testo.",
-- 536a00ad English: Choose a new named copy or replacement of the selected editable entry.
[2683] = "Scegli una nuova copia con nome o la sostituzione della voce modificabile selezionata.",
-- 28928c04 English: Set the name for a new copy. Replacement keeps the selected entry as its
--     destination.
[2684] = "Imposta il nome di una nuova copia. La sostituzione mantiene come destinazione la voce selezionata.",
-- 128c10d4 English: Preview import shows everything this import contains, read-only, the way the
--     editor shows it. Nothing is saved.
[2685] = "Anteprima importazione mostra tutto ciò che contiene questa importazione, in sola lettura, come lo mostra l'editor. Non salva nulla.",
-- 853ec82f English: Check import lists problems with the text instead of its content: why it cannot
--     be imported and any unsupported data. It does not import or change anything.
[2686] = "Verifica importazione elenca i problemi del testo invece del suo contenuto: perché non può essere importato e quali dati non sono supportati. Non importa né modifica nulla.",
-- 27a3bd58 English: Explain profile import destinations and when changes are saved.
[2687] = "Spiega le destinazioni di importazione dei profili e quando le modifiche vengono salvate.",
-- ca00de4c English: Copy the text to export a profile, or paste profile text to import. The
--     destination controls choose a new profile or replacement of the selected saved profile.
--     Opening Help does not decode, import, or apply the text.
[2688] = "Copia il testo per esportare un profilo, oppure incolla il testo di un profilo per importarlo. I controlli della destinazione scelgono un nuovo profilo o la sostituzione del profilo salvato selezionato. Aprire l'Aiuto non decodifica, importa né applica il testo.",
-- 2625de29 English: REPLACE applies immediately to the selected saved profile after Import.
--     Replacing the active profile resets it and applies the imported settings; replacing another
--     profile writes that profile. Reopen the import if the selected saved profile changes.
[2689] = "SOSTITUZIONE si applica immediatamente al profilo salvato selezionato dopo Importa. Sostituire il profilo attivo lo ripristina e applica le impostazioni importate; sostituire un altro profilo sovrascrive quel profilo. Riapri l'importazione se il profilo salvato selezionato cambia.",
-- 74cf2bda English: NEW stages the imported profile in the Profiles editor. Import fills a
--     new-profile draft; the new profile is not saved or activated until you complete the creation
--     controls in that editor. Give it an unused name.
[2690] = "NUOVO prepara il profilo importato nell'editor dei Profili. Importa compila una bozza di nuovo profilo; il nuovo profilo non viene salvato né attivato finché non completi i controlli di creazione in quell'editor. Dagli un nome non ancora usato.",
-- 00c3d8f9 English: Explain this read-only review of imported source.
[2691] = "Spiega questo esame in sola lettura del codice sorgente importato.",
-- 3b8fed45 English: This view shows the selected imported function or condition source, its
--     original and destination identifiers, and available metadata. For a condition, choose a
--     callback to inspect its text. This view and its Help do not compile, execute, accept, or
--     register the source. Return to the bundle review to decide whether to import it.
[2692] = "Questa vista mostra il codice sorgente della funzione o della condizione importata selezionata, i suoi identificatori originale e di destinazione e i metadati disponibili. Per una condizione, scegli una callback per esaminarne il testo. Questa vista e il suo Aiuto non compilano, eseguono, accettano né registrano il codice sorgente. Torna all'esame del pacchetto per decidere se importarlo.",
-- c60faea8 English: Close this read-only source view and return to the bundle review.
[2693] = "Chiudi questa vista in sola lettura del codice sorgente e torna all'esame del pacchetto.",
-- 49411dfb English: Validate the pasted bundle and build a proposed import plan. Review does not
--     apply the plan.
[2694] = "Convalida il pacchetto incollato e crea un piano di importazione proposto. L'esame non applica il piano.",
-- b8726351 English: Include referenced custom function dependencies when producing export text.
[2695] = "Includi le dipendenze delle funzioni personalizzate referenziate quando produci il testo da esportare.",
-- 74de20bd English: Explain dependency-bundle export, review, and explicit import.
[2696] = "Spiega l'esportazione, l'esame e l'importazione esplicita dei pacchetti di dipendenze.",
-- 4449aeeb English: Export produces a function or condition bundle, optionally with its custom
--     function dependencies. For import, paste bundle text, choose Review import, inspect the
--     proposed identifiers and conflicts, and review source before applying. Apply import can
--     register trusted Lua source; accept only source you intend to run. Changing the text
--     invalidates the prior plan. Opening Help neither reviews nor applies the bundle.
[2697] = "Esporta produce un pacchetto di funzioni o condizioni, facoltativamente con le dipendenze delle funzioni personalizzate. Per importare, incolla il testo del pacchetto, scegli Esamina importazione, controlla gli identificatori e i conflitti proposti ed esamina il codice sorgente prima di applicare. Applica importazione può registrare codice sorgente Lua attendibile; accetta solo codice che intendi eseguire. Modificare il testo invalida il piano precedente. Aprire l'Aiuto non esamina né applica il pacchetto.",
-- 067adc87 English: Explain rotation preview, destination, and import scope.
[2698] = "Spiega l'anteprima, la destinazione e l'ambito di importazione delle rotazioni.",
-- fe3fd231 English: Copy the text to export the current rotation, or paste a rotation to import.
--     Choose replacement of the selected editable rotation or a new named copy. Class and This
--     character set the owner of a new copy; replacement keeps the original owner. The imported
--     rotation is opened for editing after a successful import.
[2699] = "Copia il testo per esportare la rotazione attuale, oppure incolla una rotazione per importarla. Scegli la sostituzione della rotazione modificabile selezionata o una nuova copia con nome. Classe e Questo personaggio impostano il proprietario di una nuova copia; la sostituzione mantiene il proprietario originale. Dopo un'importazione riuscita, la rotazione importata viene aperta per la modifica.",
-- d6789183 English: With Replace selected entry ticked, the button reads Compare import and shows
--     what would change in that rotation. For a new named copy it reads Preview import and shows
--     everything the import contains, read-only, as the rotation editor shows it. Neither saves
--     anything. Import is enabled only for a ready preview or comparison; changing the text
--     requires another one. Check import shows read-only diagnostics, including unsupported data
--     that prevents import.
[2700] = "Con Sostituisci la voce selezionata attivo, il pulsante si chiama Confronta importazione e mostra cosa cambierebbe in quella rotazione. Per una nuova copia con nome si chiama Anteprima importazione e mostra, in sola lettura, tutto ciò che contiene l'importazione, come lo mostra l'editor delle rotazioni. Nessuno dei due salva nulla. Importa è attivo solo con un'anteprima o un confronto pronti; modificare il testo ne richiede uno nuovo. Verifica importazione mostra la diagnostica in sola lettura, compresi i dati non supportati che impediscono l'importazione.",
-- 9a2297f1 English: Explain this read-only incoming rotation comparison.
[2701] = "Spiega questo confronto in sola lettura con la rotazione in arrivo.",
-- 4f0c847b English: This view compares the saved or exported rotation with the current incoming
--     preview. It does not apply changes. Close it to choose the destination and import from the
--     transfer dialog. A changed preview, closed owner, or changed profile retires this comparison
--     Help.
[2702] = "Questa vista confronta la rotazione salvata o esportata con l'anteprima attuale in arrivo. Non applica modifiche. Chiudila per scegliere la destinazione e importare dalla finestra di trasferimento. Un'anteprima modificata, un proprietario chiuso o un profilo cambiato rendono obsoleto questo Aiuto del confronto.",
-- c091ac0b English: Compare import shows what would change in the entry you are replacing, side by
--     side with its current content. Nothing is saved.
[2703] = "Confronta importazione mostra cosa cambierebbe nella voce che stai sostituendo, accanto al suo contenuto attuale. Non salva nulla.",
-- 64144a9e English: Explain this read-only preview of the incoming rotation.
[2704] = "Spiega questa anteprima in sola lettura della rotazione in arrivo.",
-- 91ca45b8 English: This view shows the rotation as it would be imported: name, specializations,
--     switch condition, steps and cooldowns. It is read-only and works on a copy; it saves and
--     changes nothing. Close it to choose the destination and import from the transfer dialog. A
--     changed text, closed transfer or changed profile retires this Help.
[2705] = "Questa vista mostra la rotazione come verrebbe importata: nome, specializzazioni, condizione di cambio, passi e tempi di recupero. È in sola lettura, lavora su una copia e non salva né modifica nulla. Chiudila per scegliere la destinazione e importare dalla finestra di trasferimento. Un testo modificato, un trasferimento chiuso o un profilo cambiato rendono obsoleto questo Aiuto.",
-- 5ac254c6 English: Macro invocation
-- Context: Help topic title in the Announces help: an example of how a macro calls an announcement.
[2706] = "Richiamo della macro",
-- 94a47c93 English: Supplied macro unit
-- Context: Help topic title in the Announces help: the unit that a macro passes to the
--     announcement.
[2707] = "Unità fornita dalla macro",
-- c3039a0d English: Invoke this saved identifier directly from your macro. The supplied unit
--     controls Announcement target conditions and Whisper; there is no implicit target.
[2708] = "Richiama questo identificatore salvato direttamente dalla tua macro. L'unità fornita controlla le condizioni Bersaglio dell'annuncio e Sussurra; non esiste un bersaglio implicito.",
-- d4f140f6 English: Via Script/Macro is invoked by its saved Identifier rather than a cast event.
--     It does not require a stored spell or item. Current conditions must match before any output.
--     This call attempts output synchronously; it does not establish that a spell was cast or
--     succeeded.
[2709] = "L'attivatore Tramite script/macro viene richiamato dal suo identificativo salvato anziché da un evento di lancio. Non richiede un incantesimo o un oggetto memorizzato. Le condizioni attuali devono essere soddisfatte prima di qualsiasi uscita. Questa chiamata tenta l'uscita in modo sincrono; non stabilisce che un incantesimo sia stato lanciato o sia andato a buon fine.",
-- 978b4fbf English: Use a unique, case-sensitive identifier of at most 64 ASCII characters. Start
--     with a letter or underscore; subsequent characters may also include digits, dots or hyphens.
--     Identifiers are scoped to the active profile, including disabled entries. Duplicate assigns a
--     distinct identifier; ambiguous imports and Apply are rejected.
[2710] = "Usa un identificativo univoco, con distinzione tra maiuscole e minuscole, di massimo 64 caratteri ASCII. Inizia con una lettera o un trattino basso; i caratteri successivi possono includere anche cifre, punti o trattini. Gli identificativi valgono all'interno del profilo attivo, comprese le voci disattivate. Duplica assegna un identificativo distinto; le importazioni ambigue e Applica vengono rifiutati.",
-- 7247934f English: Use /run RM_Annouce('FOO','mouseover',nil). RM_Announce is the same function.
--     The target unit and spell are optional: /run RM_Announce('FOO',nil,403) or /run
--     RM_Announce('FOO','target','Lightning Bolt'). Spell names depend on client language.
--     {{event}} becomes Via Script/Macro; {{target}} and {{spell}} use the supplied arguments. A
--     required missing argument skips output. {{item}} is not supplied by this API. A resurrection
--     message announces an attempt, not a completed resurrection. Examples are text only; RM does
--     not create or execute macros.
[2711] = "Usa /run RM_Annouce('FOO','mouseover',nil). RM_Announce è la stessa funzione. L'unità bersaglio e l'incantesimo sono facoltativi: /run RM_Announce('FOO',nil,403) oppure /run RM_Announce('FOO','target','Lightning Bolt'). I nomi degli incantesimi dipendono dalla lingua del client. {{event}} diventa Tramite script/macro; {{target}} e {{spell}} usano gli argomenti forniti. Se manca un argomento richiesto, l'uscita viene saltata. {{item}} non è fornito da questa API. Un messaggio di resurrezione annuncia un tentativo, non una resurrezione completata. Gli esempi sono solo testo; RM non crea né esegue macro.",
-- fda702d4 English: Supply a readable unit token such as mouseover, target or focus. RM resolves
--     that exact unit name and rechecks its identity during delivery. Announcement target
--     conditions and Whisper use this same unit. Omitting the argument does not use your selected
--     target, yourself, a prior cast or a prior macro call. Missing Announcement target data
--     remains unavailable, including under NOT.
[2712] = "Fornisci un identificativo unità leggibile come mouseover, target o focus. RM risolve il nome esatto di quell'unità e ne ricontrolla l'identità durante l'invio. Le condizioni sul bersaglio dell'annuncio e Sussurro usano questa stessa unità. Omettere l'argomento non usa il bersaglio selezionato, te stesso, un lancio precedente o una chiamata macro precedente. I dati mancanti sul bersaglio dell'annuncio restano non disponibili, anche sotto NOT.",
-- 4c48bcf5 English: Checked directs a named emote to the supplied macro unit. Missing or unreadable
--     target data skips the targeted emote; unchecked is targetless.
[2713] = "Se selezionato, indirizza un'emote con nome all'unità fornita alla macro. Se i dati del bersaglio mancano o non sono leggibili, l'emote mirata viene saltata; se deselezionato, l'emote è senza bersaglio.",
-- 4dbc9c41 English: Available only for Via Script/Macro. Attempt a Say message directly in the
--     invoking call. Blizzard may reject macro-origin chat, including during instance encounters;
--     RM does not attest hardware input, defer delivery, retry or guarantee visible output.
[2714] = "Disponibile solo per Tramite script/macro. Tenta un messaggio /say direttamente nella chiamata che lo richiama. Blizzard può rifiutare la chat originata da una macro, anche durante gli scontri nelle istanze; RM non attesta l'input hardware, non rimanda l'invio, non riprova e non garantisce un risultato visibile.",
-- a1cf5fb0 English: Available only for Via Script/Macro. Attempt a Yell message directly in the
--     invoking call. Native macro and encounter restrictions still apply; a completed API call is
--     not confirmation of delivery.
[2715] = "Disponibile solo per Tramite script/macro. Tenta un messaggio /yell direttamente nella chiamata che lo richiama. Restano valide le restrizioni native su macro e scontri; una chiamata API completata non conferma l'invio.",
-- a736bec3 English: Available only for Via Script/Macro. Whisper uses the exact supplied unit name
--     and requires a readable player identity. No target means no Whisper. Native macro and
--     encounter restrictions still apply; RM never substitutes another recipient or retries.
[2716] = "Disponibile solo per Tramite script/macro. Sussurro usa il nome esatto dell'unità fornita e richiede un'identità di giocatore leggibile. Senza bersaglio non c'è Sussurro. Restano valide le restrizioni native su macro e scontri; RM non sostituisce mai il destinatario e non riprova.",
-- b6082c37 English: Offer this condition type when editing announcement conditions. This flag is
--     independent of Switch Condition and does not remove or invalidate conditions already saved in
--     announcements.
[2717] = "Offri questo tipo di condizione durante la modifica delle condizioni di annuncio. Questa opzione è indipendente da Condizione di cambio e non rimuove né invalida le condizioni già salvate negli annunci.",
-- 45320409 English: One trigger can send an ordered series of outputs. Each expanded card has its
--     own destination, text or sound, conditions and enabled state. Help describes that card.
--     Duplicate makes an independent card; delete removes it. Use the arrows, or drag a card from
--     anywhere on it, to change order. Add output, on the Outputs header row, appends a card; drag
--     it into a gap to insert one there. A legacy announcement stays unchanged on display. Adding,
--     duplicating or removing a card, choosing Channel, or changing to an action type that cannot
--     use its saved destination converts only the draft to output cards. Up to 64 outputs are
--     allowed; an empty series sends nothing. Apply saves the draft and Discard restores it.
[2718] = "Un attivatore può inviare una serie ordinata di uscite. Ogni scheda espansa ha la propria destinazione, testo o suono, condizioni e stato di attivazione. Aiuto descrive quella scheda. Duplica crea una scheda indipendente; elimina la rimuove. Usa le frecce, o trascina una scheda da qualsiasi punto, per cambiarne l'ordine. Aggiungi uscita, nella riga d'intestazione Uscite, aggiunge una scheda in fondo; trascinala in uno spazio vuoto per inserirla lì. Un annuncio nel formato precedente resta invariato in visualizzazione. Aggiungere, duplicare o rimuovere una scheda, scegliere Canale o passare a un tipo di azione che non può usare la destinazione salvata converte in schede di uscita solo la bozza. Sono consentite fino a 64 uscite; una serie vuota non invia nulla. Applica salva la bozza e Scarta la ripristina.",
-- 3c9708b1 English: Via Script/Macro outputs can send to a joined chat channel. Open Channel to
--     refresh the joined names, then select the exact name. A saved name remains visible when
--     unavailable; that output is skipped until the channel is joined under that name. Numeric
--     channel IDs are not saved and channels are never joined automatically. Native delivery
--     permissions still apply.
[2719] = "Le uscite Tramite script/macro possono inviare a un canale di chat a cui ti sei unito. Apri Canale per aggiornare i nomi dei canali a cui ti sei unito, poi seleziona il nome esatto. Un nome salvato resta visibile anche quando non è disponibile; quell'uscita viene saltata finché non ti unisci al canale con quel nome. Gli ID numerici dei canali non vengono salvati e RM non si unisce mai automaticamente ai canali. Restano valide le autorizzazioni native di invio.",
-- 6de77638 English: Choose an announcement trigger, then edit its always expanded output cards.
--     Each card has a destination, conditions, enabled state and Help. Add, duplicate, delete, move
--     or drag outputs within the announcement. Joined channel names are available for Via
--     Script/Macro. New opens a draft; Apply saves it and Discard restores it. Imports are
--     validated and never execute code.
[2720] = "Scegli un attivatore di annuncio, poi modifica le sue schede di uscita, sempre espanse. Ogni scheda ha una destinazione, condizioni, stato di attivazione e Aiuto. Aggiungi, duplica, elimina, sposta o trascina le uscite all'interno dell'annuncio. I nomi dei canali a cui ti sei unito sono disponibili per Tramite script/macro. Nuovo apre una bozza; Applica la salva e Scarta la ripristina. Le importazioni vengono convalidate e non eseguono mai codice.",
-- 318a2558 English: Recommends whatever spell Blizzard's Assisted Combat suggests next, read each
--     time the rotation is evaluated. It highlights that spell's button and shows in the preview
--     like a spell step, and is held to the same requirements: known, usable, off cooldown and in
--     range. When nothing is suggested, the suggested spell is not on your bars, or Assisted Combat
--     is unavailable (anywhere but Retail, or a specialization without it), the step is skipped.
--     Rotation list only.
[2721] = "Consiglia qualunque incantesimo l'Assistente di Combattimento di Blizzard suggerisca come prossimo, letto a ogni valutazione della rotazione. Evidenzia il pulsante di quell'incantesimo e compare nell'anteprima come un passaggio incantesimo, ed è soggetto agli stessi requisiti: conosciuto, utilizzabile, non in tempo di recupero e a portata. Quando non viene suggerito nulla, l'incantesimo suggerito non è sulle tue barre o l'Assistente di Combattimento non è disponibile (ovunque tranne Retail, o una specializzazione che non lo prevede), il passaggio viene saltato. Solo nell'elenco della rotazione.",
-- d462cf8d English: Who highlights the button while a "Blizzard's suggestion" step is the
--     recommendation. Rotation Master's glow uses the effect below. Blizzard's Assisted Highlight
--     turns on the game's own highlight (Options, Gameplay, Combat, Assisted Highlight) while a
--     rotation with that step is active, and Rotation Master leaves that step's button to it; Both
--     shows the two. Rotation Master turns Blizzard's highlight on only outside combat, never
--     changes it if it was already on, and puts your setting back when the rotation ends, Rotation
--     Master is disabled, or you log out or reload. If you change the setting yourself meanwhile,
--     your choice is kept. Blizzard's highlight follows Blizzard's suggestion all the time, also
--     while another step is recommended, and it shows on Blizzard's own action bars only, so choose
--     Rotation Master's glow or Both with a bar addon. The choice is hidden on clients without
--     Blizzard's highlight (Forever and the Classic clients).
[2722] = "Chi evidenzia il pulsante mentre un passo «suggerimento di Blizzard» è la raccomandazione. Il bagliore di Rotation Master usa l'effetto qui sotto. L'Evidenziazione assistita di Blizzard attiva l'evidenziazione del gioco (Opzioni, Gameplay, Combattimento, Evidenziazione assistita) mentre è attiva una rotazione con quel passo, e Rotation Master le lascia il pulsante di quel passo; Entrambi mostra tutte e due. Rotation Master attiva l'evidenziazione di Blizzard solo fuori dal combattimento, non la modifica mai se era già attiva e ripristina la tua impostazione quando la rotazione termina, Rotation Master viene disattivato oppure esci o ricarichi. Se nel frattempo cambi tu l'impostazione, la tua scelta viene mantenuta. L'evidenziazione di Blizzard segue sempre il suggerimento di Blizzard, anche mentre è raccomandato un altro passo, e compare solo sulle barre delle azioni di Blizzard, quindi con un addon per le barre scegli il bagliore di Rotation Master oppure Entrambi. La scelta è nascosta sui client senza l'evidenziazione di Blizzard (Forever e i client Classic).",
-- e031d376 English: Add Rotation Master lines to spell and item tooltips. This is the master
--     switch: off, Rotation Master adds nothing to any tooltip, and the options below do nothing.
--     Lines are only added, never read from the tooltip, so other tooltip addons are unaffected.
[2723] = "Aggiunge righe di Rotation Master alle descrizioni comando di incantesimi e oggetti. È l'interruttore generale: se è spento, Rotation Master non aggiunge nulla a nessuna descrizione e le opzioni sotto non hanno effetto. Le righe vengono solo aggiunte, mai lette dalla descrizione, quindi gli altri addon di descrizioni non sono toccati.",
-- b52dc56f English: In an item tooltip, list the Rotation Master item sets that contain the item:
--     your profile's and the shared ones from the Item Sets page. Names beyond the limit below end
--     the line with how many more there are.
[2724] = "Nella descrizione di un oggetto, elenca i set di oggetti di Rotation Master che lo contengono: quelli del tuo profilo e quelli condivisi della pagina Set di oggetti. I nomi oltre il limite qui sotto chiudono la riga indicando quanti altri ce ne sono.",
-- a142e568 English: In a spell or item tooltip, list the rotations for your current specialization
--     that use it as a step in the rotation or cooldown list. A rotation that is switched off is
--     shown dimmed and marked disabled. Built In rotations that are not for this version of the
--     game or your specialization are left out. The list is refreshed out of combat after a
--     rotation or item set changes.
[2725] = "Nella descrizione di un incantesimo o di un oggetto, elenca le rotazioni della tua specializzazione attuale che lo usano come passo nella lista della rotazione o dei tempi di recupero. Una rotazione disattivata appare attenuata e contrassegnata come disattivata. Le rotazioni integrate non adatte a questa versione del gioco o alla tua specializzazione vengono omesse. L'elenco si aggiorna fuori combattimento dopo la modifica di una rotazione o di un set di oggetti.",
-- 5e8b512d English: Also count a spell or item that appears only inside a condition (for example
--     "spell is ready" or "item is carried"), not just as a step. Off by default because it lists
--     more rotations.
[2726] = "Conta anche un incantesimo o un oggetto che compare solo dentro una condizione (per esempio \"l'incantesimo è pronto\" o \"l'oggetto è nella borsa\"), non solo come passo. Disattivato di default perché elenca più rotazioni.",
-- dffd6006 English: How many names a tooltip line lists before it ends with "(+N more)". A lower
--     number keeps tooltips short.
[2727] = "Quanti nomi elenca una riga della descrizione prima di chiudersi con \"(+N altri)\". Un numero più basso mantiene le descrizioni brevi.",
-- 83e079d3 English: Your talent specialization. Choose a class, then one of its specializations;
--     your own class is selected first, and other classes are offered for rotations shared between
--     characters. A specialization of another class is always false.
[2728] = "La tua specializzazione dei talenti. Scegli una classe, poi una delle sue specializzazioni; la tua classe è selezionata per prima e le altre classi sono offerte per le rotazioni condivise tra personaggi. Una specializzazione di un'altra classe è sempre falsa.",
-- a449bf6b English: Retail and Mists of Pandaria Classic compare your active specialization.
--     Classic Era, Burning Crusade and Wrath compare your primary talent tree, the one tree with
--     the most points; Feral and Guardian both mean Feral Combat there. Forever cannot tell its
--     specializations apart this way. No specialization yet, tied or unspent trees and unreadable
--     values are unavailable, including under NOT. The answer is cached until your talents or
--     specialization change.
[2729] = "Retail e Mists of Pandaria Classic confrontano la tua specializzazione attiva. Classic Era, Burning Crusade e Wrath confrontano il tuo albero dei talenti principale, l'unico albero con più punti; Combattimento Ferino e Guardiano Ferino indicano entrambi Combattimento Ferino lì. Forever non riesce a distinguere le sue specializzazioni in questo modo. Nessuna specializzazione ancora, alberi in parità o senza punti spesi e valori illeggibili non sono disponibili, anche con NOT. La risposta viene memorizzata finché non cambiano i tuoi talenti o la tua specializzazione.",
-- 86569ac1 English: What is equipped in the main hand, off hand or ranged slot: nothing, any
--     weapon, a one-handed, two-handed or ranged weapon, a shield, an off-hand item, or one weapon
--     type such as Daggers. Types are read from the item's class and subclass, so they work in
--     every language. The answer is cached until your equipment changes.
[2730] = "Ciò che è equipaggiato nella mano principale, nella mano secondaria o nello slot a distanza: niente, qualsiasi arma, un'arma a una mano, a due mani o a distanza, uno scudo, un oggetto per la mano secondaria, oppure un tipo di arma preciso come i Pugnali. I tipi vengono letti dalla classe e dalla sottoclasse dell'oggetto, quindi funzionano in ogni lingua. La risposta viene memorizzata finché non cambia il tuo equipaggiamento.",
-- 96a5754f English: Dual wielding: off hand holds any weapon. Titan's Grip: off hand holds a
--     two-handed weapon. Backstab and Ambush: main hand holds Daggers. Shield Slam or a tank set:
--     off hand holds a shield. The ranged slot exists only before Mists of Pandaria; elsewhere, and
--     while item data is still loading, this condition is unavailable, including under NOT.
[2731] = "Doppia impugnatura: la mano secondaria regge qualsiasi arma. Presa del Titano: la mano secondaria regge un'arma a due mani. Colpo alle spalle e Imboscata: la mano principale regge Pugnali. Schiantare con lo scudo o un set da tank: la mano secondaria regge uno scudo. Lo slot a distanza esiste solo prima di Mists of Pandaria; altrove, e finché i dati dell'oggetto si stanno ancora caricando, questa condizione non è disponibile, anche con NOT.",
-- 0e0d00b2 English: Not on your action bars
[2732] = "Non sulle tue barre delle azioni",
-- c8117094 English: An amber border and warning mark a card whose action no action bar button holds
--     right now. Rotation Master highlights an action by lighting the button that holds it, so that
--     step is skipped (a cooldown is never shown) until you put it on a bar. The warning updates
--     when your bars change. Red still marks invalid data.
[2733] = "Un bordo ambra e un segnale di avviso indicano una scheda la cui azione non è contenuta in nessun pulsante delle barre delle azioni al momento. Rotation Master evidenzia un'azione illuminando il pulsante che la contiene, quindi quel passo viene saltato (un tempo di recupero non viene mai mostrato) finché non la metti su una barra. L'avviso si aggiorna quando le tue barre cambiano. Il rosso continua a indicare dati non validi.",
-- 2c7e6247 English: Actions must also be on an action bar: Rotation Master highlights an action by
--     lighting the button that holds it, so a step or cooldown that no button holds is skipped, and
--     its card shows an amber warning.
[2734] = "Le azioni devono anche trovarsi su una barra delle azioni: Rotation Master evidenzia un'azione illuminando il pulsante che la contiene, quindi un passo o un tempo di recupero che nessun pulsante contiene viene saltato, e la sua scheda mostra un avviso ambra.",
-- cc011249 English: Matches while the game says a boss encounter is in progress. Unlike the Boss
--     Mod Encounter condition it needs no boss mod, and it knows nothing of which boss or stage it
--     is. It starts when the encounter starts and ends on a kill, a wipe or a reset. It reads in
--     combat on every edition, Retail and Forever included.
[2735] = "Vale finché il gioco indica che è in corso uno scontro con un boss. A differenza della condizione Scontro del boss mod, non richiede alcun boss mod e non sa di quale boss o fase si tratti. Inizia con lo scontro e termina con una vittoria, un wipe o un reset. Si legge in combattimento in ogni edizione, Retail e Forever compresi.",
-- bec26f34 English: The level of the Mythic+ keystone you are running. It is 0 whenever you are not
--     in a Mythic+ dungeon, so 'at least 10' is only true inside a run of that level. Retail only.
[2736] = "Il livello della Chiave Mitica+ che stai affrontando. Vale 0 quando non sei in una spedizione Mitica+, quindi «almeno 10» è vero solo in una chiave di quel livello. Solo Retail.",
-- a4530fa7 English: The hero talent tree you have chosen. Pick a tree from the list, which shows
--     the trees of the rotation's specialization, or choose 'Any hero talent tree' to match once
--     you have chosen one. A tree can also be entered by its ID, to share a rotation with another
--     class. Below the level that offers hero talents, or before you pick a tree, no tree is
--     chosen. Retail only.
[2737] = "L'albero dei talenti eroe che hai scelto. Scegli un albero dall'elenco, che mostra gli alberi della specializzazione della rotazione, oppure «Qualsiasi albero dei talenti eroe» per verificare che ne sia stato scelto uno. Un albero si può anche inserire tramite il suo ID, per condividere una rotazione con un'altra classe. Sotto il livello che offre i talenti eroe, o prima di scegliere un albero, nessun albero è scelto. Solo Retail.",
-- 88cf82f7 English: Matches while the game shows the activation glow on this spell, the golden
--     border an action button gets when a proc makes the spell castable or stronger. It asks the
--     game directly, so it still reads when the buff behind the proc is hidden from addons in
--     combat. Choose the spell as it appears on your bars; its base and override forms are checked
--     too. Unavailable, never simply false, if the game cannot answer.
[2738] = "Vale finché il gioco mostra il bagliore di attivazione su questo incantesimo, il bordo dorato che un pulsante azione riceve quando un proc rende l'incantesimo lanciabile o più forte. Interroga direttamente il gioco, quindi si legge anche quando il potenziamento dietro il proc è nascosto agli addon in combattimento. Scegli l'incantesimo come appare sulle tue barre; vengono controllate anche le sue forme base e sostitutive. Non disponibile, mai semplicemente falsa, se il gioco non può rispondere.",
-- c9e6ec28 English: How happy your Hunter pet is: Unhappy, Content or Happy, as the game reports
--     it. No pet, or a pet that is not a Hunter pet, is in none of these moods. Classic Era,
--     Burning Crusade and Wrath only.
[2739] = "Quanto è felice il tuo famiglio da cacciatore: Infelice, Soddisfatto o Felice, come lo riporta il gioco. Nessun famiglio, o un famiglio che non è da cacciatore, non si trova in nessuno di questi stati. Solo Classic Era, Burning Crusade e Wrath.",
-- d6742b74 English: The damage waiting in your Brewmaster Monk's Stagger pool, or, with the box
--     ticked, that damage as a percent of your maximum health. Mists of Pandaria, Retail and
--     Forever only. On Retail and Forever the game can hide the pool from addons in combat, and
--     always hides maximum health, so the percent form is unavailable there and the amount is
--     unavailable whenever the game hides it; neither is ever guessed.
[2740] = "Il danno in attesa nell'accumulo di Stagger del tuo monaco Mastro Birraio o, con la casella spuntata, quel danno come percentuale della salute massima. Solo Mists of Pandaria, Retail e Forever. In Retail e Forever il gioco può nascondere l'accumulo agli addon in combattimento e nasconde sempre la salute massima, quindi la forma in percentuale lì non è disponibile e la quantità non è disponibile ogni volta che il gioco la nasconde; nulla viene mai stimato.",
-- 22cccaf0 English: Advise a spell even when you do not have the mana or other resource for it
--     right now. Without this, a spell you cannot afford is skipped like any other step that is not
--     ready. The spell must still be learned, off cooldown and usable for another reason, and its
--     conditions still apply.
[2741] = "Consiglia un incantesimo anche quando al momento non hai il mana o un'altra risorsa che richiede. Senza questa opzione, un incantesimo che non puoi permetterti viene saltato come qualsiasi altro passaggio non pronto. L'incantesimo deve comunque essere appreso, non in ricarica e utilizzabile per altri motivi, e le sue condizioni continuano ad applicarsi.",
-- 1bf91ced English: Retail and Forever can hide whether a spell is usable from addons in some
--     situations. The spell is then skipped whether or not this option is on.
[2742] = "Retail e Forever possono nascondere agli addon, in alcune situazioni, se un incantesimo è utilizzabile. L'incantesimo viene allora saltato, a prescindere da questa opzione.",
-- 0c4bd263 English: Advise a spell or item even when your target is out of its range. Without this,
--     a step whose range check fails is skipped. The spell or item must still be learned or owned,
--     off cooldown and usable, and its conditions still apply.
[2743] = "Consiglia un incantesimo o un oggetto anche quando il bersaglio è fuori portata. Senza questa opzione, un passaggio il cui controllo della portata fallisce viene saltato. L'incantesimo o l'oggetto deve comunque essere appreso o posseduto, non in ricarica e utilizzabile, e le sue condizioni continuano ad applicarsi.",
-- cb691e6c English: Adopt several at once
[2744] = "Adottarne più di una alla volta",
-- 6ac62581 English: Adopt all and Adopt all from specialization adopt every listed record in one
--     step, for the owner chosen under Applies to. Each record is adopted on its own, exactly as a
--     single adoption would be: a record whose destination already exists, or that is incomplete,
--     stays in the archive and is named in the result.
[2745] = "Adotta tutte e Adotta tutte della specializzazione adottano ogni record elencato in un solo passaggio, per il proprietario scelto in Si applica a. Ogni record viene adottato separatamente, esattamente come un'adozione singola: un record la cui destinazione esiste già, o che è incompleto, resta nell'archivio e viene indicato nel risultato.",
-- d3742617 English: the number of {item} you are carrying {comparison} {quantity}
[2746] = "il numero di {item} che porti con te {comparison} {quantity}",
