[3406] = "Rimuovi il marcatore",
-- 32436d10 English: Put on an action bar
[3407] = "Metti su una barra delle azioni",
-- eb8dfba9 English: Makes a macro that presses this step's hidden button, and picks it up. Drop it
--     on an action bar slot and Rotation Master lights it while this step is advised. In a raid
--     only the leader and assistants can place marks.
[3408] = "Crea una macro che preme il pulsante nascosto di questo passo e la prende. Rilasciala su uno slot della barra delle azioni e Rotation Master lo evidenzia finché questo passo è consigliato. In un raid solo il capo e gli assistenti possono mettere marcatori.",
-- 406b0045 English: Drag the macro %s to an action bar slot.
-- Context: Message after pressing Put on an action bar: the macro is now on the mouse cursor and
--     the player has to drop it on an action bar slot.
-- %s #1: the name of the macro that was created, e.g. "RM skull/tgt"
[3409] = "Trascina la macro %s su uno slot della barra delle azioni.",
-- 45a37997 English: Empty your cursor before binding.
[3410] = "Svuota il cursore prima di associare.",
-- 69f3d263 English: Your character macros are full, so the macro could not be made.
[3411] = "Le macro del tuo personaggio sono piene, quindi non è stato possibile creare la macro.",
-- b9f12561 English: Raid marks cannot be placed on this client.
[3412] = "I marcatori del raid non si possono mettere su questo client.",
-- 90c22683 English: The macro could not be made.
[3413] = "Non è stato possibile creare la macro.",
-- 19a35f5c English: Recommends pressing a macro that places the raid mark
[3414] = "Consiglia di premere una macro che mette il marcatore del raid",
-- 2dacd008 English: uses a Set Mark step this client cannot run
[3415] = "usa un passo Imposta marcatore che questo client non può eseguire",
-- bd3e44b0 English: uses Set Mark, which only works in the rotation list
[3416] = "usa Imposta marcatore, che funziona solo nella lista della rotazione",
-- 0d936a8d English: /rm debug marks - Report the raid mark table and what each mark unit resolves
--     to.
[3417] = "/rm debug marks - Riporta la tabella dei marcatori del raid e in cosa si risolve ogni unità marcatore.",
-- 42f0cd37 English: Any mark
-- Context: Choice in the mark dropdown of the Raid Mark condition: the unit carries any raid
--     marker.
[3418] = "Qualsiasi marcatore",
-- 1bc1f1c6 English: No mark
-- Context: Choice in the mark dropdown of the Raid Mark condition: the unit carries no raid marker.
[3419] = "Nessun marcatore",
-- 36baf150 English: One of these marks
[3420] = "Uno di questi marcatori",
-- 582de115 English: %s {{!have|do not have}} a raid mark
-- Context: Sentence the Raid Mark condition prints. Used when the unit is the player ("you"). The
--     {{!positive|negated}} part is the wording for the condition and for its NOT form.
-- %s #1: the unit phrase, e.g. "your target"
[3421] = "%s {{!hai|non hai}} un marcatore del raid",
-- 472cb18e English: %s {{!has|does not have}} a raid mark
-- Context: Sentence the Raid Mark condition prints. Used when the unit is anyone else (third
--     person, "has"). The {{!positive|negated}} part is the wording for the condition and for its
--     NOT form.
-- %s #1: the unit phrase, e.g. "your target"
[3422] = "%s {{!ha|non ha}} un marcatore del raid",
-- 4235af62 English: %s {{!have no|have a}} raid mark
-- Context: Sentence the Raid Mark condition prints. Used when the unit is the player ("you"). The
--     {{!positive|negated}} part is the wording for the condition and for its NOT form.
-- %s #1: the unit phrase, e.g. "your target"
[3423] = "%s {{!non hai alcun|hai un}} marcatore del raid",
-- 4f17a484 English: %s {{!has no|has a}} raid mark
-- Context: Sentence the Raid Mark condition prints. Used when the unit is anyone else (third
--     person, "has"). The {{!positive|negated}} part is the wording for the condition and for its
--     NOT form.
-- %s #1: the unit phrase, e.g. "your target"
[3424] = "%s {{!non ha alcun|ha un}} marcatore del raid",
-- a8bca387 English: %s {{!have|do not have}} one of these marks: %s
-- Context: Sentence the Raid Mark condition prints when several marks are ticked. Used when the
--     unit is the player ("you"). The {{!positive|negated}} part is the wording for the condition
--     and for its NOT form.
-- %s #1: the unit phrase, e.g. "your target"
-- %s #2: the marks to match, comma separated, in the game's names, e.g. "Skull, Moon"
[3425] = "%s {{!hai|non hai}} uno di questi marcatori: %s",
-- ed95df2d English: %s {{!has|does not have}} one of these marks: %s
-- Context: Sentence the Raid Mark condition prints when several marks are ticked. Used when the
--     unit is anyone else (third person, "has"). The {{!positive|negated}} part is the wording for
--     the condition and for its NOT form.
-- %s #1: the unit phrase, e.g. "your target"
-- %s #2: the marks to match, comma separated, in the game's names, e.g. "Skull, Moon"
[3426] = "%s {{!ha|non ha}} uno di questi marcatori: %s",
-- c8ca4b13 English: %s {{!have|do not have}} the %s mark
-- Context: Sentence the Raid Mark condition prints when exactly one mark is ticked. Used when the
--     unit is the player ("you"). The {{!positive|negated}} part is the wording for the condition
--     and for its NOT form.
-- %s #1: the unit phrase, e.g. "your target"
-- %s #2: the game's name of the one mark, e.g. "Skull"
[3427] = "%s {{!hai|non hai}} il marcatore %s",
-- 8c22e3b7 English: %s {{!has|does not have}} the %s mark
-- Context: Sentence the Raid Mark condition prints when exactly one mark is ticked. Used when the
--     unit is anyone else (third person, "has"). The {{!positive|negated}} part is the wording for
--     the condition and for its NOT form.
-- %s #1: the unit phrase, e.g. "your target"
-- %s #2: the game's name of the one mark, e.g. "Skull"
[3428] = "%s {{!ha|non ha}} il marcatore %s",
-- 58d8289e English: the number of marked units
[3429] = "il numero di unità marcate",
-- e5568f80 English: the number of marked enemy units
[3430] = "il numero di unità nemiche marcate",
-- 0112a03e English: the number of marked friendly units
[3431] = "il numero di unità amichevoli marcate",
-- e2490322 English: Marked units
-- Context: Choice in the Count dropdown of the Raid Mark Count condition: count every unit that
--     carries a marker.
[3432] = "Unità marcate",
-- cfc9ed3d English: Marked enemies
-- Context: Choice in the Count dropdown of the Raid Mark Count condition: count only marked units
--     the player can attack.
[3433] = "Nemici marcati",
-- e9c0dcf1 English: Marked friendly units
-- Context: Choice in the Count dropdown of the Raid Mark Count condition: count only marked units
--     that are friendly.
[3434] = "Unità amichevoli marcate",
-- 205bd60c English: A number from 0 to 8: there are eight marks, and a unit carries at most one.
[3435] = "Un numero da 0 a 8: i marcatori sono otto e un'unità ne porta al massimo uno.",
-- 6bc4e7b1 English: Matches while the unit carries a raid target marker. Choose Any mark, No mark,
--     or One of these marks and tick the marks you want (skull, cross, square, moon, triangle,
--     diamond, circle, star). A unit that does not exist never matches, not even for No mark. Where
--     the game hides a marker (Retail and Forever restrict some data in combat) the condition is
--     unavailable, also under NOT, never false. To act on whichever unit carries a mark, pick the
--     mark itself as the Unit of another condition: Skull, Cross and the rest, or the
--     highest-priority marked unit, which tries skull first and star last.
[3436] = "Vale finché l'unità porta un marcatore del raid. Scegli Qualsiasi marcatore, Nessun marcatore o Uno di questi marcatori e spunta quelli che vuoi (teschio, croce, quadrato, luna, triangolo, diamante, cerchio, stella). Un'unità che non esiste non corrisponde mai, nemmeno a Nessun marcatore. Dove il gioco nasconde un marcatore (Retail e Forever limitano alcuni dati in combattimento) la condizione non è disponibile, anche sotto NON, e mai falsa. Per agire sull'unità che porta un marcatore, scegli il marcatore stesso come Unità di un'altra condizione: Teschio, Croce e gli altri, oppure l'unità marcata con la priorità più alta, che prova prima il teschio e per ultima la stella.",
-- 74adf719 English: Counts the marked units Rotation Master knows of. It finds them on your target,
--     focus, mouseover, nameplates, group members and their targets, bosses and arena opponents
--     each time a mark changes, so a marked unit you cannot reach right now still counts until the
--     mark is seen to be gone or you leave the area. Count every marked unit, only enemies, or only
--     friendly units. If a marker cannot be read, or a unit's hostility is unknown for the filter
--     you chose, the condition is unavailable, also under NOT. A unit carries at most one mark, so
--     the count is never more than eight.
[3437] = "Conta le unità marcate che Rotation Master conosce. Le trova sul tuo bersaglio, sul focus, sul mouseover, sulle targhette dei nomi, sui membri del gruppo e i loro bersagli, sui boss e sugli avversari dell'arena a ogni cambio di marcatore; un'unità marcata fuori portata continua quindi a contare finché il marcatore non risulta rimosso o non lasci la zona. Conta tutte le unità marcate, solo i nemici o solo le unità amichevoli. Se un marcatore non si può leggere, o l'ostilità di un'unità è sconosciuta per il filtro scelto, la condizione non è disponibile, anche sotto NON. Un'unità porta al massimo un marcatore, quindi il conteggio non supera mai otto.",
-- b5559325 English: When its conditions match, attempts to set or clear the selected raid marker on
--     the chosen unit, then continues to the next rotation step.
[3438] = "Quando le condizioni sono soddisfatte, tenta di assegnare o rimuovere il contrassegno incursione scelto sull’unità selezionata, poi passa al passo successivo della rotazione.",
-- d607ecc3 English: Include disabled rotations
-- Context: Check box on the General settings page, Tooltips section. On: spell and item tooltips
--     also list rotations that are switched off (grayed, marked disabled). Off: only rotations that
--     are on are listed.
[3439] = "Includi le rotazioni disattivate",
-- e1738cc8 English: Exclude disabled conditions
-- Context: Check box on the General settings page, Tooltips section, next to 'Include rotation
--     conditions'. On: a condition that is switched off in the rotation editor is not counted when
--     tooltips list the rotations that use a spell or item.
[3440] = "Escludi le condizioni disattivate",
-- e3334d5c English: Also list the rotations for your current specialization that are switched off,
--     dimmed and marked disabled, after the ones that are on. Turn this off to list only rotations
--     that are on; the "(+N more)" count then leaves the switched-off ones out too.
[3441] = "Elenca anche le rotazioni della tua specializzazione attuale che sono spente, attenuate e contrassegnate come disattivate, dopo quelle attive. Disattiva questa opzione per elencare solo le rotazioni attive; il conteggio \"(+N altri)\" esclude allora anche quelle spente.",
-- 766abde1 English: With rotation conditions included, leave out any condition that is switched off
--     in the rotation editor, together with everything under it, because a disabled condition no
--     longer affects the rotation. Off by default: a spell or item that appears only in a disabled
--     condition still counts.
[3442] = "Con le condizioni delle rotazioni incluse, omette ogni condizione spenta nell'editor delle rotazioni, insieme a tutto ciò che contiene, perché una condizione disattivata non influisce più sulla rotazione. Disattivato di default: un incantesimo o un oggetto che compare solo in una condizione disattivata viene comunque contato.",
-- 9d030584 English: Unit Exists
[3443] = "Unità esistente",
-- 57e392e8 English: {unit} {{!exists|does not exist}}
[3444] = "{unit} {{!esiste|non esiste}}",
-- 8dfc9fc3 English: Matches when the selected unit exists. A marked unit exists when that mark is
--     known, even if the unit is currently out of reach.
[3445] = "Corrisponde se l’unità scelta esiste. Un’unità contrassegnata esiste se il contrassegno è noto, anche fuori portata.",
-- ab06b6f8 English: Highest priority unset
[3446] = "Priorità libera più alta",
-- da73f55a English: Raid Role
[3447] = "Ruolo incursione",
-- 7c968fb7 English: Member
[3448] = "Membro",
-- 391e4051 English: Assistant
[3449] = "Assistente",
-- 3f53871b English: Leader
[3450] = "Capo",
-- 901e4ca6 English: you {{!are|are not}} a raid %s
[3451] = "{{!sei|non sei}} %s dell’incursione",
-- 8aee3f95 English: Matches your role in a raid: member, assistant or leader. Outside a raid it
--     does not match.
[3452] = "Corrisponde al tuo ruolo nell’incursione: membro, assistente o capo. Fuori da un’incursione non corrisponde.",
